  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('T3A-D3-EXEC-001-CONSTRUCT', 'construct'::public.t3a_content_family, 'D3 construct', 'D3', 'not_applicable'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.0', 'drafting', 'not_applicable'::public.t3a_operational_state, '{"situation_classes": {"SC-D3-1": {"situation": "More work is required within the available time than the source establishes can be done", "pattern_family": "IPF-D3-01"}, "SC-D3-2": {"situation": "A resource, tool or system the work depends on is unavailable", "pattern_family": "IPF-D3-02"}, "SC-D3-3": {"situation": "The deadline or the scope moves after work has begun", "pattern_family": "IPF-D3-03"}, "SC-D3-4": {"situation": "The deliverable can be completed only in part", "pattern_family": "IPF-D3-04"}, "SC-D3-5": {"situation": "Work cannot proceed until something outside the participant''s control moves", "pattern_family": "IPF-D3-05"}, "SC-D3-6": {"situation": "The work arrives without a specification sufficient to complete it", "pattern_family": "IPF-D3-06"}, "SC-D3-7": {"situation": "Work is received from, or passed to, another party in an incomplete state", "pattern_family": "IPF-D3-07"}}, "conduct_elements": {"CE-D3-01": {"name": "Order of work", "supports": "A stated sequence is recoverable from the record and is the least interpretive fact available about a delivery decision", "does_not_support": "Does not support any claim that the order was correct, efficient or well judged, and never supports a comparison with another order"}, "CE-D3-02": {"name": "Reduction", "supports": "The source lists the components before observation, so the selection is bounded and not invented by the mentor", "does_not_support": "Does not support a claim that the right part was cut, or that cutting was necessary"}, "CE-D3-03": {"name": "Protection", "supports": "Holding one requirement while another gives is a distinct observable decision from reducing", "does_not_support": "Does not support a claim about values, priorities as a disposition, or what the participant cares about"}, "CE-D3-04": {"name": "Verification before handover", "supports": "The source designates the checks available; whether one was run is a fact", "does_not_support": "Does not support a claim that the verification was adequate, nor any inference from its absence about care"}, "CE-D3-05": {"name": "Use of available means", "supports": "Means are pre-listed by the source with their in-session performability, so use is observable rather than judged", "does_not_support": "Does not support a claim that the means chosen was the best available, or that not using one was a failure"}, "CE-D3-06": {"name": "Action on the blocking dependency", "supports": "A dependency outside the participant''s control is established before observation, so acting on it is bounded", "does_not_support": "Does not support a claim about persistence, initiative or escalation judgment, and never supports a statement about the party holding the dependency"}, "CE-D3-07": {"name": "Identification of gaps at handover", "supports": "Handing over with gaps identified is part of delivering. It is distinct from D2''s disclosure of a shortfall to an affected party, which D3 does not observe", "does_not_support": "Does not support a claim about transparency or candour, and does not support any statement about who was told"}, "CE-D3-08": {"name": "Response to a moved standard", "supports": "The move is authored into the source, so the opportunity is identical for every participant", "does_not_support": "Does not support a claim about adaptability or flexibility, and does not support a judgment of whether the move should have been accepted"}, "CE-D3-09": {"name": "Conduct when the delivery state was put to the participant", "supports": "The test point is authored into the source, so the opportunity is identical for every participant", "does_not_support": "Does not support a claim about composure, defensiveness or honesty"}}, "coverage": {"CE-D3-01": ["Carried", "Carried", "Carried", "Carried"], "CE-D3-02": ["Carried", "Carried", "Carried", "Carried"], "CE-D3-03": ["Carried", "Carried", "Carried", "Carried"], "CE-D3-04": ["Carried", "Carried", "Carried", "Carried"], "CE-D3-05": ["Carried", "Carried", "Carried", "Carried"], "CE-D3-06": ["Carried", "Carried", "Carried", "Carried"], "CE-D3-07": ["Carried", "Carried", "Carried", "Carried"], "CE-D3-08": ["Carried", "Carried", "NOT IN LAUNCH DESIGN", "Carried"], "CE-D3-09": ["Carried", "Carried", "NOT IN LAUNCH DESIGN", "Carried"]}, "source_fields": {"permitted_administration_variance": {"type": "text", "stages": "1, 2, 3, 4", "holds": "The administration variance the source permits, recorded wherever it occurs"}, "unsupported_inferences": {"type": "text", "stages": "1, 2, 3, 4", "holds": "The inferences the source must never support"}, "compatibility_class": {"type": "text", "stages": "1, 2, 3, 4", "holds": "The delivery form class of the source, derived from its Stage"}, "work_items": {"type": "list: WI, mapped", "stages": "1, 2, 3, 4", "holds": "The items of work the source places before the participant, each quoted in the material map"}, "deliverable_components": {"type": "list: DC", "stages": "1, 2, 3, 4", "holds": "The named parts of the deliverable; consumed by Q-D3-02b, Q-D3-07b and Q-D3-09, each as its own determination"}, "stated_requirements": {"type": "list: SR, mapped", "stages": "1, 2, 3, 4", "holds": "The requirements the source states, the standard against which delivery is recorded, each quoted in the material map"}, "available_checks": {"type": "list: CK", "stages": "1, 2, 3, 4", "holds": "The verification steps the source makes available that Q-D3-04b may offer"}, "available_means": {"type": "list: MN", "stages": "1, 2, 3, 4", "holds": "The tools, routes, authorities or resources the source makes available that Q-D3-05b may offer"}, "time_available": {"type": "text", "stages": "1, 2, 3, 4", "holds": "What the source establishes is available, with its exact text where it gives one"}, "work_required": {"type": "text", "stages": "1, 2, 3, 4", "holds": "What the source establishes is required, with its exact text where it gives one"}, "blocking_dependency": {"type": "text", "stages": "1, 2, 3, 4", "holds": "The thing the source establishes the participant does not control, or None"}, "dependency_holder_role": {"type": "text", "stages": "1, 2, 3, 4", "holds": "The role holding the dependency, retained for source truth and never rendered, or None"}, "moved_standard_point": {"type": "text", "stages": "1, 2, 4", "holds": "The point at which the source moves the deadline or scope, or None"}, "handover_point": {"type": "text", "stages": "1, 2, 3, 4", "holds": "The point at which the deliverable passes out of the participant''s hands, or None"}, "delivery_state_record": {"type": "text", "stages": "1, 2, 4", "holds": "The source''s own record of what was and was not complete at the delivery test point, against which Q-D3-09 is recorded"}, "delivery_test_point": {"type": "point: Account test", "stages": "1, 2, 4", "holds": "The reveal or beat at which the recorded delivery state is put to the participant, or None"}, "list_note": {"type": "text", "stages": "1, 2, 3, 4", "holds": "Why a list is empty, and any item withheld from a list as a character statement or as not selectable, or None"}, "source_note": {"type": "text", "stages": "1, 2, 3, 4", "holds": "A shared situation, a shared Stage 3 submission or other situation context the source carries, or None"}, "situation_class_label": {"type": "text", "stages": "1, 2, 3, 4", "holds": "One approved generic phrase naming the kind of situation, its time sensitivity or consequence and the information available; never the source title or scenario detail"}, "observation_mode_label": {"type": "enum: written_response, structured_live_session, work_sample, group_session", "stages": "1, 2, 3, 4", "holds": "The observation mode of the Stage at which the source is served"}}, "source": "T3A-D3-EXEC-001 v2.0"}'::jsonb from public.t3a_content_object where identifier = 'T3A-D3-EXEC-001-CONSTRUCT' and family = 'construct'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('T3A-D3-EXEC-001-DETERMINATION', 'determination_question_set'::public.t3a_content_family, 'D3 determination set', 'D3', 'not_applicable'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.0', 'drafting', 'not_applicable'::public.t3a_operational_state, '{"questions": {"Q-D3-01": {"element": "CE-D3-01", "capture_set": "C1", "answer_type": "Single select, fixed", "source_bound_to": "—", "served_when": "Always where the element is in play"}, "Q-D3-01b": {"element": "CE-D3-01", "capture_set": "C1b", "answer_type": "Bound selection, one or more", "source_bound_to": "work_items", "served_when": "C1 records a first item or a sequence"}, "Q-D3-02": {"element": "CE-D3-02", "capture_set": "C2", "answer_type": "Single select, fixed", "source_bound_to": "—", "served_when": "Always where the element is in play"}, "Q-D3-02b": {"element": "CE-D3-02", "capture_set": "C2b", "answer_type": "Bound selection, one or more", "source_bound_to": "deliverable_components", "served_when": "C2 records a part reduced, deferred or dropped"}, "Q-D3-03": {"element": "CE-D3-03", "capture_set": "C3", "answer_type": "Single select, fixed", "source_bound_to": "—", "served_when": "Source carries stated_requirements"}, "Q-D3-03b": {"element": "CE-D3-03", "capture_set": "C3b", "answer_type": "Bound selection, one or more", "source_bound_to": "stated_requirements", "served_when": "C3 records a specific requirement held"}, "Q-D3-04": {"element": "CE-D3-04", "capture_set": "C4", "answer_type": "Single select, fixed", "source_bound_to": "—", "served_when": "Source carries available_checks"}, "Q-D3-04b": {"element": "CE-D3-04", "capture_set": "C4b", "answer_type": "Bound selection, one or more", "source_bound_to": "available_checks", "served_when": "C4 records a check performed or stated"}, "Q-D3-05": {"element": "CE-D3-05", "capture_set": "C5", "answer_type": "Single select, fixed", "source_bound_to": "—", "served_when": "Source carries available_means"}, "Q-D3-05b": {"element": "CE-D3-05", "capture_set": "C5b", "answer_type": "Bound selection, one or more", "source_bound_to": "available_means", "served_when": "C5 records a means used or stated"}, "Q-D3-06a": {"element": "CE-D3-06", "capture_set": "C6a", "answer_type": "Single select, fixed", "source_bound_to": "—", "served_when": "Source carries a blocking dependency"}, "Q-D3-06b": {"element": "CE-D3-06", "capture_set": "C6b", "answer_type": "Single select, fixed", "source_bound_to": "—", "served_when": "Source carries a blocking dependency"}, "Q-D3-07": {"element": "CE-D3-07", "capture_set": "C7", "answer_type": "Single select, fixed", "source_bound_to": "—", "served_when": "Source carries handover_point"}, "Q-D3-07b": {"element": "CE-D3-07", "capture_set": "C7b", "answer_type": "Bound selection, one or more", "source_bound_to": "deliverable_components", "served_when": "C7 records incomplete parts identified"}, "Q-D3-08": {"element": "CE-D3-08", "capture_set": "C8", "answer_type": "Single select, fixed", "source_bound_to": "—", "served_when": "Source carries a moved standard"}, "Q-D3-09": {"element": "CE-D3-09", "capture_set": "C9", "answer_type": "Bound selection, one or more", "source_bound_to": "deliverable_components", "served_when": "Source carries delivery_test_point"}}, "capture_sets": {"C1": {"title": "What the participant stated about the order of the work", "lines": ["Named a specific first item of work.", "Named a sequence of two or more items in order.", "Stated that the items would be worked on together.", "Stated no order for the work during the observation."], "bound": null, "type": "content", "whole_session": "Stated no order for the work during the observation."}, "C1b": {"title": "Which of the work items were placed in the stated order", "lines": ["LISTED Selected, in the stated order, each listed item the participant placed.", "ORDERED_UNLISTED_ITEM Placed an item outside the list and none of the listed items.", "LISTED + ORDERED_UNLISTED_ITEM Selected, in the stated order, the listed items placed and an item outside the list."], "bound": {"field": "work_items", "selection": "one or more"}, "type": "content", "whole_session": "—"}, "C2": {"title": "Whether a part of the deliverable was reduced, deferred or dropped", "lines": ["A specific part of the deliverable was reduced or narrowed.", "A specific part of the deliverable was deferred to a later point.", "A specific part of the deliverable was dropped.", "No part of the deliverable was reduced, deferred or dropped during the observation."], "bound": null, "type": "content", "whole_session": "No part of the deliverable was reduced, deferred or dropped during the observation."}, "C2b": {"title": "Which deliverable components were reduced, deferred or dropped", "lines": ["LISTED Selected each listed component that was reduced, deferred or dropped.", "AFFECTED_UNLISTED_COMPONENT A component outside the list was affected and none of the listed components.", "LISTED + AFFECTED_UNLISTED_COMPONENT Selected the listed components affected and a component outside the list."], "bound": {"field": "deliverable_components", "selection": "one or more"}, "type": "content", "whole_session": "—"}, "C3": {"title": "Which stated requirement was held intact", "lines": ["Stated a specific requirement as held intact.", "Stated every requirement as held intact.", "Stated no requirement as held intact during the observation."], "bound": null, "type": "content", "whole_session": "Stated no requirement as held intact during the observation."}, "C3b": {"title": "Which requirements were stated as held intact", "lines": ["LISTED Selected each listed requirement stated as held intact.", "HELD_UNLISTED_REQUIREMENT Stated a requirement outside the list as held and none of the listed requirements."], "bound": {"field": "stated_requirements", "selection": "one or more"}, "type": "content", "whole_session": "—"}, "C4": {"title": "Whether a check against the stated standard was performed or stated", "lines": ["Performed a check or evidenced one in the work.", "Stated a check without performing or evidencing one.", "Performed no check and stated none during the observation."], "bound": null, "type": "content", "whole_session": "Performed no check and stated none during the observation."}, "C4b": {"title": "Which checks were performed or stated", "lines": ["LISTED Selected each listed check performed or stated.", "UNLISTED_CHECK_IDENTIFIED Identified a check outside the list and none of the listed checks.", "LISTED + UNLISTED_CHECK_IDENTIFIED Selected the listed checks performed or stated and a check outside the list."], "bound": {"field": "available_checks", "selection": "one or more"}, "type": "content", "whole_session": "—"}, "C5": {"title": "Whether a means the source makes available was used", "lines": ["Used one or more of the listed means.", "Stated a means without using one of those the source makes available.", "Stated that no means would be used.", "Used no means and stated none during the observation."], "bound": null, "type": "content", "whole_session": "Used no means and stated none during the observation."}, "C5b": {"title": "Which means were used or stated", "lines": ["LISTED Selected each listed means used or stated.", "UNLISTED_MEANS_IDENTIFIED Identified a means outside the list and none of the listed means.", "LISTED + UNLISTED_MEANS_IDENTIFIED Selected the listed means used or stated and a means outside the list."], "bound": {"field": "available_means", "selection": "one or more"}, "type": "content", "whole_session": "—"}, "C6a": {"title": "Whether an action on the blocking dependency was performed, evidenced or stated", "lines": ["Performed or evidenced an action on the dependency.", "Stated an action on the dependency without performing one.", "Performed, evidenced and stated no action on the dependency during the observation."], "bound": null, "type": "content", "whole_session": "Performed, evidenced and stated no action on the dependency during the observation."}, "C6b": {"title": "What happened to the work while the dependency remained", "lines": ["Reordered the work to proceed around the dependency.", "Held the work pending the dependency.", "Continued the work with no change made for the dependency.", "No work depending on the item remained during the observation."], "bound": null, "type": "content", "whole_session": "No work depending on the item remained during the observation."}, "C7": {"title": "Whether the work was handed over with its incomplete parts identified", "lines": ["Handed over the work with its incomplete parts identified.", "Handed over the work with some incomplete parts identified and others not.", "Handed over the work with no incomplete parts identified.", "Did not hand over the work during the observation."], "bound": null, "type": "content", "whole_session": "Did not hand over the work during the observation."}, "C7b": {"title": "Which incomplete components were identified on the handover", "lines": ["LISTED Selected each listed component identified as incomplete on the handover.", "IDENTIFIED_NO_LISTED_COMPONENT Identified incomplete parts and none of the listed components."], "bound": {"field": "deliverable_components", "selection": "one or more"}, "type": "content", "whole_session": "—"}, "C8": {"title": "What was done with the work already performed when the requirement changed", "lines": ["Kept the work already done and continued from it.", "Set the work already done aside and began again.", "Kept part of the work already done.", "Made no change to the work after the requirement changed."], "bound": null, "type": "content", "whole_session": "—"}, "C9": {"title": "What the participant stated when the delivery state was put to them", "lines": ["MATCHED_ALL Stated every component as the source records it.", "MATCHED_ALL_WITH_OUTSTANDING Stated every component as the source records it and stated what remained outstanding.", "LISTED:OVERSTATED Selected each component stated as further along than the source records, and marked none less far along.", "LISTED:UNDERSTATED Selected each component stated as less far along than the source records, and marked none further along.", "LISTED:OVERSTATED + LISTED:UNDERSTATED Selected the components stated as further along and those stated as less far along than the source records.", "NO_POSITION_STATED Stated no position during the observation."], "bound": {"field": "deliverable_components", "selection": "one or more"}, "type": "content", "whole_session": "NO_POSITION_STATED Stated no position during the observation."}}, "branch_rules": {"BR-D3-01": {"child": "Q-D3-01b", "parent": "Q-D3-01", "serving_answers": ["A1", "A2"], "note": "Which items were placed exists only once a first item or a sequence was stated"}, "BR-D3-02": {"child": "Q-D3-02b", "parent": "Q-D3-02", "serving_answers": ["A1", "A2", "A3"], "note": "Which components were affected exists only once a part was reduced, deferred or dropped"}, "BR-D3-03": {"child": "Q-D3-03b", "parent": "Q-D3-03", "serving_answers": ["A1"], "note": "Which requirement was held exists only once a specific requirement was stated as held"}, "BR-D3-04": {"child": "Q-D3-04b", "parent": "Q-D3-04", "serving_answers": ["A1", "A2"], "note": "Which checks exists only once a check was performed or stated"}, "BR-D3-05": {"child": "Q-D3-05b", "parent": "Q-D3-05", "serving_answers": ["A1", "A2"], "note": "Which means exists only once a means was used or stated"}, "BR-D3-06": {"child": "Q-D3-07b", "parent": "Q-D3-07", "serving_answers": ["A1", "A2"], "note": "Which components were identified exists only once incomplete parts were identified"}}, "source": "T3A-D3-EXEC-001 v2.0"}'::jsonb from public.t3a_content_object where identifier = 'T3A-D3-EXEC-001-DETERMINATION' and family = 'determination_question_set'::public.t3a_content_family;
