  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D3-S1-001', 'source'::public.t3a_content_family, 'THREE REQUESTS BEFORE ELEVEN', 'D3', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.0', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 1, "title": "THREE REQUESTS BEFORE ELEVEN", "source_digest": "436a5d6a8349d094ac23fbcd5d5915b71dc06c3fd677bfff2ebb7bc0692bd7fb", "situation": "You are an operations coordinator. It is Monday at 9:15 AM. Three requests arrived in the last thirty minutes.\n\nYour supervisor, at 8:50 AM: the vendor cost comparison needs updating by 11:00 AM for a leadership meeting. About ninety minutes of work.\n\nThe client services team, at 9:00 AM: the client organization says its invoice is wrong and is threatening to withhold payment. About forty-five minutes of work.\n\nThe technology department, at 8:45 AM: the shared drive migration runs at noon, and every department must confirm its files are backed up by 11:30 AM or risk data loss. About sixty minutes of work.\n\nYou have one hour and forty-five minutes before the 11:00 AM deadline and two hours and fifteen minutes before the 11:30 AM deadline. The three tasks take about three hours and fifteen minutes. You cannot complete all three before their stated times.", "reveals": [{"code": "R1", "text": "What do you do first, and in what order do you take the three?", "role": "Opening"}, {"code": "R2", "text": "One hour forty-five to the first deadline and three hours fifteen of work. What gives, and what does not?", "role": "Information"}, {"code": "R3", "text": "For the items you do complete, what do you check before you send them?", "role": "Information"}, {"code": "R4", "text": "For any item you do not complete on time, what happens to it and how does it go out?", "role": "Information"}, {"code": "R5", "text": "At 11:05 AM your supervisor writes: \"Just so I have it right — which of the three is done and which is not?\" What is your answer?", "role": "Account test"}], "question_applicability": [{"question": "Q-D3-01", "state": "DIRECT", "basis": "Three items, a stated gap between time and work. R2 creates the opportunity"}, {"question": "Q-D3-01b", "state": "CONDITIONAL", "basis": "work_items holds three. THE ORDER IS PERSISTED AS A SEQUENCE"}, {"question": "Q-D3-02", "state": "DIRECT", "basis": "R3 asks what gives"}, {"question": "Q-D3-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-03", "state": "DIRECT", "basis": "Two stated requirements that cannot both hold with the third item"}, {"question": "Q-D3-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-04", "state": "DIRECT", "basis": "R4 asks what is checked"}, {"question": "Q-D3-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-05", "state": "DIRECT", "basis": "Three means available"}, {"question": "Q-D3-05b", "state": "CONDITIONAL", "basis": "SERVED at this Stage in identifying form"}, {"question": "Q-D3-06a", "state": "NOT SERVED", "basis": "blocking_dependency is an explicit none. NO ANSWER ROW, NO MISSING-STATE CODE"}, {"question": "Q-D3-06b", "state": "NOT SERVED", "basis": "blocking_dependency is an explicit none. NO ANSWER ROW, NO MISSING-STATE CODE"}, {"question": "Q-D3-07", "state": "DIRECT", "basis": "R5 asks how the incomplete item goes out"}, {"question": "Q-D3-07b", "state": "CONDITIONAL", "basis": "Draws on the SAME family as Q-D3-02b, captured independently"}, {"question": "Q-D3-08", "state": "NOT SERVED", "basis": "The situation presents no change to the requirement"}, {"question": "Q-D3-09", "state": "DIRECT", "basis": "delivery_test_point at R6"}], "material_map": [{"Item": "WI1", "Item text": "update the vendor cost comparison — about ninety minutes, due 11:00 AM", "Where the participant meets it": "The situation", "Quoted text": "vendor cost comparison needs"}, {"Item": "WI2", "Item text": "investigate the invoice dispute — about forty-five minutes", "Where the participant meets it": "The situation", "Quoted text": "the client organization says its invoice is wrong"}, {"Item": "WI3", "Item text": "confirm the department backup — about sixty minutes, due 11:30 AM", "Where the participant meets it": "The situation", "Quoted text": "sixty minutes of work"}, {"Item": "SR1", "Item text": "the cost comparison reaches the supervisor by 11:00 AM", "Where the participant meets it": "The situation", "Quoted text": "supervisor, at 8:50 AM: the vendor cost comparison"}, {"Item": "SR2", "Item text": "the backup is confirmed by 11:30 AM", "Where the participant meets it": "The situation", "Quoted text": "confirm its files are backed up by 11:30 AM"}], "source_sheet": {"d3_situation_class": "SC-D3-1", "workplace_demand": "Ordering three commitments that do not fit the available time.", "relevant_conduct": "The order stated; what was reduced, deferred or dropped; what was stated as held; which checks were named; which means were named; what was said about the incomplete item at handover; the answer at R5.", "irrelevant_conduct": "Whether the order chosen was the right one; the substance of the invoice error; opinions about short-notice requests.", "stated_standard": "\"confirm its files are backed up by 11:30 AM or risk data loss\" and \"by 11:00 AM for a leadership meeting.\" Exact participant-facing text at the situation. NOTHING IN THE SOURCE RANKS THE THREE, and no ranking may be assumed.", "stated_standard_source_quote_or_location": "\"confirm its files are backed up by 11:30 AM or risk data loss\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Reveal order fixed. Screen-reader and extended-time accommodations permitted and recorded.", "unsupported_inferences": "That any ordering is correct; that the client matter outranks the backup; anything about how the participant handles pressure as a trait.", "compatibility_class": "S1-WRITTEN-SEQUENTIAL", "work_items": [{"id": "WI1", "text": "update the vendor cost comparison — about ninety minutes, due 11:00 AM"}, {"id": "WI2", "text": "investigate the invoice dispute — about forty-five minutes"}, {"id": "WI3", "text": "confirm the department backup — about sixty minutes, due 11:30 AM"}], "deliverable_components": [{"id": "DC1", "text": "the vendor cost comparison"}, {"id": "DC2", "text": "the invoice correction"}, {"id": "DC3", "text": "the backup confirmation"}], "stated_requirements": [{"id": "SR1", "text": "the cost comparison reaches the supervisor by 11:00 AM"}, {"id": "SR2", "text": "the backup is confirmed by 11:30 AM"}], "available_checks": [{"id": "CK1", "text": "reconcile the cost comparison against the vendor quotes"}, {"id": "CK2", "text": "confirm the backup completed rather than that it was started"}], "available_means": [{"id": "MN1", "text": "ask the client services team to hold the invoice matter until after 11:30 AM"}, {"id": "MN2", "text": "send the cost comparison partly updated and identify what is not updated"}, {"id": "MN3", "text": "ask the supervisor which of the three should give"}], "time_available": "\"one hour and forty-five minutes before the 11:00 AM deadline and two hours and fifteen minutes before the 11:30 AM deadline.\" Exact text at the situation.", "work_required": "\"about three hours and fifteen minutes.\" Exact text at the situation.", "blocking_dependency": null, "dependency_holder_role": null, "moved_standard_point": null, "handover_point": "11:00 AM and 11:30 AM.", "delivery_state_record": "At R5: the source establishes only that three hours fifteen of work did not fit in two hours forty-five. WHICH ITEMS ARE COMPLETE DEPENDS ON THE PARTICIPANT''S OWN STATED ORDER, and the determination compares the answer at R5 against what they stated at R1 and R2.", "delivery_test_point": "R5", "list_note": null, "source_note": "blocking_dependency: Every item is within the participant''s own work.", "situation_class_label": "More work than the available time allows, with the gap stated in the situation", "observation_mode_label": "written_response", "min_seconds": 420, "max_seconds": 1800}, "source_identifier": "SRC-D3-S1-001", "stage_code": "S1", "source_version_hash": "436a5d6a8349d094ac23fbcd5d5915b71dc06c3fd677bfff2ebb7bc0692bd7fb", "serving_eligible": false, "verbatim": "You are an operations coordinator. It is Monday at 9:15 AM. Three requests arrived in the last thirty minutes.\n\nYour supervisor, at 8:50 AM: the vendor cost comparison needs updating by 11:00 AM for a leadership meeting. About ninety minutes of work.\n\nThe client services team, at 9:00 AM: the client organization says its invoice is wrong and is threatening to withhold payment. About forty-five minutes of work.\n\nThe technology department, at 8:45 AM: the shared drive migration runs at noon, and every department must confirm its files are backed up by 11:30 AM or risk data loss. About sixty minutes of work.\n\nYou have one hour and forty-five minutes before the 11:00 AM deadline and two hours and fifteen minutes before the 11:30 AM deadline. The three tasks take about three hours and fifteen minutes. You cannot complete all three before their stated times."}'::jsonb from public.t3a_content_object where identifier = 'SRC-D3-S1-001' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D3-S1-002', 'source'::public.t3a_content_family, 'THE BUDGET HALVED AFTER THE DEPOSIT', 'D3', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.0', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 1, "title": "THE BUDGET HALVED AFTER THE DEPOSIT", "source_digest": "f22ff4b6c4ab572de6a2f5ff83611fef9572c8b1b6010bef145fb83babdf04da", "situation": "You are an event coordinator. Your supervisor assigned you a client appreciation event for forty guests in three weeks. The budget was five thousand dollars.\n\nThis morning your supervisor writes: \"Finance cut the event budget to two thousand five hundred. Same date, same guest count.\"\n\nAgainst the original five thousand you have already:\n\n- Signed the venue contract at one thousand five hundred, with a five hundred dollar non-refundable deposit paid\n- Taken a catering quote at two thousand, not yet confirmed\n- Taken a photographer quote at four hundred, not yet confirmed\n- Planned printed materials and signage at three hundred, not yet ordered\n- Made a verbal agreement with a speaker at eight hundred, no contract\n\nYou need to remove two thousand five hundred dollars and still hold the event on the same date for the same number of guests.", "reveals": [{"code": "R1", "text": "What do you do first, and in what order do you take the five commitments?", "role": "Opening"}, {"code": "R2", "text": "What is cut, and by how much? What is kept whole?", "role": "Information"}, {"code": "R3", "text": "What do you check before you treat a commitment as removed?", "role": "Information"}, {"code": "R4", "text": "What do you tell the supervisor the event will now be, and what will it not include?", "role": "Information"}, {"code": "R5", "text": "Your supervisor writes: \"For my own record — which of the five commitments are now settled and which are still open?\" What is your answer?", "role": "Account test"}], "question_applicability": [{"question": "Q-D3-01", "state": "DIRECT", "basis": "Five commitments, R2 asks the order"}, {"question": "Q-D3-01b", "state": "CONDITIONAL", "basis": "work_items holds five — the largest ordering set in the bank"}, {"question": "Q-D3-02", "state": "DIRECT", "basis": "R3 asks what is cut"}, {"question": "Q-D3-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-03", "state": "DIRECT", "basis": "R3 asks what is kept whole; three stated requirements"}, {"question": "Q-D3-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-04", "state": "DIRECT", "basis": "R4 asks what is checked"}, {"question": "Q-D3-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-05", "state": "DIRECT", "basis": "Three means available"}, {"question": "Q-D3-05b", "state": "CONDITIONAL", "basis": "SERVED at this Stage in identifying form"}, {"question": "Q-D3-06a", "state": "NOT SERVED", "basis": "blocking_dependency is an explicit none"}, {"question": "Q-D3-06b", "state": "NOT SERVED", "basis": "blocking_dependency is an explicit none"}, {"question": "Q-D3-07", "state": "DIRECT", "basis": "R5 asks what the event will and will not include"}, {"question": "Q-D3-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-08", "state": "DIRECT", "basis": "THE PRIMARY ELEMENT OF THIS SOURCE. The budget moved after commitments were made"}, {"question": "Q-D3-09", "state": "DIRECT", "basis": "delivery_test_point at R6"}], "material_map": [{"Item": "WI1", "Item text": "the venue — contract signed, five hundred non-refundable", "Where the participant meets it": "The situation", "Quoted text": "five thousand you have already: - Signed the venue contract at one thousand five hundred, with a five hundred dollar non-refundable deposit"}, {"Item": "WI2", "Item text": "the catering — quoted, not confirmed", "Where the participant meets it": "The situation", "Quoted text": "catering quote at two thousand, not yet confirmed - Taken a photographer quote at four hundred, not yet confirmed"}, {"Item": "WI3", "Item text": "the photographer — quoted, not confirmed", "Where the participant meets it": "The situation", "Quoted text": "confirmed - Taken a photographer quote at four hundred, not yet confirmed"}, {"Item": "WI4", "Item text": "the printed materials — planned, not ordered", "Where the participant meets it": "The situation", "Quoted text": "Planned printed materials and signage at three hundred, not yet ordered"}, {"Item": "WI5", "Item text": "the speaker — verbal agreement, no contract", "Where the participant meets it": "The situation", "Quoted text": "materials and signage at three hundred, not yet ordered - Made a verbal agreement with a speaker at eight hundred, no contract"}, {"Item": "SR1", "Item text": "the event is held on the same date", "Where the participant meets it": "The situation", "Quoted text": "event on the same date for the same"}, {"Item": "SR2", "Item text": "the event is held for the same guest count", "Where the participant meets it": "The situation", "Quoted text": "Same date, same guest count.\""}, {"Item": "SR3", "Item text": "total spend does not exceed two thousand five hundred", "Where the participant meets it": "The situation", "Quoted text": "two thousand five hundred"}], "source_sheet": {"d3_situation_class": "SC-D3-3", "workplace_demand": "Replanning delivery when the constraint changes after commitments are made.", "relevant_conduct": "The order stated; which commitments were reduced, deferred or dropped; what was kept whole; what verification was named before treating a commitment as removed; what was stated about the reduced event at handover; what was done with the work already committed; the answer at R5.", "irrelevant_conduct": "Whether the cuts chosen were the right ones; the quality of the event; opinions about the finance decision.", "stated_standard": "\"Same date, same guest count.\" Exact text at the situation. THESE ARE THE TWO REQUIREMENTS THE SOURCE PROTECTS; nothing else is protected.", "stated_standard_source_quote_or_location": "\"Same date, same guest count\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Reveal order fixed; accommodations recorded.", "unsupported_inferences": "That the deposit should or should not be written off; that cutting the speaker is better than cutting catering; anything about negotiation skill.", "compatibility_class": "S1-WRITTEN-SEQUENTIAL", "work_items": [{"id": "WI1", "text": "the venue — contract signed, five hundred non-refundable"}, {"id": "WI2", "text": "the catering — quoted, not confirmed"}, {"id": "WI3", "text": "the photographer — quoted, not confirmed"}, {"id": "WI4", "text": "the printed materials — planned, not ordered"}, {"id": "WI5", "text": "the speaker — verbal agreement, no contract"}], "deliverable_components": [{"id": "DC1", "text": "venue"}, {"id": "DC2", "text": "catering"}, {"id": "DC3", "text": "photography"}, {"id": "DC4", "text": "printed materials and signage"}, {"id": "DC5", "text": "speaker"}], "stated_requirements": [{"id": "SR1", "text": "the event is held on the same date"}, {"id": "SR2", "text": "the event is held for the same guest count"}, {"id": "SR3", "text": "total spend does not exceed two thousand five hundred"}], "available_checks": [{"id": "CK1", "text": "confirm which commitments are contractually binding before treating one as removable"}, {"id": "CK2", "text": "reconcile the revised plan against the two thousand five hundred limit"}], "available_means": [{"id": "MN1", "text": "renegotiate the catering quote to a lower service level"}, {"id": "MN2", "text": "withdraw from the uncontracted commitments"}, {"id": "MN3", "text": "ask the supervisor whether the guest count may move"}], "time_available": "Three weeks to the event date.", "work_required": "Five commitments totalling five thousand against a limit of two thousand five hundred.", "blocking_dependency": null, "dependency_holder_role": null, "moved_standard_point": "This morning, when the budget was cut to two thousand five hundred.", "handover_point": "R4, when the revised event is stated to the supervisor.", "delivery_state_record": "At R5: the venue is contracted; the catering, photographer and materials are unconfirmed; the speaker holds a verbal agreement only.", "delivery_test_point": "R5", "list_note": null, "source_note": "blocking_dependency: NOTE: the non-refundable deposit is a SUNK CONSTRAINT, not a dependency the participant is waiting on.", "situation_class_label": "The deadline or scope moves after work has begun", "observation_mode_label": "written_response", "min_seconds": 420, "max_seconds": 1800}, "source_identifier": "SRC-D3-S1-002", "stage_code": "S1", "source_version_hash": "f22ff4b6c4ab572de6a2f5ff83611fef9572c8b1b6010bef145fb83babdf04da", "serving_eligible": false, "verbatim": "You are an event coordinator. Your supervisor assigned you a client appreciation event for forty guests in three weeks. The budget was five thousand dollars.\n\nThis morning your supervisor writes: \"Finance cut the event budget to two thousand five hundred. Same date, same guest count.\"\n\nAgainst the original five thousand you have already:\n\n- Signed the venue contract at one thousand five hundred, with a five hundred dollar non-refundable deposit paid\n- Taken a catering quote at two thousand, not yet confirmed\n- Taken a photographer quote at four hundred, not yet confirmed\n- Planned printed materials and signage at three hundred, not yet ordered\n- Made a verbal agreement with a speaker at eight hundred, no contract\n\nYou need to remove two thousand five hundred dollars and still hold the event on the same date for the same number of guests."}'::jsonb from public.t3a_content_object where identifier = 'SRC-D3-S1-002' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D3-S1-003', 'source'::public.t3a_content_family, 'THE TRUCK THAT DID NOT ARRIVE', 'D3', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.0', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 1, "title": "THE TRUCK THAT DID NOT ARRIVE", "source_digest": "7cfcf895382d6802d48d369139d9d7c8c7c9f6c781199df464e882bbad53e194", "situation": "You are a logistics coordinator. A shipment of five hundred units to the client organization is scheduled to leave the warehouse at 2:00 PM today. The delivery truck was due at 1:00 PM for loading.\n\nIt is 1:45 PM. The truck has not arrived. The shipping company says it broke down on the highway and the replacement will not reach you until 5:30 PM.\n\nWhat you know:\n\n- The client organization expects delivery by 8:00 AM tomorrow. Leaving at 5:30 PM means arriving about 10:30 AM\n- Their production line is scheduled to start at 8:30 AM using these units\n- Your supervisor is on a flight and lands at 6:00 PM\n- You may approve shipping costs up to two thousand dollars without supervisor approval\n- A regional courier could take a partial load today at a cost within that limit", "reveals": [{"code": "R1", "text": "What do you do first?", "role": "Opening"}, {"code": "R2", "text": "You can move part of the shipment today or all of it late. What goes, and what does not?", "role": "Information"}, {"code": "R3", "text": "Before anything leaves the warehouse, what do you check?", "role": "Information"}, {"code": "R4", "text": "What do you do about the truck itself between now and 5:30 PM?", "role": "Information"}, {"code": "R5", "text": "At 6:15 PM your supervisor calls: \"Just so I have the position — what has left the warehouse and what has not?\" What is your answer?", "role": "Account test"}], "question_applicability": [{"question": "Q-D3-01", "state": "DIRECT", "basis": "Three routes of action; R2 creates the opportunity"}, {"question": "Q-D3-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-02", "state": "DIRECT", "basis": "R3 asks what goes and what does not"}, {"question": "Q-D3-02b", "state": "CONDITIONAL", "basis": "Only two components — the smallest reduction set in the bank"}, {"question": "Q-D3-03", "state": "DIRECT", "basis": "Two stated requirements, one of which is an authority limit"}, {"question": "Q-D3-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-04", "state": "DIRECT", "basis": "R4 asks what is checked"}, {"question": "Q-D3-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-05", "state": "DIRECT", "basis": "Three means, one of which is to use no means and wait"}, {"question": "Q-D3-05b", "state": "CONDITIONAL", "basis": "SERVED at this Stage in identifying form"}, {"question": "Q-D3-06a", "state": "DIRECT", "basis": "THE BLOCKING DEPENDENCY IS THE SITUATION and R5 asks about it directly"}, {"question": "Q-D3-06b", "state": "DIRECT", "basis": "THE BLOCKING DEPENDENCY IS THE SITUATION and R5 asks about it directly"}, {"question": "Q-D3-07", "state": "DIRECT", "basis": "R3 creates the opportunity to state what would go incomplete"}, {"question": "Q-D3-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-08", "state": "NOT SERVED", "basis": "The situation presents no change to the requirement"}, {"question": "Q-D3-09", "state": "DIRECT", "basis": "delivery_test_point at R6"}], "material_map": [{"Item": "WI1", "Item text": "load and dispatch the full shipment on the replacement truck", "Where the participant meets it": "The situation", "Quoted text": "truck was due at 1:00 PM for loading"}, {"Item": "WI2", "Item text": "arrange a partial load with the regional courier today", "Where the participant meets it": "The situation", "Quoted text": "regional courier could take a partial load today"}, {"Item": "WI3", "Item text": "confirm the revised arrival with the client organization", "Where the participant meets it": "The situation", "Quoted text": "client organization is scheduled"}, {"Item": "SR1", "Item text": "delivery reaches the client organization by 8:00 AM tomorrow", "Where the participant meets it": "The situation", "Quoted text": "client organization expects delivery by 8:00 AM tomorrow"}, {"Item": "SR2", "Item text": "shipping cost stays within the two thousand dollar authority", "Where the participant meets it": "The situation", "Quoted text": "shipping costs up to two thousand dollars without supervisor approval - A regional courier could take a partial load today at a"}], "source_sheet": {"d3_situation_class": "SC-D3-5", "workplace_demand": "Delivering against a fixed client time when the means of delivery has failed.", "relevant_conduct": "The order stated; what was split, deferred or dropped from the shipment; what was stated as held; which checks were named; which means were named and whether within the stated authority; what was done about the truck; what was stated about the partial load at handover; the answer at R5.", "irrelevant_conduct": "Whether splitting the load was the right call; the shipping company''s reliability; the client organization''s production schedule.", "stated_standard": "\"expects delivery by 8:00 AM tomorrow\" and \"You may approve shipping costs up to two thousand dollars without supervisor approval.\" Exact text at the situation.", "stated_standard_source_quote_or_location": "\"expects delivery by 8:00 AM tomorrow\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Reveal order fixed; accommodations recorded.", "unsupported_inferences": "That waiting for the supervisor was required or wrong; that the courier should have been used; anything about decisiveness.", "compatibility_class": "S1-WRITTEN-SEQUENTIAL", "work_items": [{"id": "WI1", "text": "load and dispatch the full shipment on the replacement truck"}, {"id": "WI2", "text": "arrange a partial load with the regional courier today"}, {"id": "WI3", "text": "confirm the revised arrival with the client organization"}], "deliverable_components": [{"id": "DC1", "text": "the units required for the 8:30 AM production start"}, {"id": "DC2", "text": "the remainder of the five hundred units"}], "stated_requirements": [{"id": "SR1", "text": "delivery reaches the client organization by 8:00 AM tomorrow"}, {"id": "SR2", "text": "shipping cost stays within the two thousand dollar authority"}], "available_checks": [{"id": "CK1", "text": "confirm the courier''s stated arrival time before committing the partial load"}, {"id": "CK2", "text": "confirm the partial load covers the units needed for the 8:30 AM start"}], "available_means": [{"id": "MN1", "text": "engage the regional courier for a partial load within the stated authority"}, {"id": "MN2", "text": "dispatch the full load on the replacement truck at 5:30 PM"}, {"id": "MN3", "text": "wait for the supervisor to land at 6:00 PM before committing spend"}], "time_available": "From 1:45 PM today to 8:00 AM tomorrow.", "work_required": "Five hundred units delivered against a replacement truck arriving at 5:30 PM.", "blocking_dependency": "The replacement truck does not arrive until 5:30 PM.", "dependency_holder_role": "The shipping company. RETAINED FOR SOURCE TRUTH AND NEVER RENDERED.", "moved_standard_point": null, "handover_point": "Dispatch from the warehouse, inside the observation at R2 and R4.", "delivery_state_record": "At R5: the source establishes that the replacement truck arrives at 5:30 PM and that a partial courier load was available. WHAT LEFT DEPENDS ON THE PARTICIPANT''S OWN STATED PLAN.", "delivery_test_point": "R5", "list_note": null, "source_note": "moved_standard_point: The client requirement did not move; the means failed.", "situation_class_label": "Work that cannot proceed until something outside the participant''s control moves", "observation_mode_label": "written_response", "min_seconds": 420, "max_seconds": 1800}, "source_identifier": "SRC-D3-S1-003", "stage_code": "S1", "source_version_hash": "7cfcf895382d6802d48d369139d9d7c8c7c9f6c781199df464e882bbad53e194", "serving_eligible": false, "verbatim": "You are a logistics coordinator. A shipment of five hundred units to the client organization is scheduled to leave the warehouse at 2:00 PM today. The delivery truck was due at 1:00 PM for loading.\n\nIt is 1:45 PM. The truck has not arrived. The shipping company says it broke down on the highway and the replacement will not reach you until 5:30 PM.\n\nWhat you know:\n\n- The client organization expects delivery by 8:00 AM tomorrow. Leaving at 5:30 PM means arriving about 10:30 AM\n- Their production line is scheduled to start at 8:30 AM using these units\n- Your supervisor is on a flight and lands at 6:00 PM\n- You may approve shipping costs up to two thousand dollars without supervisor approval\n- A regional courier could take a partial load today at a cost within that limit"}'::jsonb from public.t3a_content_object where identifier = 'SRC-D3-S1-003' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D3-S1-004', 'source'::public.t3a_content_family, 'SEGMENT FIVE AT EIGHTY PER CENT', 'D3', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.0', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 1, "title": "SEGMENT FIVE AT EIGHTY PER CENT", "source_digest": "840e178b39fcb41c557d0bce87f5d985ab07767a5a4cc364d0516a8d9ce4b0f1", "situation": "You are a research analyst. Your supervisor asked you for a market analysis report for a client presentation tomorrow at 10:00 AM. The report covers five market segments.\n\nIt is 7:00 PM. Segments one to four are complete: data verified, charts formatted, narratives written. Segment five is about eighty per cent done — the data is gathered and the analysis is finished, but the narrative needs editing, one chart has a formatting fault, and segment five has not been cross-referenced against the other four for consistency.\n\nFinishing segment five to the standard of the others takes about two to three more hours. Submitting now means segment five is presentable but not at that standard.\n\nYour supervisor messages that the report must be in their inbox by 8:30 PM tonight for a 9:00 PM client handoff.", "reveals": [{"code": "R1", "text": "What do you do first with the remaining work on segment five?", "role": "Opening"}, {"code": "R2", "text": "If not everything on segment five gets done tonight, what gets done and what does not?", "role": "Information"}, {"code": "R3", "text": "What do you check before the report goes to your supervisor?", "role": "Information"}, {"code": "R4", "text": "How does the report reach your supervisor by 8:30 PM, and what does it say about segment five?", "role": "Information"}, {"code": "R5", "text": "At 8:35 PM your supervisor writes: \"Before I send it on — which segments are finished to standard and which are not?\" What is your answer?", "role": "Account test"}], "question_applicability": [{"question": "Q-D3-01", "state": "DIRECT", "basis": "Three outstanding pieces; R2 asks the order"}, {"question": "Q-D3-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-02", "state": "DIRECT", "basis": "R3 asks what does not get done"}, {"question": "Q-D3-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-03", "state": "DIRECT", "basis": "FOUR stated requirements — the largest requirement set in the bank"}, {"question": "Q-D3-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-04", "state": "DIRECT", "basis": "R4 asks what is checked"}, {"question": "Q-D3-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-05", "state": "DIRECT", "basis": "Three means"}, {"question": "Q-D3-05b", "state": "CONDITIONAL", "basis": "SERVED at this Stage in identifying form"}, {"question": "Q-D3-06a", "state": "NOT SERVED", "basis": "blocking_dependency is an explicit none"}, {"question": "Q-D3-06b", "state": "NOT SERVED", "basis": "blocking_dependency is an explicit none"}, {"question": "Q-D3-07", "state": "DIRECT", "basis": "R5 asks what the report says about segment five"}, {"question": "Q-D3-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-08", "state": "NOT SERVED", "basis": "The situation presents no change to the requirement"}, {"question": "Q-D3-09", "state": "DIRECT", "basis": "delivery_test_point at R6"}], "material_map": [{"Item": "WI1", "Item text": "edit the segment five narrative", "Where the participant meets it": "The situation", "Quoted text": "data is gathered and the analysis is finished, but the narrative needs editing, one chart has a formatting fault, and segment five"}, {"Item": "WI2", "Item text": "fix the chart formatting fault", "Where the participant meets it": "The situation", "Quoted text": "chart has a formatting fault"}, {"Item": "WI3", "Item text": "cross-reference segment five against segments one to four", "Where the participant meets it": "The situation", "Quoted text": "but the narrative needs editing, one chart has a formatting fault, and segment five has not been cross-referenced against the other four"}, {"Item": "SR1", "Item text": "data is verified", "Where the participant meets it": "The situation", "Quoted text": "data verified, charts formatted"}, {"Item": "SR2", "Item text": "charts are formatted", "Where the participant meets it": "The situation", "Quoted text": "are complete: data verified, charts formatted"}, {"Item": "SR3", "Item text": "narratives are written", "Where the participant meets it": "The situation", "Quoted text": "are complete: data verified, charts formatted, narratives written"}, {"Item": "SR4", "Item text": "the report reaches the supervisor by 8:30 PM", "Where the participant meets it": "Reveal R4", "Quoted text": "report reach your supervisor"}], "source_sheet": {"d3_situation_class": "SC-D3-4", "workplace_demand": "Releasing work that can be completed only in part.", "relevant_conduct": "The order of the three outstanding pieces; what was reduced or deferred; what was stated as held; which checks were named; which means were named; what was stated about segment five at handover; the answer at R5.", "irrelevant_conduct": "Whether staying late was the right call; the analytical content; whether the supervisor''s timing was reasonable.", "stated_standard": "\"the standard of Segments one to four\": data verified, charts formatted, narratives written. Exact text at the situation.", "stated_standard_source_quote_or_location": "\"data verified, charts formatted\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Reveal order fixed; accommodations recorded.", "unsupported_inferences": "That submitting at eighty per cent is a failure or a strength; that cross-referencing matters more than the chart; anything about diligence.", "compatibility_class": "S1-WRITTEN-SEQUENTIAL", "work_items": [{"id": "WI1", "text": "edit the segment five narrative"}, {"id": "WI2", "text": "fix the chart formatting fault"}, {"id": "WI3", "text": "cross-reference segment five against segments one to four"}], "deliverable_components": [{"id": "DC1", "text": "the segment five narrative"}, {"id": "DC2", "text": "the segment five chart"}, {"id": "DC3", "text": "the cross-segment consistency check"}], "stated_requirements": [{"id": "SR1", "text": "data is verified"}, {"id": "SR2", "text": "charts are formatted"}, {"id": "SR3", "text": "narratives are written"}, {"id": "SR4", "text": "the report reaches the supervisor by 8:30 PM"}], "available_checks": [{"id": "CK1", "text": "the cross-segment consistency check"}, {"id": "CK2", "text": "a formatting pass across all five segments"}], "available_means": [{"id": "MN1", "text": "submit now with segment five marked as draft"}, {"id": "MN2", "text": "submit segments one to four now and segment five before 8:30 PM"}, {"id": "MN3", "text": "stay and finish segment five to the stated standard"}], "time_available": "From 7:00 PM to the 8:30 PM inbox time.", "work_required": "\"about two to three more hours.\" Exact text at the situation.", "blocking_dependency": null, "dependency_holder_role": null, "moved_standard_point": null, "handover_point": "R4, when the report reaches the supervisor. INSIDE THE OBSERVATION.", "delivery_state_record": "At R5: segments one to four are at standard; segment five''s narrative, chart and cross-reference are the three outstanding items.", "delivery_test_point": "R5", "list_note": null, "source_note": null, "situation_class_label": "A deliverable that can be completed only in part by the time it is due", "observation_mode_label": "written_response", "min_seconds": 420, "max_seconds": 1800}, "source_identifier": "SRC-D3-S1-004", "stage_code": "S1", "source_version_hash": "840e178b39fcb41c557d0bce87f5d985ab07767a5a4cc364d0516a8d9ce4b0f1", "serving_eligible": false, "verbatim": "You are a research analyst. Your supervisor asked you for a market analysis report for a client presentation tomorrow at 10:00 AM. The report covers five market segments.\n\nIt is 7:00 PM. Segments one to four are complete: data verified, charts formatted, narratives written. Segment five is about eighty per cent done — the data is gathered and the analysis is finished, but the narrative needs editing, one chart has a formatting fault, and segment five has not been cross-referenced against the other four for consistency.\n\nFinishing segment five to the standard of the others takes about two to three more hours. Submitting now means segment five is presentable but not at that standard.\n\nYour supervisor messages that the report must be in their inbox by 8:30 PM tonight for a 9:00 PM client handoff."}'::jsonb from public.t3a_content_object where identifier = 'SRC-D3-S1-004' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D3-S1-005', 'source'::public.t3a_content_family, 'THE CLIENT SYSTEM WITH NO RESTORATION TIME', 'D3', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.0', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 1, "title": "THE CLIENT SYSTEM WITH NO RESTORATION TIME", "source_digest": "0e79362a5255323d029ca35a0a884ce444b79fa2c0449144d4fa73a2e8ef6aa3", "situation": "You are a sales operations specialist. It is Tuesday at 9:00 AM. The client records system you use for client data, pipeline tracking and proposal preparation has crashed. The technology department has posted: outage, investigating, no restoration time.\n\nYour commitments today:\n\n- 10:00 AM — send a proposal to the client organization. The template and the client''s pricing and terms are in the system. Due by noon\n- 2:00 PM — weekly pipeline review with your supervisor, who expects an updated pipeline report produced from the system\n- 4:00 PM — client call, for which you need the account history held in the system\n\nThe system may return within the hour. It may be down all day. You do not know.", "reveals": [{"code": "R1", "text": "What do you do first, and in what order do you take the three commitments?", "role": "Opening"}, {"code": "R2", "text": "If the system does not return today, which of the three still happens and which does not?", "role": "Information"}, {"code": "R3", "text": "For anything you send or present today, what do you check first?", "role": "Information"}, {"code": "R4", "text": "What do you do about the outage itself?", "role": "Information"}, {"code": "R5", "text": "At 4:30 PM your supervisor writes: \"Just so I have it — which of today''s three went ahead and which did not?\" What is your answer?", "role": "Account test"}], "question_applicability": [{"question": "Q-D3-01", "state": "DIRECT", "basis": "Three commitments; R2 asks the order"}, {"question": "Q-D3-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-02", "state": "DIRECT", "basis": "R3 asks which still happens"}, {"question": "Q-D3-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-03", "state": "DIRECT", "basis": "ONE stated requirement only"}, {"question": "Q-D3-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-04", "state": "DIRECT", "basis": "R4 asks what is checked"}, {"question": "Q-D3-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-05", "state": "DIRECT", "basis": "Three means"}, {"question": "Q-D3-05b", "state": "CONDITIONAL", "basis": "SERVED at this Stage in identifying form"}, {"question": "Q-D3-06a", "state": "DIRECT", "basis": "R5 asks about the outage directly"}, {"question": "Q-D3-06b", "state": "DIRECT", "basis": "R5 asks about the outage directly"}, {"question": "Q-D3-07", "state": "DIRECT", "basis": "R3 and R4 create the opportunity to state what goes out incomplete"}, {"question": "Q-D3-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-08", "state": "NOT SERVED", "basis": "The situation presents no change to the requirement"}, {"question": "Q-D3-09", "state": "DIRECT", "basis": "delivery_test_point at R6"}], "material_map": [{"Item": "WI1", "Item text": "the proposal, due by noon", "Where the participant meets it": "The situation", "Quoted text": "Due by noon -"}, {"Item": "WI2", "Item text": "the pipeline report for the 2:00 PM review", "Where the participant meets it": "The situation", "Quoted text": "pipeline review with your supervisor, who expects an updated pipeline report"}, {"Item": "WI3", "Item text": "the account history for the 4:00 PM call", "Where the participant meets it": "The situation", "Quoted text": "call, for which you need the account history"}, {"Item": "SR1", "Item text": "the proposal reaches the client organization by noon", "Where the participant meets it": "The situation", "Quoted text": "proposal to the client organization"}], "source_sheet": {"d3_situation_class": "SC-D3-2", "workplace_demand": "Holding three fixed commitments when the system all three depend on is unavailable.", "relevant_conduct": "The order stated; what was reduced, deferred or dropped; what was stated as held; which checks were named; which means were named; what was done about the outage; what was stated about anything delivered incomplete; the answer at R5.", "irrelevant_conduct": "The technical cause of the outage; the technology department''s responsiveness; the substance of the proposal.", "stated_standard": "\"Due by noon\" for the proposal. Exact text at the situation. The other two commitments carry times but no stated standard.", "stated_standard_source_quote_or_location": "\"proposal to the client organization\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Reveal order fixed; accommodations recorded.", "unsupported_inferences": "That working from memory would be wrong; that any commitment should have been canceled; anything about resourcefulness.", "compatibility_class": "S1-WRITTEN-SEQUENTIAL", "work_items": [{"id": "WI1", "text": "the proposal, due by noon"}, {"id": "WI2", "text": "the pipeline report for the 2:00 PM review"}, {"id": "WI3", "text": "the account history for the 4:00 PM call"}], "deliverable_components": [{"id": "DC1", "text": "the proposal"}, {"id": "DC2", "text": "the pipeline report"}, {"id": "DC3", "text": "the account history preparation"}], "stated_requirements": [{"id": "SR1", "text": "the proposal reaches the client organization by noon"}], "available_checks": [{"id": "CK1", "text": "confirm pricing and terms against a source outside the system before sending"}, {"id": "CK2", "text": "confirm the pipeline figures are current rather than carried forward"}], "available_means": [{"id": "MN1", "text": "rebuild the proposal from a saved copy outside the system"}, {"id": "MN2", "text": "move the pipeline review to a later day"}, {"id": "MN3", "text": "hold the client call without the account history and say so"}], "time_available": "The working day, with the first deadline at noon.", "work_required": "Three commitments, all dependent on an unavailable system.", "blocking_dependency": "The client records system is down with no restoration time.", "dependency_holder_role": "The technology department. RETAINED AND NEVER RENDERED.", "moved_standard_point": null, "handover_point": "Noon for the proposal, inside the observation at R2 and R3.", "delivery_state_record": "At R5: the source establishes only that the system was unavailable with no restoration time. WHAT WENT AHEAD DEPENDS ON THE PARTICIPANT''S OWN STATED PLAN.", "delivery_test_point": "R5", "list_note": null, "source_note": null, "situation_class_label": "A tool or resource the work depends on is unavailable, with no restoration time given", "observation_mode_label": "written_response", "min_seconds": 420, "max_seconds": 1800}, "source_identifier": "SRC-D3-S1-005", "stage_code": "S1", "source_version_hash": "0e79362a5255323d029ca35a0a884ce444b79fa2c0449144d4fa73a2e8ef6aa3", "serving_eligible": false, "verbatim": "You are a sales operations specialist. It is Tuesday at 9:00 AM. The client records system you use for client data, pipeline tracking and proposal preparation has crashed. The technology department has posted: outage, investigating, no restoration time.\n\nYour commitments today:\n\n- 10:00 AM — send a proposal to the client organization. The template and the client''s pricing and terms are in the system. Due by noon\n- 2:00 PM — weekly pipeline review with your supervisor, who expects an updated pipeline report produced from the system\n- 4:00 PM — client call, for which you need the account history held in the system\n\nThe system may return within the hour. It may be down all day. You do not know."}'::jsonb from public.t3a_content_object where identifier = 'SRC-D3-S1-005' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D3-S1-006', 'source'::public.t3a_content_family, 'FOUR SENTENCES AND TWO AND A HALF DAYS', 'D3', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.0', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 1, "title": "FOUR SENTENCES AND TWO AND A HALF DAYS", "source_digest": "3365fe09f1730017ac1e5ca02a28019cdd1e5f413f3efa2540f6bf9913f957cc", "situation": "You are a marketing coordinator. On Friday at 4:30 PM your director sent this before leaving for a week-long conference: \"Can you put together the deck for the client pitch? Need it by Wednesday. Use the usual format. Thanks.\"\n\nIt is Monday morning. You have two and a half days.\n\nWhat the message does not say: which client account, because there are two with that name; whether the pitch is new business, a renewal or an expansion; which of the three pitch deck templates counts as the usual format; and what the deck should contain, because there is no brief, outline or talking points.\n\nYour director is at the conference with limited availability and may not reply quickly.", "reveals": [{"code": "R1", "text": "What do you do first, and in what order?", "role": "Opening"}, {"code": "R2", "text": "You may not get an answer before Wednesday. What do you build, and what do you leave out?", "role": "Information"}, {"code": "R3", "text": "Before the deck goes to your director, what do you check?", "role": "Information"}, {"code": "R4", "text": "How does the deck reach your director, and what does it say about the parts you could not confirm?", "role": "Information"}, {"code": "R5", "text": "On Wednesday your director writes: \"One quick question before I open it — which parts are settled and which are assumptions?\" What is your answer?", "role": "Account test"}], "question_applicability": [{"question": "Q-D3-01", "state": "DIRECT", "basis": "Four work items; R2 asks the order"}, {"question": "Q-D3-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-02", "state": "DIRECT", "basis": "R3 asks what is left out"}, {"question": "Q-D3-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-03", "state": "DIRECT", "basis": "Two stated requirements, one of them ambiguous by design"}, {"question": "Q-D3-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-04", "state": "DIRECT", "basis": "R4 asks what is checked"}, {"question": "Q-D3-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-05", "state": "DIRECT", "basis": "Three means"}, {"question": "Q-D3-05b", "state": "CONDITIONAL", "basis": "SERVED at this Stage in identifying form"}, {"question": "Q-D3-06a", "state": "DIRECT", "basis": "The director''s unavailability is the blocking dependency"}, {"question": "Q-D3-06b", "state": "DIRECT", "basis": "The director''s unavailability is the blocking dependency"}, {"question": "Q-D3-07", "state": "DIRECT", "basis": "R5 asks what the deck says about the unconfirmed parts. THIS IS THE STRONGEST CE-D3-07 SOURCE IN THE BANK"}, {"question": "Q-D3-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-08", "state": "NOT SERVED", "basis": "The situation presents no change to the requirement"}, {"question": "Q-D3-09", "state": "DIRECT", "basis": "delivery_test_point at R6"}], "material_map": [{"Item": "WI1", "Item text": "establish which client account the pitch is for", "Where the participant meets it": "The situation", "Quoted text": "client account, because there are two with that name; whether the pitch is new business, a renewal or an expansion; which of"}, {"Item": "WI2", "Item text": "establish the pitch type", "Where the participant meets it": "The situation", "Quoted text": "for the client pitch?"}, {"Item": "WI3", "Item text": "select the template", "Where the participant meets it": "The situation", "Quoted text": "which of the three pitch deck templates"}, {"Item": "WI4", "Item text": "build the deck content", "Where the participant meets it": "The situation", "Quoted text": "deck for the client"}, {"Item": "SR1", "Item text": "the deck reaches the director by Wednesday", "Where the participant meets it": "Reveal R4", "Quoted text": "deck reach your director"}, {"Item": "SR2", "Item text": "the deck uses the usual format", "Where the participant meets it": "The situation", "Quoted text": "deck templates counts as the usual format; and what the deck"}], "source_sheet": {"d3_situation_class": "SC-D3-6", "workplace_demand": "Delivering to a specification that does not exist.", "relevant_conduct": "The order stated; what was built and what was left out; what was stated as held; which checks were named; which means were named; what was stated about the unconfirmed parts at handover; the answer at R5.", "irrelevant_conduct": "Whether the assumptions chosen were right; whether the director should have briefed better; the deck''s content.", "stated_standard": "\"Need it by Wednesday\" and \"Use the usual format.\" Exact text at the situation. THE SECOND IS THE ONLY CONTENT STANDARD THE SOURCE STATES AND IT IS AMBIGUOUS BY DESIGN — a mentor must not resolve it.", "stated_standard_source_quote_or_location": "\"Need it by Wednesday\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Reveal order fixed; accommodations recorded.", "unsupported_inferences": "That asking was required; that building on an assumption was wrong; anything about initiative.", "compatibility_class": "S1-WRITTEN-SEQUENTIAL", "work_items": [{"id": "WI1", "text": "establish which client account the pitch is for"}, {"id": "WI2", "text": "establish the pitch type"}, {"id": "WI3", "text": "select the template"}, {"id": "WI4", "text": "build the deck content"}], "deliverable_components": [{"id": "DC1", "text": "the account-specific content"}, {"id": "DC2", "text": "the pitch-type framing"}, {"id": "DC3", "text": "the template and format"}, {"id": "DC4", "text": "the talking points"}], "stated_requirements": [{"id": "SR1", "text": "the deck reaches the director by Wednesday"}, {"id": "SR2", "text": "the deck uses the usual format"}], "available_checks": [{"id": "CK1", "text": "confirm the account and pitch type against the two existing records before building"}, {"id": "CK2", "text": "compare the draft against the three templates to establish which is the usual format"}], "available_means": [{"id": "MN1", "text": "send the director a short list of the specific unknowns"}, {"id": "MN2", "text": "build one deck against the more likely account and mark the assumption"}, {"id": "MN3", "text": "build the structure only and leave the account-specific content blank"}], "time_available": "\"two and a half days.\" Exact text at the situation.", "work_required": "Four unknowns resolved and a deck built.", "blocking_dependency": "The director is at a conference with limited availability and may not reply before Wednesday.", "dependency_holder_role": "The director. RETAINED AND NEVER RENDERED.", "moved_standard_point": null, "handover_point": "R4, Wednesday. INSIDE THE OBSERVATION.", "delivery_state_record": "At R5: the four items the source lists as unknown remain unconfirmed unless the participant states otherwise.", "delivery_test_point": "R5", "list_note": null, "source_note": null, "situation_class_label": "Work that arrives without a specification sufficient to complete it", "observation_mode_label": "written_response", "min_seconds": 420, "max_seconds": 1800}, "source_identifier": "SRC-D3-S1-006", "stage_code": "S1", "source_version_hash": "3365fe09f1730017ac1e5ca02a28019cdd1e5f413f3efa2540f6bf9913f957cc", "serving_eligible": false, "verbatim": "You are a marketing coordinator. On Friday at 4:30 PM your director sent this before leaving for a week-long conference: \"Can you put together the deck for the client pitch? Need it by Wednesday. Use the usual format. Thanks.\"\n\nIt is Monday morning. You have two and a half days.\n\nWhat the message does not say: which client account, because there are two with that name; whether the pitch is new business, a renewal or an expansion; which of the three pitch deck templates counts as the usual format; and what the deck should contain, because there is no brief, outline or talking points.\n\nYour director is at the conference with limited availability and may not reply quickly."}'::jsonb from public.t3a_content_object where identifier = 'SRC-D3-S1-006' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D3-S1-007', 'source'::public.t3a_content_family, 'SECTION B HAS NOT ARRIVED', 'D3', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.0', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 1, "title": "SECTION B HAS NOT ARRIVED", "source_digest": "a63681c5c3d9e6be360a1ad108990726fc3ea5ecc666667f0ba6933336fb8773", "situation": "You are a project coordinator preparing a client proposal due to the client organization by Friday at 5:00 PM. It has three components.\n\nSection A, the market analysis, you completed on Monday. Section B, the technical specifications, is owned by a colleague and was due to you by Wednesday. Section C, pricing and terms, is owned by the finance team and is due to you by Thursday.\n\nIt is Wednesday at 3:00 PM. Section B has not arrived. You have sent two messages and one email. There has been no reply, and the colleague''s calendar shows meetings all day.\n\nWithout Section B you cannot finalize Section C, because the pricing depends on the specifications, and you cannot assemble the proposal.", "reveals": [{"code": "R1", "text": "What do you do now, and in what order?", "role": "Opening"}, {"code": "R2", "text": "If Section B does not arrive by Thursday morning, what goes to the client organization on Friday and what does not?", "role": "Information"}, {"code": "R3", "text": "Before the proposal goes out, what do you check?", "role": "Information"}, {"code": "R4", "text": "What do you do about Section B itself between now and Thursday morning?", "role": "Information"}, {"code": "R5", "text": "On Thursday your supervisor writes: \"Where does the proposal stand — which sections are in and which are not?\" What is your answer?", "role": "Account test"}], "question_applicability": [{"question": "Q-D3-01", "state": "DIRECT", "basis": "Three work items in a dependency chain; R2 asks the order"}, {"question": "Q-D3-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-02", "state": "DIRECT", "basis": "R3 asks what goes and what does not"}, {"question": "Q-D3-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-03", "state": "DIRECT", "basis": "One stated requirement, the Friday deadline"}, {"question": "Q-D3-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-04", "state": "DIRECT", "basis": "R4 asks what is checked"}, {"question": "Q-D3-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-05", "state": "DIRECT", "basis": "Three means"}, {"question": "Q-D3-05b", "state": "CONDITIONAL", "basis": "SERVED at this Stage in identifying form"}, {"question": "Q-D3-06a", "state": "DIRECT", "basis": "R5 asks about Section B directly. THE SOURCE WHERE THE RISK OF A CROSS-DIMENSION ASSERTION IS HIGHEST — a statement naming the colleague REFUSES and logs cross_dimension_assertion"}, {"question": "Q-D3-06b", "state": "DIRECT", "basis": "R5 asks about Section B directly. THE SOURCE WHERE THE RISK OF A CROSS-DIMENSION ASSERTION IS HIGHEST — a statement naming the colleague REFUSES and logs cross_dimension_assertion"}, {"question": "Q-D3-07", "state": "DIRECT", "basis": "R3 creates the opportunity to state what goes out incomplete"}, {"question": "Q-D3-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-08", "state": "NOT SERVED", "basis": "The situation presents no change to the requirement"}, {"question": "Q-D3-09", "state": "DIRECT", "basis": "delivery_test_point at R6"}], "material_map": [{"Item": "WI1", "Item text": "obtain Section B", "Where the participant meets it": "The situation", "Quoted text": "Section A, the market"}, {"Item": "WI2", "Item text": "finalize Section C once the specifications are available", "Where the participant meets it": "The situation", "Quoted text": "Section B you cannot finalize Section C, because the pricing depends on the specifications"}, {"Item": "WI3", "Item text": "assemble and issue the proposal", "Where the participant meets it": "The situation", "Quoted text": "cannot assemble the proposal"}, {"Item": "SR1", "Item text": "the proposal reaches the client organization by Friday at 5:00 PM", "Where the participant meets it": "The situation", "Quoted text": "client proposal due to the client organization by Friday"}], "source_sheet": {"d3_situation_class": "SC-D3-5", "workplace_demand": "Assembling a deliverable whose middle component sits with someone else.", "relevant_conduct": "The order stated; what was reduced, deferred or dropped; what was stated as held; which checks were named; which means were named; what was done about Section B; what was stated about the incomplete proposal at handover; the answer at R5.", "irrelevant_conduct": "The colleague''s responsiveness, workload or conduct, WHICH IS NEVER RECORDED OR RENDERED; the technical content; whether chasing harder was warranted.", "stated_standard": "\"due to the client organization by Friday at 5:00 PM.\" Exact text at the situation.", "stated_standard_source_quote_or_location": "\"due to the client organization by Friday at 5:00 PM\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Reveal order fixed; accommodations recorded.", "unsupported_inferences": "That the colleague failed; that escalating was required; anything about persistence. NO D3 STATEMENT NAMES THE COLLEAGUE OR ATTRIBUTES THE DELAY.", "compatibility_class": "S1-WRITTEN-SEQUENTIAL", "work_items": [{"id": "WI1", "text": "obtain Section B"}, {"id": "WI2", "text": "finalize Section C once the specifications are available"}, {"id": "WI3", "text": "assemble and issue the proposal"}], "deliverable_components": [{"id": "DC1", "text": "Section A, market analysis"}, {"id": "DC2", "text": "Section B, technical specifications"}, {"id": "DC3", "text": "Section C, pricing and terms"}], "stated_requirements": [{"id": "SR1", "text": "the proposal reaches the client organization by Friday at 5:00 PM"}], "available_checks": [{"id": "CK1", "text": "confirm Section C''s pricing against the specifications once received"}, {"id": "CK2", "text": "confirm the assembled proposal contains all three sections before issue"}], "available_means": [{"id": "MN1", "text": "raise the missing section with the supervisor"}, {"id": "MN2", "text": "draft an interim Section B from the available information and mark it provisional"}, {"id": "MN3", "text": "issue the proposal with Section B marked as to follow"}], "time_available": "From Wednesday 3:00 PM to Friday 5:00 PM.", "work_required": "Two dependent components plus assembly, with the middle one absent.", "blocking_dependency": "Section B has not been delivered and the finance team''s Section C depends on it.", "dependency_holder_role": "A colleague and the finance team. RETAINED FOR SOURCE TRUTH AND NEVER RENDERED.", "moved_standard_point": null, "handover_point": "Friday at 5:00 PM, inside the observation as a stated intention at R2.", "delivery_state_record": "At R5: Section A complete; Section B not received; Section C not finalisable until Section B arrives.", "delivery_test_point": "R5", "list_note": null, "source_note": null, "situation_class_label": "Work that cannot proceed until something outside the participant''s control moves", "observation_mode_label": "written_response", "min_seconds": 420, "max_seconds": 1800}, "source_identifier": "SRC-D3-S1-007", "stage_code": "S1", "source_version_hash": "a63681c5c3d9e6be360a1ad108990726fc3ea5ecc666667f0ba6933336fb8773", "serving_eligible": false, "verbatim": "You are a project coordinator preparing a client proposal due to the client organization by Friday at 5:00 PM. It has three components.\n\nSection A, the market analysis, you completed on Monday. Section B, the technical specifications, is owned by a colleague and was due to you by Wednesday. Section C, pricing and terms, is owned by the finance team and is due to you by Thursday.\n\nIt is Wednesday at 3:00 PM. Section B has not arrived. You have sent two messages and one email. There has been no reply, and the colleague''s calendar shows meetings all day.\n\nWithout Section B you cannot finalize Section C, because the pricing depends on the specifications, and you cannot assemble the proposal."}'::jsonb from public.t3a_content_object where identifier = 'SRC-D3-S1-007' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D3-S1-008', 'source'::public.t3a_content_family, 'TWO FIRES AND A MANDATORY HOUR', 'D3', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.0', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 1, "title": "TWO FIRES AND A MANDATORY HOUR", "source_digest": "5e1533f98d2da78040e32561f8f1b0707bd86474d814cb233fc820814823377b", "situation": "You are a client services coordinator. It is Tuesday at 10:15 AM. Three things arrived in fifteen minutes.\n\nAt 10:00 AM the client organization emailed: a billing error on last month''s invoice overcharged them four thousand two hundred dollars, and they want it resolved today or they pause all payments. You must investigate, identify the error and issue a correction.\n\nAt 10:08 AM a colleague messaged: the client demonstration environment for a two-hundred-thousand-dollar opportunity crashed and rebuilding the demonstration data needs about ninety minutes of your time. The demonstration is at 2:00 PM.\n\nAt 10:12 AM your supervisor sent a calendar invitation: emergency team meeting at 11:00 AM on restructuring, mandatory, sixty minutes.\n\nYou have forty-five minutes before the meeting and about two hours after it.", "reveals": [{"code": "R1", "text": "What do you do in the forty-five minutes before 11:00 AM, and in what order?", "role": "Opening"}, {"code": "R2", "text": "Across the whole day, what gets done and what does not?", "role": "Information"}, {"code": "R3", "text": "Before the invoice correction goes out, what do you check?", "role": "Information"}, {"code": "R4", "text": "For anything not finished today, how does it go out and what does it say?", "role": "Information"}, {"code": "R5", "text": "At 5:00 PM your supervisor writes: \"A quick status check — where did each of the three land?\" What is your answer?", "role": "Account test"}], "question_applicability": [{"question": "Q-D3-01", "state": "DIRECT", "basis": "Three claims on one day; R2 asks the order within a bounded window"}, {"question": "Q-D3-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-02", "state": "DIRECT", "basis": "R3 asks what does not get done"}, {"question": "Q-D3-02b", "state": "CONDITIONAL", "basis": "TWO components only, because the meeting is not a deliverable"}, {"question": "Q-D3-03", "state": "DIRECT", "basis": "Three stated requirements that cannot all hold"}, {"question": "Q-D3-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-04", "state": "DIRECT", "basis": "R4 asks what is checked"}, {"question": "Q-D3-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-05", "state": "DIRECT", "basis": "Three means"}, {"question": "Q-D3-05b", "state": "CONDITIONAL", "basis": "SERVED at this Stage in identifying form"}, {"question": "Q-D3-06a", "state": "NOT SERVED", "basis": "blocking_dependency is an explicit none"}, {"question": "Q-D3-06b", "state": "NOT SERVED", "basis": "blocking_dependency is an explicit none"}, {"question": "Q-D3-07", "state": "DIRECT", "basis": "R5 asks how anything unfinished goes out"}, {"question": "Q-D3-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-08", "state": "NOT SERVED", "basis": "The situation presents no change to the requirement"}, {"question": "Q-D3-09", "state": "DIRECT", "basis": "delivery_test_point at R6"}], "material_map": [{"Item": "WI1", "Item text": "investigate and correct the invoice", "Where the participant meets it": "The situation", "Quoted text": "invoice overcharged them four"}, {"Item": "WI2", "Item text": "rebuild the demonstration data — about ninety minutes", "Where the participant meets it": "The situation", "Quoted text": "demonstration environment for a two-hundred-thousand-dollar opportunity crashed and rebuilding the demonstration data needs about ninety minutes"}, {"Item": "WI3", "Item text": "attend the mandatory meeting — sixty minutes", "Where the participant meets it": "The situation", "Quoted text": "meeting at 11:00 AM on restructuring, mandatory, sixty minutes"}, {"Item": "SR1", "Item text": "the invoice matter is resolved today", "Where the participant meets it": "The situation", "Quoted text": "invoice overcharged them four thousand two hundred dollars, and they want it resolved today"}, {"Item": "SR2", "Item text": "attendance at the 11:00 AM meeting", "Where the participant meets it": "The situation", "Quoted text": "meeting at 11:00 AM"}, {"Item": "SR3", "Item text": "the demonstration runs at 2:00 PM", "Where the participant meets it": "The situation", "Quoted text": "demonstration is at 2:00"}], "source_sheet": {"d3_situation_class": "SC-D3-1", "workplace_demand": "Ordering work around a block of time that cannot be used.", "relevant_conduct": "The order stated; what was reduced, deferred or dropped; what was stated as held; which checks were named; which means were named; what was stated about anything unfinished; the answer at R5.", "irrelevant_conduct": "Whether attending the meeting was the right call; the substance of the billing error; the value of the opportunity.", "stated_standard": "\"resolved today or they pause all payments\"; \"mandatory attendance\"; \"The demonstration is at 2:00 PM.\" Exact text at the situation.", "stated_standard_source_quote_or_location": "\"resolved today or they pause all payments\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Reveal order fixed; accommodations recorded.", "unsupported_inferences": "That the mandatory meeting should have been skipped; that the larger opportunity outranks the invoice; anything about judgment under workplace pressure.", "compatibility_class": "S1-WRITTEN-SEQUENTIAL", "work_items": [{"id": "WI1", "text": "investigate and correct the invoice"}, {"id": "WI2", "text": "rebuild the demonstration data — about ninety minutes"}, {"id": "WI3", "text": "attend the mandatory meeting — sixty minutes"}], "deliverable_components": [{"id": "DC1", "text": "the invoice correction"}, {"id": "DC2", "text": "the rebuilt demonstration environment"}], "stated_requirements": [{"id": "SR1", "text": "the invoice matter is resolved today"}, {"id": "SR2", "text": "attendance at the 11:00 AM meeting"}, {"id": "SR3", "text": "the demonstration runs at 2:00 PM"}], "available_checks": [{"id": "CK1", "text": "verify the overcharge figure against the underlying billing record before issuing a correction"}, {"id": "CK2", "text": "confirm the rebuilt demonstration data loads before 2:00 PM"}], "available_means": [{"id": "MN1", "text": "ask the colleague to rebuild the demonstration data without you"}, {"id": "MN2", "text": "acknowledge the invoice to the client organization with a stated time for the correction"}, {"id": "MN3", "text": "ask the supervisor whether the meeting can be missed"}], "time_available": "Forty-five minutes before the meeting and about two hours after.", "work_required": "An investigation and correction, about ninety minutes of rebuild, and sixty minutes of unusable time.", "blocking_dependency": null, "dependency_holder_role": null, "moved_standard_point": null, "handover_point": "The invoice correction and the 2:00 PM demonstration, both inside the observation.", "delivery_state_record": "At R5: the source establishes the three claims on the day and the sixty-minute mandatory block. WHERE EACH LANDED DEPENDS ON THE PARTICIPANT''S OWN STATED PLAN.", "delivery_test_point": "R5", "list_note": null, "source_note": "blocking_dependency: THE MEETING IS A FIXED CLAIM ON TIME, NOT A DEPENDENCY THE PARTICIPANT IS WAITING ON. A build that treats an unusable block as a blocking dependency has misread the field.", "situation_class_label": "More work than the available time allows, with the gap stated in the situation", "observation_mode_label": "written_response", "min_seconds": 420, "max_seconds": 1800}, "source_identifier": "SRC-D3-S1-008", "stage_code": "S1", "source_version_hash": "5e1533f98d2da78040e32561f8f1b0707bd86474d814cb233fc820814823377b", "serving_eligible": false, "verbatim": "You are a client services coordinator. It is Tuesday at 10:15 AM. Three things arrived in fifteen minutes.\n\nAt 10:00 AM the client organization emailed: a billing error on last month''s invoice overcharged them four thousand two hundred dollars, and they want it resolved today or they pause all payments. You must investigate, identify the error and issue a correction.\n\nAt 10:08 AM a colleague messaged: the client demonstration environment for a two-hundred-thousand-dollar opportunity crashed and rebuilding the demonstration data needs about ninety minutes of your time. The demonstration is at 2:00 PM.\n\nAt 10:12 AM your supervisor sent a calendar invitation: emergency team meeting at 11:00 AM on restructuring, mandatory, sixty minutes.\n\nYou have forty-five minutes before the meeting and about two hours after it."}'::jsonb from public.t3a_content_object where identifier = 'SRC-D3-S1-008' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D3-S1-009', 'source'::public.t3a_content_family, 'MODULE THREE, REWRITTEN BY MORNING', 'D3', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.0', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 1, "title": "MODULE THREE, REWRITTEN BY MORNING", "source_digest": "878acbeb729f2256eab94c92b6c49bf037ed2d2f1e13ad0533dc23471e437556", "situation": "You are a project coordinator. Over two weeks you built a five-module training program for the client organization covering safety protocols, equipment operation and compliance reporting. It launches tomorrow. All materials are finalized, reviewed and approved by the client. Facilitators are booked. Participants are registered.\n\nAt 4:00 PM today the client organization''s safety director calls: a new regulatory requirement has been issued, and Module 3 on compliance reporting must be rewritten to reflect the new filing procedures. Launching with the outdated content could expose them to regulatory penalties. Can you update it by tomorrow morning?\n\nWhat you know:\n\n- Module 3 is about forty-five slides with supporting materials and exercises\n- The new regulatory document is twelve pages and you have not read it\n- Rewriting Module 3 properly takes about eight to ten hours\n- The client requires the revised module by 8:00 AM. The authoring system is available to you until 7:00 PM today and reopens at 7:00 AM tomorrow, so you have about four working hours before the handoff", "reveals": [{"code": "R1", "text": "What do you do first, and in what order?", "role": "Opening"}, {"code": "R2", "text": "Eight to ten hours of rewriting does not fit before morning. What is rewritten and what is not?", "role": "Information"}, {"code": "R3", "text": "Before Module 3 is used tomorrow, what do you check?", "role": "Information"}, {"code": "R4", "text": "What goes to the facilitators tonight, and what does it say about Module 3?", "role": "Information"}, {"code": "R5", "text": "At 7:00 AM the safety director calls: \"Before we start — which parts of Module 3 reflect the new procedures and which do not?\" What is your answer?", "role": "Account test"}], "question_applicability": [{"question": "Q-D3-01", "state": "DIRECT", "basis": "Four work items; R2 asks the order"}, {"question": "Q-D3-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-02", "state": "DIRECT", "basis": "R3 asks what is not rewritten"}, {"question": "Q-D3-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-03", "state": "DIRECT", "basis": "Two stated requirements that cannot both hold in the time"}, {"question": "Q-D3-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-04", "state": "DIRECT", "basis": "R4 asks what is checked"}, {"question": "Q-D3-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-05", "state": "DIRECT", "basis": "Three means"}, {"question": "Q-D3-05b", "state": "CONDITIONAL", "basis": "SERVED at this Stage in identifying form"}, {"question": "Q-D3-06a", "state": "NOT SERVED", "basis": "blocking_dependency is an explicit none"}, {"question": "Q-D3-06b", "state": "NOT SERVED", "basis": "blocking_dependency is an explicit none"}, {"question": "Q-D3-07", "state": "DIRECT", "basis": "R5 asks what goes to the facilitators about Module 3"}, {"question": "Q-D3-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-08", "state": "DIRECT", "basis": "THE PRIMARY ELEMENT. Two weeks of finished work meets a changed requirement, and all four conduct answers are reachable"}, {"question": "Q-D3-09", "state": "DIRECT", "basis": "delivery_test_point at R6"}], "material_map": [{"Item": "WI1", "Item text": "read the twelve-page regulatory document", "Where the participant meets it": "The situation", "Quoted text": "regulatory document is twelve pages and you have not read"}, {"Item": "WI2", "Item text": "identify which of the forty-five slides are affected", "Where the participant meets it": "The situation", "Quoted text": "Module 3 is about forty-five slides"}, {"Item": "WI3", "Item text": "rewrite the affected slides", "Where the participant meets it": "The situation", "Quoted text": "slides with supporting materials"}, {"Item": "WI4", "Item text": "update the supporting materials and exercises", "Where the participant meets it": "The situation", "Quoted text": "supporting materials and exercises"}, {"Item": "SR1", "Item text": "Module 3 reflects the new filing procedures before it is used", "Where the participant meets it": "The situation", "Quoted text": "new regulatory requirement has been issued, and Module 3 on compliance reporting must be rewritten to reflect the new filing procedures"}, {"Item": "SR2", "Item text": "the program launches tomorrow as scheduled", "Where the participant meets it": "The situation", "Quoted text": "It launches tomorrow. All materials are finalized"}], "source_sheet": {"d3_situation_class": "SC-D3-3", "workplace_demand": "A finished deliverable whose requirement changes the night before use.", "relevant_conduct": "The order stated; what was rewritten, deferred or dropped; what was stated as held; which checks were named; which means were named; what was said to the facilitators about Module 3; what was done with the two weeks of work already completed; the answer at R5.", "irrelevant_conduct": "Whether the request should have been accepted; the regulatory content; the client''s notice period.", "stated_standard": "\"Launching with outdated compliance content could expose them to regulatory penalties\" and the program launches tomorrow. Exact text at the situation.", "stated_standard_source_quote_or_location": "\"new regulatory requirement has been issued, and Module 3 on compliance reporting must be rewritten to reflect the new filing procedures\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Reveal order fixed; accommodations recorded.", "unsupported_inferences": "That delaying the launch was the right answer; that a partial rewrite is inadequate; anything about stamina or commitment.", "compatibility_class": "S1-WRITTEN-SEQUENTIAL", "work_items": [{"id": "WI1", "text": "read the twelve-page regulatory document"}, {"id": "WI2", "text": "identify which of the forty-five slides are affected"}, {"id": "WI3", "text": "rewrite the affected slides"}, {"id": "WI4", "text": "update the supporting materials and exercises"}], "deliverable_components": [{"id": "DC1", "text": "the Module 3 slides"}, {"id": "DC2", "text": "the Module 3 supporting materials"}, {"id": "DC3", "text": "the Module 3 exercises"}], "stated_requirements": [{"id": "SR1", "text": "Module 3 reflects the new filing procedures before it is used"}, {"id": "SR2", "text": "the program launches tomorrow as scheduled"}], "available_checks": [{"id": "CK1", "text": "confirm the rewritten slides against the twelve-page document"}, {"id": "CK2", "text": "confirm with the safety director that the rewritten content meets the new requirement"}], "available_means": [{"id": "MN1", "text": "move Module 3 to a later day in the program and run the other four as planned"}, {"id": "MN2", "text": "rewrite only the slides the regulatory document affects and mark the rest as unchanged"}, {"id": "MN3", "text": "ask the safety director which filing procedures changed"}], "time_available": "About four working hours: 4:00 PM to 7:00 PM today and 7:00 AM to 8:00 AM tomorrow, bounded by system availability. Exact text at the situation.", "work_required": "\"about eight to ten hours.\" Exact text at the situation.", "blocking_dependency": null, "dependency_holder_role": null, "moved_standard_point": "4:00 PM today, when the regulatory requirement changed Module 3''s content standard.", "handover_point": "R4, when material goes to the facilitators tonight. INSIDE THE OBSERVATION.", "delivery_state_record": "At R5: the source establishes that a full rewrite takes eight to ten hours and that less time than that was available. WHICH PARTS REFLECT THE NEW PROCEDURES DEPENDS ON THE PARTICIPANT''S OWN STATED PLAN.", "delivery_test_point": "R5", "list_note": null, "source_note": "blocking_dependency: The regulatory document is in hand; nothing is being waited on.", "situation_class_label": "The deadline or scope moves after work has begun", "observation_mode_label": "written_response", "min_seconds": 420, "max_seconds": 1800}, "source_identifier": "SRC-D3-S1-009", "stage_code": "S1", "source_version_hash": "878acbeb729f2256eab94c92b6c49bf037ed2d2f1e13ad0533dc23471e437556", "serving_eligible": false, "verbatim": "You are a project coordinator. Over two weeks you built a five-module training program for the client organization covering safety protocols, equipment operation and compliance reporting. It launches tomorrow. All materials are finalized, reviewed and approved by the client. Facilitators are booked. Participants are registered.\n\nAt 4:00 PM today the client organization''s safety director calls: a new regulatory requirement has been issued, and Module 3 on compliance reporting must be rewritten to reflect the new filing procedures. Launching with the outdated content could expose them to regulatory penalties. Can you update it by tomorrow morning?\n\nWhat you know:\n\n- Module 3 is about forty-five slides with supporting materials and exercises\n- The new regulatory document is twelve pages and you have not read it\n- Rewriting Module 3 properly takes about eight to ten hours\n- The client requires the revised module by 8:00 AM. The authoring system is available to you until 7:00 PM today and reopens at 7:00 AM tomorrow, so you have about four working hours before the handoff"}'::jsonb from public.t3a_content_object where identifier = 'SRC-D3-S1-009' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D3-S1-010', 'source'::public.t3a_content_family, 'THE ACCOUNT WITH NO HANDOVER', 'D3', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.0', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 1, "title": "THE ACCOUNT WITH NO HANDOVER", "source_digest": "77a4ac16e5f85f371244385ef3e7698bd35ec93cba83dabb8d5a04987a054adf", "situation": "You are a customer success associate. A colleague went on medical leave unexpectedly last week and you have been assigned their largest account, effective immediately.\n\nThere is no handover documentation. The files are a mix of outdated spreadsheets, unsorted email folders and a client record not updated in three weeks.\n\nWhat the record shows:\n\n- The contract renewal is in six weeks\n- Four support tickets are open, from three days to two weeks old\n- The last meeting note is a month old\n- The satisfaction score dropped from eight to five last quarter, flagged with no follow-up recorded\n- You have a check-in call with the account lead tomorrow at 2:00 PM", "reveals": [{"code": "R1", "text": "What do you do first, and in what order do you take the five items?", "role": "Opening"}, {"code": "R2", "text": "You have until 2:00 PM tomorrow. What is ready for that call and what is not?", "role": "Information"}, {"code": "R3", "text": "Before the call, what do you check and against what?", "role": "Information"}, {"code": "R4", "text": "What do you take into the call, and what does it say about the parts you could not reconstruct?", "role": "Information"}, {"code": "R5", "text": "After the call your supervisor writes: \"So I have the position — which parts of the account are reconstructed and which are still unknown?\" What is your answer?", "role": "Account test"}], "question_applicability": [{"question": "Q-D3-01", "state": "DIRECT", "basis": "Five work items — joint largest ordering set in the bank"}, {"question": "Q-D3-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-02", "state": "DIRECT", "basis": "R3 asks what is not ready"}, {"question": "Q-D3-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-03", "state": "DIRECT", "basis": "Two stated requirements on different horizons"}, {"question": "Q-D3-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-04", "state": "DIRECT", "basis": "R4 asks what is checked AND against what, which is the CE-D3-04 pairing this source exercises best"}, {"question": "Q-D3-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-05", "state": "DIRECT", "basis": "Three means"}, {"question": "Q-D3-05b", "state": "CONDITIONAL", "basis": "SERVED at this Stage in identifying form"}, {"question": "Q-D3-06a", "state": "NOT SERVED", "basis": "blocking_dependency is an explicit none. Absent information is not a dependency"}, {"question": "Q-D3-06b", "state": "NOT SERVED", "basis": "blocking_dependency is an explicit none. Absent information is not a dependency"}, {"question": "Q-D3-07", "state": "DIRECT", "basis": "R5 asks what the call carries about the unreconstructed parts"}, {"question": "Q-D3-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-08", "state": "NOT SERVED", "basis": "The situation presents no change to the requirement"}, {"question": "Q-D3-09", "state": "DIRECT", "basis": "delivery_test_point at R6"}], "material_map": [{"Item": "WI1", "Item text": "review and update the client record", "Where the participant meets it": "The situation", "Quoted text": "client record not updated"}, {"Item": "WI2", "Item text": "work the four open support tickets", "Where the participant meets it": "The situation", "Quoted text": "Four support tickets are open"}, {"Item": "WI3", "Item text": "reconstruct the meeting history", "Where the participant meets it": "The situation", "Quoted text": "meeting note is a"}, {"Item": "WI4", "Item text": "establish what lies behind the satisfaction drop", "Where the participant meets it": "The situation", "Quoted text": "satisfaction score dropped from"}, {"Item": "WI5", "Item text": "prepare for the 2:00 PM call", "Where the participant meets it": "The situation", "Quoted text": "call with the account"}, {"Item": "SR1", "Item text": "the check-in call happens at 2:00 PM tomorrow", "Where the participant meets it": "Reveal R3", "Quoted text": "call, what do you check"}, {"Item": "SR2", "Item text": "the contract renewal is addressed within six weeks", "Where the participant meets it": "The situation", "Quoted text": "contract renewal is in six weeks - Four support tickets are open, from three days to two weeks"}], "source_sheet": {"d3_situation_class": "SC-D3-7", "workplace_demand": "Delivering against an account received in an undocumented state.", "relevant_conduct": "The order stated; what was reduced, deferred or dropped before the call; what was stated as held; which checks were named and against what; which means were named; what was taken into the call about the unreconstructed parts; the answer at R5.", "irrelevant_conduct": "The departed colleague''s records, conduct or circumstances, WHICH ARE NEVER RECORDED OR RENDERED; the client relationship; the satisfaction score''s cause.", "stated_standard": "\"a check-in call with the account lead tomorrow at 2:00 PM\" and \"the contract renewal is in six weeks.\" Exact text at the situation.", "stated_standard_source_quote_or_location": "\"a check-in call with the account lead tomorrow at 2:00 PM\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Reveal order fixed; accommodations recorded.", "unsupported_inferences": "That the handover should have existed; that the tickets outrank the renewal; anything about thoroughness.", "compatibility_class": "S1-WRITTEN-SEQUENTIAL", "work_items": [{"id": "WI1", "text": "review and update the client record"}, {"id": "WI2", "text": "work the four open support tickets"}, {"id": "WI3", "text": "reconstruct the meeting history"}, {"id": "WI4", "text": "establish what lies behind the satisfaction drop"}, {"id": "WI5", "text": "prepare for the 2:00 PM call"}], "deliverable_components": [{"id": "DC1", "text": "the updated client record"}, {"id": "DC2", "text": "the open ticket position"}, {"id": "DC3", "text": "the reconstructed history"}, {"id": "DC4", "text": "the call preparation"}], "stated_requirements": [{"id": "SR1", "text": "the check-in call happens at 2:00 PM tomorrow"}, {"id": "SR2", "text": "the contract renewal is addressed within six weeks"}], "available_checks": [{"id": "CK1", "text": "reconcile the client record against the open tickets and the email folders"}, {"id": "CK2", "text": "confirm the ticket ages and status against the ticket system rather than the spreadsheets"}], "available_means": [{"id": "MN1", "text": "ask the supervisor which of the five items comes first"}, {"id": "MN2", "text": "move the check-in call to a later day"}, {"id": "MN3", "text": "take the call with a stated list of what is not yet reconstructed"}], "time_available": "From now to 2:00 PM tomorrow.", "work_required": "Five items against an undocumented record.", "blocking_dependency": null, "dependency_holder_role": null, "moved_standard_point": null, "handover_point": "The 2:00 PM call, inside the observation at R4.", "delivery_state_record": "At R5: the five items the source lists remain in the state the record shows unless the participant states otherwise.", "delivery_test_point": "R5", "list_note": null, "source_note": "blocking_dependency: The information is absent rather than held by someone the participant is waiting on. This situation class is the same one D2 samples at SRC-D2-S1-007. THAT IS PERMITTED AND IT IS NOT AN ERROR. D2 observes who holds the account and what was stated to the affected party; D3 observes what was ordered, checked and handed over.", "situation_class_label": "Work received from, or passed to, another party in an incomplete state", "observation_mode_label": "written_response", "min_seconds": 420, "max_seconds": 1800}, "source_identifier": "SRC-D3-S1-010", "stage_code": "S1", "source_version_hash": "77a4ac16e5f85f371244385ef3e7698bd35ec93cba83dabb8d5a04987a054adf", "serving_eligible": false, "verbatim": "You are a customer success associate. A colleague went on medical leave unexpectedly last week and you have been assigned their largest account, effective immediately.\n\nThere is no handover documentation. The files are a mix of outdated spreadsheets, unsorted email folders and a client record not updated in three weeks.\n\nWhat the record shows:\n\n- The contract renewal is in six weeks\n- Four support tickets are open, from three days to two weeks old\n- The last meeting note is a month old\n- The satisfaction score dropped from eight to five last quarter, flagged with no follow-up recorded\n- You have a check-in call with the account lead tomorrow at 2:00 PM"}'::jsonb from public.t3a_content_object where identifier = 'SRC-D3-S1-010' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D3-S2-001', 'source'::public.t3a_content_family, 'THE LAUNCH PULLED FORWARD', 'D3', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.0', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 2, "title": "THE LAUNCH PULLED FORWARD", "source_digest": "42c6741f520add3b78f140b3d0d7c199b2ba9337b1dfcb784672abd7e6abf532", "mentor_brief": "The mentor reads the scripted lines of the vice-president. The date is fixed and the mentor states it once, at B1, and never repeats or defends it. THE MENTOR MUST NOT REACT to anything the participant says, must not offer help, and must not suggest what could be dropped. If the participant says nothing at B2, the session proceeds unchanged.", "participant_pre_brief": "You are a marketing coordinator. You have spent three weeks planning a product launch campaign for the fifteenth of next month, four weeks away. Every timeline, vendor contract and team assignment is built on that date. The campaign has four remaining pieces: the creative assets, the vendor bookings, the channel scheduling and the internal launch briefing. Each takes about a week. The campaign standard, written in the launch checklist, is that no asset goes live without brand review and legal sign-off. Your vice-president has asked to see you now.", "script": [{"beat": "B1", "type": "SAY", "spoken": "I have just come out of the board meeting. The launch has been moved forward by two weeks — the new date is the first, not the fifteenth. The campaign needs to be live on the first. The date is not negotiable. I will let you start.", "direction": null, "capture": []}, {"beat": "B2", "type": "PAUSE", "spoken": null, "direction": "Say nothing for ten to fifteen seconds. Do not prompt or fill the silence.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, {"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C3", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4", "state": "open"}, {"set": "C4b", "state": "open"}, {"set": "C5", "state": "open"}, {"set": "C5b", "state": "open"}, {"set": "C7", "state": "open"}, {"set": "C7b", "state": "open"}, {"set": "C8", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "Where does the campaign stand now?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C1b", "state": "update"}, {"set": "C8", "state": "update"}]}, {"beat": "B4", "type": "ASK", "spoken": "Two weeks instead of four. What happens to the pieces you had planned?", "direction": "Read once, verbatim.", "capture": [{"set": "C2", "state": "update"}, {"set": "C2b", "state": "update"}, {"set": "C3", "state": "update"}, {"set": "C3b", "state": "update"}, {"set": "C7", "state": "update"}, {"set": "C7b", "state": "update"}]}, {"beat": "B5", "type": "ASK", "spoken": "What gets checked before anything goes live, and how?", "direction": "Read once, verbatim.", "capture": [{"set": "C4", "state": "update"}, {"set": "C4b", "state": "update"}, {"set": "C5", "state": "update"}, {"set": "C5b", "state": "update"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so I have it right — as of now, which pieces are finished and which are not?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "That is what I needed. Thank you.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3", "state": "final"}, {"set": "C4", "state": "final"}, {"set": "C5", "state": "final"}, {"set": "C7", "state": "final"}, {"set": "C9", "state": "final"}]}], "question_applicability": [{"question": "Q-D3-01", "state": "DIRECT", "basis": "Four pieces, two weeks; B2 and B3 create the opportunity"}, {"question": "Q-D3-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-02", "state": "DIRECT", "basis": "B4 asks what happens to the pieces"}, {"question": "Q-D3-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-03", "state": "DIRECT", "basis": "Three stated requirements that cannot all hold"}, {"question": "Q-D3-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-04", "state": "DIRECT", "basis": "B5 asks what is checked"}, {"question": "Q-D3-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-05", "state": "DIRECT", "basis": "Three means, all performable in session"}, {"question": "Q-D3-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-06a", "state": "NOT SERVED", "basis": "blocking_dependency is an explicit none"}, {"question": "Q-D3-06b", "state": "NOT SERVED", "basis": "blocking_dependency is an explicit none"}, {"question": "Q-D3-07", "state": "DIRECT", "basis": "B4 creates the opportunity to state what goes live incomplete"}, {"question": "Q-D3-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-08", "state": "DIRECT", "basis": "THE PRIMARY ELEMENT. The date moves at B1"}, {"question": "Q-D3-09", "state": "DIRECT", "basis": "delivery_test_point at B6"}], "material_map": [{"Item": "WI1", "Item text": "the creative assets", "Where the participant meets it": "The pre-brief", "Quoted text": "creative assets, the vendor"}, {"Item": "WI2", "Item text": "the vendor bookings", "Where the participant meets it": "The pre-brief", "Quoted text": "vendor bookings, the channel"}, {"Item": "WI3", "Item text": "the channel scheduling", "Where the participant meets it": "The pre-brief", "Quoted text": "channel scheduling and the"}, {"Item": "WI4", "Item text": "the internal launch briefing", "Where the participant meets it": "The pre-brief", "Quoted text": "the internal launch briefing"}, {"Item": "SR1", "Item text": "every asset passes brand review before going live", "Where the participant meets it": "The pre-brief", "Quoted text": "asset goes live without brand review"}, {"Item": "SR2", "Item text": "every asset passes legal sign-off before going live", "Where the participant meets it": "The pre-brief", "Quoted text": "asset goes live without brand review and legal"}, {"Item": "SR3", "Item text": "the campaign is live on the first", "Where the participant meets it": "Beat B1", "Quoted text": "campaign needs to be live on the first"}], "source_sheet": {"d3_situation_class": "SC-D3-3", "workplace_demand": "Replanning a campaign when the date moves after three weeks of work.", "relevant_conduct": "The order stated; what was reduced, deferred or dropped; what was stated as held; which checks were named; which means were named; what was done with the three weeks already spent; what was stated about anything going live incomplete; the answer at B6.", "irrelevant_conduct": "Whether the compression is achievable; the vice-president''s decision; the participant''s manner, pace or composure, WHICH ARE NEVER OBSERVED OR RECORDED.", "stated_standard": "\"no asset goes live without brand review and legal sign-off.\" Exact pre-brief text.", "stated_standard_source_quote_or_location": "\"no asset goes live without brand review and legal sign-off\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only. Accommodations changing channel or pause window are recorded and set `timing_not_comparable`.", "unsupported_inferences": "That pushing back was required or wrong; that any piece should have been dropped first; anything about adaptability.", "compatibility_class": "S2-SEVEN-BEAT", "work_items": [{"id": "WI1", "text": "the creative assets"}, {"id": "WI2", "text": "the vendor bookings"}, {"id": "WI3", "text": "the channel scheduling"}, {"id": "WI4", "text": "the internal launch briefing"}], "deliverable_components": [{"id": "DC1", "text": "creative assets"}, {"id": "DC2", "text": "vendor bookings"}, {"id": "DC3", "text": "channel scheduling"}, {"id": "DC4", "text": "internal briefing"}], "stated_requirements": [{"id": "SR1", "text": "every asset passes brand review before going live"}, {"id": "SR2", "text": "every asset passes legal sign-off before going live"}, {"id": "SR3", "text": "the campaign is live on the first"}], "available_checks": [{"id": "CK1", "text": "brand review"}, {"id": "CK2", "text": "legal sign-off"}], "available_means": [{"id": "MN1", "text": "release the campaign in two waves, the first on the first"}, {"id": "MN2", "text": "ask the vice-president to release a resource to take one piece"}, {"id": "MN3", "text": "reuse approved assets from the previous campaign"}], "time_available": "Two weeks.", "work_required": "Four pieces of about one week each.", "blocking_dependency": null, "dependency_holder_role": null, "moved_standard_point": "B1, when the date moves forward by two weeks.", "handover_point": "The first, when the campaign goes live. Stated at B4, inside the observation.", "delivery_state_record": "At B6: three weeks of planning is complete; none of the four pieces is delivered.", "delivery_test_point": "B6", "list_note": null, "source_note": null, "situation_class_label": "The deadline or scope moves after work has begun", "observation_mode_label": "structured_live_session", "min_seconds": 480, "max_seconds": 900}, "source_identifier": "SRC-D3-S2-001", "stage_code": "S2", "source_version_hash": "42c6741f520add3b78f140b3d0d7c199b2ba9337b1dfcb784672abd7e6abf532", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D3-S2-001' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D3-S2-002', 'source'::public.t3a_content_family, 'THE ROOM WITH NO PROJECTOR', 'D3', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.0', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 2, "title": "THE ROOM WITH NO PROJECTOR", "source_digest": "f4b9d654dd45a0f2fbecc08dad80748366a8464e3fef770f4717941245afcdc5", "mentor_brief": "The mentor reads the scripted lines of the client organization''s office manager. The mentor states what is available once, at B1, and adds nothing further. THE MENTOR MUST NOT SUGGEST a workaround, must not apologize repeatedly, and must not react to whatever the participant proposes.", "participant_pre_brief": "You are a training coordinator about to facilitate a half-day workshop for fifteen participants at the client organization''s office. You arrived thirty minutes early. The projector is broken, so there is no display for your forty-five slide presentation. The network is down, so the interactive polling tool is unavailable. The printed handouts you shipped ahead did not arrive and the front desk has no record of them. Participants arrive in twenty-five minutes. The workshop agreement states that every participant leaves with the four reference frameworks and that the session runs to its stated finish time.", "script": [{"beat": "B1", "type": "SAY", "spoken": "I am sorry about this. The projector has been failing all week and our technology team is off site. I do not know what happened to your package. There is a whiteboard and markers in the room, and I can bring a flip chart from the supply cupboard. That is what I can offer. Over to you.", "direction": null, "capture": []}, {"beat": "B2", "type": "PAUSE", "spoken": null, "direction": "Say nothing for ten to fifteen seconds. Do not prompt or fill the silence.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, {"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C3", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4", "state": "open"}, {"set": "C4b", "state": "open"}, {"set": "C5", "state": "open"}, {"set": "C5b", "state": "open"}, {"set": "C6a", "state": "open"}, {"set": "C6b", "state": "open"}, {"set": "C7", "state": "open"}, {"set": "C7b", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "What are you going to run?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C1b", "state": "update"}]}, {"beat": "B4", "type": "ASK", "spoken": "Twenty-five minutes and no slides. What stays in the session and what does not?", "direction": "Read once, verbatim.", "capture": [{"set": "C2", "state": "update"}, {"set": "C2b", "state": "update"}, {"set": "C3", "state": "update"}, {"set": "C3b", "state": "update"}, {"set": "C7", "state": "update"}, {"set": "C7b", "state": "update"}]}, {"beat": "B5", "type": "ASK", "spoken": "What do you check before the participants come in?", "direction": "Read once, verbatim.", "capture": [{"set": "C4", "state": "update"}, {"set": "C4b", "state": "update"}, {"set": "C5", "state": "update"}, {"set": "C5b", "state": "update"}, {"set": "C6a", "state": "update"}, {"set": "C6b", "state": "update"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so I have it right — as of now, what is ready and what is not?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "Understood. I will leave you to it.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3", "state": "final"}, {"set": "C4", "state": "final"}, {"set": "C5", "state": "final"}, {"set": "C6a", "state": "final"}, {"set": "C6b", "state": "final"}, {"set": "C7", "state": "final"}, {"set": "C9", "state": "final"}]}], "question_applicability": [{"question": "Q-D3-01", "state": "DIRECT", "basis": "Four work items in twenty-five minutes"}, {"question": "Q-D3-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-02", "state": "DIRECT", "basis": "B4 asks what stays in the session"}, {"question": "Q-D3-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-03", "state": "DIRECT", "basis": "Two stated requirements that may not both hold"}, {"question": "Q-D3-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-04", "state": "DIRECT", "basis": "B5 asks what is checked"}, {"question": "Q-D3-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-05", "state": "DIRECT", "basis": "Three means, two performable in session"}, {"question": "Q-D3-05b", "state": "CONDITIONAL", "basis": "MN-02 is NOT eligible — sending handouts later is an intention"}, {"question": "Q-D3-06a", "state": "DIRECT", "basis": "Three unavailable resources, and B5 creates the opportunity"}, {"question": "Q-D3-06b", "state": "DIRECT", "basis": "Three unavailable resources, and B5 creates the opportunity"}, {"question": "Q-D3-07", "state": "DIRECT", "basis": "B4 creates the opportunity to state what the session will not cover"}, {"question": "Q-D3-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-08", "state": "NOT SERVED", "basis": "The situation presents no change to the requirement"}, {"question": "Q-D3-09", "state": "DIRECT", "basis": "delivery_test_point at B6"}], "material_map": [{"Item": "WI1", "Item text": "rebuild the presentation content for a whiteboard", "Where the participant meets it": "The pre-brief", "Quoted text": "your forty-five slide presentation"}, {"Item": "WI2", "Item text": "replace the polling exercise", "Where the participant meets it": "The pre-brief", "Quoted text": "polling tool is unavailable"}, {"Item": "WI3", "Item text": "replace the handouts", "Where the participant meets it": "The pre-brief", "Quoted text": "handouts you shipped ahead"}, {"Item": "WI4", "Item text": "set the room up", "Where the participant meets it": "Beat B1", "Quoted text": "room, and I can"}, {"Item": "SR1", "Item text": "every participant leaves with the four reference frameworks", "Where the participant meets it": "The pre-brief", "Quoted text": "every participant leaves with the four reference frameworks"}, {"Item": "SR2", "Item text": "the session runs to its stated finish time", "Where the participant meets it": "The pre-brief", "Quoted text": "states that every participant leaves with the four reference frameworks and that the session runs to its stated finish time"}], "source_sheet": {"d3_situation_class": "SC-D3-2", "workplace_demand": "Delivering a prepared session when every tool it was built on is unavailable.", "relevant_conduct": "The order stated; which parts of the session were reduced, deferred or dropped; what was stated as held; which checks were named; which means were used; what was done about the missing handouts; what was stated about anything the session would not cover; the answer at B6.", "irrelevant_conduct": "The office manager''s explanation; whether the workaround would work; the participant''s composure or confidence.", "stated_standard": "\"every participant leaves with the four reference frameworks\" and \"the session runs to its stated finish time.\" Exact pre-brief text.", "stated_standard_source_quote_or_location": "\"every participant leaves with the four reference frameworks\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations recorded and set `timing_not_comparable`.", "unsupported_inferences": "That improvising is better than postponing;