  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.0', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 2, "title": "TWO MEETINGS AT TWO O''CLOCK", "source_digest": "f103a9c697e04061e3fd98d3f1d4a0c0b6fd274ed38cb7cc51a521792584dc05", "mentor_brief": "The mentor reads the scripted lines of the supervisor. The mentor states the position once and does not choose for the participant, express preference, or react to the choice made.", "participant_pre_brief": "You are a client success manager. It is 1:55 PM and two meetings start at 2:00 PM. The first is a quarterly business review with the client organization''s vice-president, three of their stakeholders and your director; you are the presenter. The second is an internal project kick-off your supervisor scheduled yesterday, with six people waiting. The team operating standard states that a meeting you cannot attend is handed over with its material before it starts.", "script": [{"beat": "B1", "type": "SAY", "spoken": "It is five to two. Both of those are at two. I will let you tell me where you are going.", "direction": null, "capture": []}, {"beat": "B2", "type": "PAUSE", "spoken": null, "direction": "Say nothing for ten to fifteen seconds. Do not prompt or fill the silence.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, {"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C3", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4", "state": "open"}, {"set": "C4b", "state": "open"}, {"set": "C5", "state": "open"}, {"set": "C5b", "state": "open"}, {"set": "C7", "state": "open"}, {"set": "C7b", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "Which one are you in at two?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C1b", "state": "update"}]}, {"beat": "B4", "type": "ASK", "spoken": "What happens to the other one, and what goes with it?", "direction": "Read once, verbatim.", "capture": [{"set": "C2", "state": "update"}, {"set": "C2b", "state": "update"}, {"set": "C3", "state": "update"}, {"set": "C3b", "state": "update"}, {"set": "C7", "state": "update"}, {"set": "C7b", "state": "update"}]}, {"beat": "B5", "type": "ASK", "spoken": "Before two o''clock, what do you confirm?", "direction": "Read once, verbatim.", "capture": [{"set": "C4", "state": "update"}, {"set": "C4b", "state": "update"}, {"set": "C5", "state": "update"}, {"set": "C5b", "state": "update"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so I have it right — at two o''clock, where is each meeting?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "Understood. Thank you.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3", "state": "final"}, {"set": "C4", "state": "final"}, {"set": "C5", "state": "final"}, {"set": "C7", "state": "final"}, {"set": "C9", "state": "final"}]}], "question_applicability": [{"question": "Q-D3-01", "state": "DIRECT", "basis": "Two commitments and a handover; B3 asks which comes first"}, {"question": "Q-D3-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-02", "state": "DIRECT", "basis": "B4 asks what happens to the other"}, {"question": "Q-D3-02b", "state": "CONDITIONAL", "basis": "TWO components only"}, {"question": "Q-D3-03", "state": "DIRECT", "basis": "ONE stated requirement"}, {"question": "Q-D3-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-04", "state": "DIRECT", "basis": "B5 asks what is confirmed"}, {"question": "Q-D3-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-05", "state": "DIRECT", "basis": "Three means"}, {"questi