  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D3-S2-007', 'source'::public.t3a_content_family, 'NO FOOD, THIRTY GUESTS, TWO HOURS', 'D3', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.0', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 2, "title": "NO FOOD, THIRTY GUESTS, TWO HOURS", "source_digest": "0cd4df99212637a85409de3083b411b24c9b2d9cf2d789359e1c4a6ebdc71dcc", "mentor_brief": "The mentor reads the scripted lines of the venue manager. The mentor states what the venue has once and offers nothing further, suggests nothing, and does not react to whatever the participant proposes.", "participant_pre_brief": "You are an event coordinator running a client appreciation lunch for thirty guests that starts in two hours. The caterer has called: their delivery vehicle has broken down, they cannot deliver, there is no backup, and the two thousand dollar fee is being refunded. The venue has tables, chairs and basic kitchen facilities. Your supervisor is in a meeting until thirty minutes before the event. The event brief states that guests are seated and served within fifteen minutes of arrival and that dietary requirements recorded at registration are met.", "script": [{"beat": "B1", "type": "SAY", "spoken": "I have just heard about the caterer. We have the room set, tables and chairs, and a basic kitchen. That is what the venue can give you. I will let you tell me what you need.", "direction": null, "capture": []}, {"beat": "B2", "type": "PAUSE", "spoken": null, "direction": "Say nothing for ten to fifteen seconds. Do not prompt or fill the silence.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, {"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C3", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4", "state": "open"}, {"set": "C4b", "state": "open"}, {"set": "C5", "state": "open"}, {"set": "C5b", "state": "open"}, {"set": "C6a", "state": "open"}, {"set": "C6b", "state": "open"}, {"set": "C7", "state": "open"}, {"set": "C7b", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "What is the plan for the lunch?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C1b", "state": "update"}, {"set": "C6a", "state": "update"}, {"set": "C6b", "state": "update"}]}, {"beat": "B4", "type": "ASK", "spoken": "Two hours and no caterer. What does the event include and what does it not?", "direction": "Read once, verbatim.", "capture": [{"set": "C2", "state": "update"}, {"set": "C2b", "state": "update"}, {"set": "C3", "state": "update"}, {"set": "C3b", "state": "update"}, {"set": "C7", "state": "update"}, {"set": "C7b", "state": "update"}]}, {"beat": "B5", "type": "ASK", "spoken": "Before guests arrive, what do you confirm?", "direction": "Read once, verbatim.", "capture": [{"set": "C4", "state": "update"}, {"set": "C4b", "state": "update"}, {"set": "C5", "state": "update"}, {"set": "C5b", "state": "update"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so I have it right — an hour from now, what is in place and what is not?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "Understood. Tell me if you need the room changed.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3", "state": "final"}, {"set": "C4", "state": "final"}, {"set": "C5", "state": "final"}, {"set": "C6a", "state": "final"}, {"set": "C6b", "state": "final"}, {"set": "C7", "state": "final"}, {"set": "C9", "state": "final"}]}], "question_applicability": [{"question": "Q-D3-01", "state": "DIRECT", "basis": "Four work items in two hours"}, {"question": "Q-D3-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-02", "state": "DIRECT", "basis": "B4 asks what the event includes"}, {"question": "Q-D3-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-03", "state": "DIRECT", "basis": "Two stated requirements, both at risk"}, {"question": "Q-D3-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-04", "state": "DIRECT", "basis": "B5 asks what is confirmed"}, {"question": "Q-D3-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-05", "state": "DIRECT", "basis": "Three means"}, {"question": "Q-D3-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-06a", "state": "DIRECT", "basis": "The caterer is the blocking dependency"}, {"question": "Q-D3-06b", "state": "DIRECT", "basis": "The caterer is the blocking dependency"}, {"question": "Q-D3-07", "state": "DIRECT", "basis": "B4 and B6 create the opportunity"}, {"question": "Q-D3-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-08", "state": "NOT SERVED", "basis": "The situation presents no change to the requirement"}, {"question": "Q-D3-09", "state": "DIRECT", "basis": "delivery_test_point at B6"}], "material_map": [{"Item": "WI1", "Item text": "source food for thirty", "Where the participant meets it": "The pre-brief", "Quoted text": "thirty guests that starts"}, {"Item": "WI2", "Item text": "confirm dietary requirements can still be met", "Where the participant meets it": "The pre-brief", "Quoted text": "dietary requirements recorded at registration are met"}, {"Item": "WI3", "Item text": "adjust the room and service plan", "Where the participant meets it": "Beat B1", "Quoted text": "room set, tables and"}, {"Item": "WI4", "Item text": "inform the supervisor", "Where the participant meets it": "The pre-brief", "Quoted text": "supervisor is in a"}, {"Item": "SR1", "Item text": "guests are seated and served within fifteen minutes of arrival", "Where the participant meets it": "The pre-brief", "Quoted text": "guests are seated and served within fifteen minutes of arrival and that dietary requirements recorded at registration are"}, {"Item": "SR2", "Item text": "recorded dietary requirements are met", "Where the participant meets it": "The pre-brief", "Quoted text": "are seated and served within fifteen minutes of arrival and that dietary requirements recorded at registration are met"}], "source_sheet": {"d3_situation_class": "SC-D3-5", "workplace_demand": "Delivering an event whose central component has been withdrawn two hours before it starts.", "relevant_conduct": "The order stated; what was reduced, deferred or dropped from the event; what was stated as held; which checks were named; which means were used; what was done about the caterer; what was stated about anything the event would not include; the answer at B6.", "irrelevant_conduct": "The caterer''s failure; whether the replacement is good enough; problem-solving speed, WHICH IS NEVER OBSERVED OR TIMED.", "stated_standard": "\"guests are seated and served within fifteen minutes of arrival\" and \"dietary requirements recorded at registration are met.\" Exact pre-brief text.", "stated_standard_source_quote_or_location": "\"guests are seated and served within fifteen minutes of arrival\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations recorded. NO TIMER IS STARTED OR REFERENCED.", "unsupported_inferences": "That acting fast is better; that the supervisor should have been interrupted; anything about creativity.", "compatibility_class": "S2-SEVEN-BEAT", "work_items": [{"id": "WI1", "text": "source food for thirty"}, {"id": "WI2", "text": "confirm dietary requirements can still be met"}, {"id": "WI3", "text": "adjust the 