  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D3-S2-009', 'source'::public.t3a_content_family, 'THE CALL YOU WERE HANDED TWO MINUTES AGO', 'D3', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.0', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 2, "title": "THE CALL YOU WERE HANDED TWO MINUTES AGO", "source_digest": "853065bf4ab078bd3cf1090c543ba52f7346705d8bf084ef3b6ea890f8a84f60", "mentor_brief": "The mentor reads the scripted lines of the client organization''s contact. The mentor asks about the two workstreams named in the script and does not add a third, does not press, and does not react to a stated unknown.", "participant_pre_brief": "You work in client services. Two minutes ago a colleague messaged that they cannot take their 3:00 PM progress call with the client organization about a website redesign, asked you to cover, and said there was no time to brief you. You have the project record open. It shows four workstreams — homepage mockups, mobile responsiveness, content migration and accessibility review — and the last update on each is between one and three weeks old. The service standard states that a progress update states the position of every workstream and that anything not known is identified as not known.", "script": [{"beat": "B1", "type": "SAY", "spoken": "Thanks for picking this up. I moved my afternoon for this call. I will let you begin.", "direction": null, "capture": []}, {"beat": "B2", "type": "PAUSE", "spoken": null, "direction": "Say nothing for ten to fifteen seconds. Do not prompt or fill the silence.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, {"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C3", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4", "state": "open"}, {"set": "C4b", "state": "open"}, {"set": "C5", "state": "open"}, {"set": "C5b", "state": "open"}, {"set": "C6a", "state": "open"}, {"set": "C6b", "state": "open"}, {"set": "C7", "state": "open"}, {"set": "C7b", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "Where are we on the redesign?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C1b", "state": "update"}, {"set": "C6a", "state": "update"}, {"set": "C6b", "state": "update"}]}, {"beat": "B4", "type": "ASK", "spoken": "Which of the four can you give me a position on, and which can you not?", "direction": "Read once, verbatim.", "capture": [{"set": "C2", "state": "update"}, {"set": "C2b", "state": "update"}, {"set": "C3", "state": "update"}, {"set": "C3b", "state": "update"}, {"set": "C7", "state": "update"}, {"set": "C7b", "state": "update"}]}, {"beat": "B5", "type": "ASK", "spoken": "What are you checking before you come back to me?", "direction": "Read once, verbatim.", "capture": [{"set": "C4", "state": "update"}, {"set": "C4b", "state": "update"}, {"set": "C5", "state": "update"}, {"set": "C5b", "state": "update"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so I have it right — which workstreams did you confirm on this call and which did you not?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "Thank you. I will wait for the follow-up.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3", "state": "final"}, {"set": "C4", "state": "final"}, {"set": "C5", "state": "final"}, {"set": "C6a", "state": "final"}, {"set": "C6b", "state": "final"}, {"set": "C7", "state": "final"}, {"set": "C9", "state": "final"}]}], "question_applicability": [{"question": "Q-D3-01", "state": "DIRECT", "basis": "Four workstreams; B3 creates the opportunity"}, {"question": "Q-D3-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-02", "state": "DIRECT", "basis": "B4 asks which can be given a position"}, {"question": "Q-D3-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-03", "state": "DIRECT", "basis": "Two stated requirements, the second of which the situation engages directly"}, {"question": "Q-D3-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-04", "state": "DIRECT", "basis": "B5 asks what is checked. CK-02 is NOT eligible — confirming later is an intention"}, {"question": "Q-D3-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-05", "state": "DIRECT", "basis": "Three means"}, {"question": "Q-D3-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-06a", "state": "DIRECT", "basis": "The absent briefing is the blocking dependency. A STATEMENT NAMING THE COLLEAGUE REFUSES and logs cross_dimension_assertion"}, {"question": "Q-D3-06b", "state": "DIRECT", "basis": "The absent briefing is the blocking dependency. A STATEMENT NAMING THE COLLEAGUE REFUSES and logs cross_dimension_assertion"}, {"question": "Q-D3-07", "state": "DIRECT", "basis": "THE STRONGEST CE-D3-07 SOURCE IN THE STAGE 2 BANK — the whole call is a handover with gaps"}, {"question": "Q-D3-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-08", "state": "NOT SERVED", "basis": "The situation presents no change to the requirement"}, {"question": "Q-D3-09", "state": "DIRECT", "basis": "delivery_test_point at B6"}], "material_map": [{"Item": "WI1", "Item text": "homepage mockups", "Where the participant meets it": "The pre-brief", "Quoted text": "homepage mockups, mobile responsiveness"}, {"Item": "WI2", "Item text": "mobile responsiveness", "Where the participant meets it": "The pre-brief", "Quoted text": "mobile responsiveness, content migration"}, {"Item": "WI3", "Item text": "content migration", "Where the participant meets it": "The pre-brief", "Quoted text": "content migration and accessibility"}, {"Item": "WI4", "Item text": "accessibility review", "Where the participant meets it": "The pre-brief", "Quoted text": "accessibility review — and"}, {"Item": "SR1", "Item text": "a progress update states the position of every workstream", "Where the participant meets it": "The pre-brief", "Quoted text": "states that a progress update states the position of every workstream"}, {"Item": "SR2", "Item text": "anything not known is identified as not known", "Where the participant meets it": "The pre-brief", "Quoted text": "anything not known is identified as not known"}], "source_sheet": {"d3_situation_class": "SC-D3-7", "workplace_demand": "Delivering an update on work received two minutes earlier in an undocumented state.", "relevant_conduct": "The order stated across the four workstreams; what was deferred; what was stated as held; which checks were named and against what; which means were used; what was done about the absent briefing; which workstreams were identified as not known; the answer at B6.", "irrelevant_conduct": "The colleague''s handover, conduct or reasons, WHICH ARE NEVER RECORDED OR RENDERED; the client''s inconvenience; the participant''s composure, voice or pace.", "stated_standard": "\"a progress update states the position of every workstream\" and \"anything not known is identified as not known.\" Exact pre-brief text.", "stated_standard_source_quote_or_location": "\"a progress update states the position of every workstream\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations recorded.", "unsupported_inferences": "That taking the call was right; that admitting ignorance is a strength or weakness; anything about composure. THE ORIGINAL LIBRARY FORM ASKS THE MENTOR TO OBSERVE VOICE STEADINESS AND PACE OF SPEECH — THAT IS REMOVED ENTIRELY.", "compatibility_class": "S2-SEVEN-BEAT", "work_items": [{"id": "WI1", "text": "homepage mockups"}, {"id": "WI2", "text": "mobile responsiveness"}, {"id": "WI3", "text": "content migration"}, {"id": "WI4", "text": "accessibility review"}], "deliverable_components": [{"id": "DC1", "text": "the homepage mockup position"}, {"id": "DC2", "text": "the mobile responsiveness position"}, {"id": "DC3", "text": "the content migration position"}, {"id": "DC4", "text": "the accessibility review position"}], "stated_requirements": [{"id": "SR1", "text": "a progress update states the position of every workstream"}, {"id": "SR2", "text": "anything not known is identified as not known"}], "available_checks": [{"id": "CK1", "text": "read the project record''s last update date on each workstream before speaking to it"}], "available_means": [{"id": "MN1", "text": "state the position from the project record and mark its age"}, {"id": "MN2", "text": "commit a written follow-up with the confirmed positions"}, {"id": "MN3", "text": "propose reconvening once the workstreams are confirmed"}], "time_available": "The call itself.", "work_required": "A position on four workstreams whose records are one to three weeks old.", "blocking_dependency": "No briefing was given and the colleague is unavailable.", "dependency_holder_role": "A colleague. RETAINED AND NEVER RENDERED.", "moved_standard_point": null, "handover_point": "The call itself, wholly inside the observation.", "delivery_state_record": "At B6: four workstreams with records one to three weeks old, none confirmed current.", "delivery_test_point": "B6", "list_note": "Not selectable in available_checks: confirm with the colleague after the call which positions are current.", "source_note": null, "situation_class_label": "Work received from, or passed to, another party in an incomplete state", "observation_mode_label": "structured_live_session", "min_seconds": 480, "max_seconds": 900}, "source_identifier": "SRC-D3-S2-009", "stage_code": "S2", "source_version_hash": "853065bf4ab078bd3cf1090c543ba52f7346705d8bf084ef3b6ea890f8a84f60", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D3-S2-009' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D3-S2-010', 'source'::public.t3a_content_family, 'FIFTEEN CHANGES BY MONDAY', 'D3', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.0', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 2, "title": "FIFTEEN CHANGES BY MONDAY", "source_digest": "4b7bc35217ef882c8d4c0bb529ba016424d4518ae3bf5933bc2e498135cfe30e", "mentor_brief": "The mentor reads the scripted lines of the supervisor. The mentor states the position once and does not plead, repeat, or acknowledge the participant''s personal circumstances.", "participant_pre_brief": "You are a project manager. It is Friday at 4:00 PM. The contract renewal proposal for the client organization is due Monday at 9:00 AM. Legal has returned fifteen required changes to the terms section, affecting pricing, liability caps and service levels. The changes need careful incorporation, not copy-paste; several require judgment about phrasing. The proposal system closes for scheduled maintenance at 6:00 PM Friday and reopens at 7:00 AM Monday, and the legal read-back team is unavailable after 5:30 PM Friday and returns Monday at 8:00 AM, so you have a bounded Friday window for incorporation and one hour on Monday for the read-back before the 9:00 AM delivery. Your estimate is three to four hours of focused work. No one else on the team knows this proposal. The proposal standard states that no terms change goes to a client without a legal read-back, and that the proposal is delivered complete rather than in parts.", "script": [{"beat": "B1", "type": "SAY", "spoken": "Legal have come back with fifteen required changes on the terms section. The proposal cannot go without them and the client has said Monday at nine, no extension. I will let you take it from there.", "direction": null, "capture": []}, {"beat": "B2", "type": "PAUSE", "spoken": null, "direction": "Say nothing for ten to fifteen seconds. Do not prompt or fill the silence.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, {"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C3", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4", "state": "open"}, {"set": "C4b", "state": "open"}, {"set": "C5", "state": "open"}, {"set": "C5b", "state": "open"}, {"set": "C7", "state": "open"}, {"set": "C7b", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "How are you going to take the fifteen?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C1b", "state": "update"}]}, {"beat": "B4", "type": "ASK", "spoken": "If not all fifteen land properly, what goes Monday and what does not?", "direction": "Read once, verbatim.", "capture": [{"set": "C2", "state": "update"}, {"set": "C2b", "state": "update"}, {"set": "C3", "state": "update"}, {"set": "C3b", "state": "update"}, {"set": "C7", "state": "update"}, {"set": "C7b", "state": "update"}]}, {"beat": "B5", "type": "ASK", "spoken": "What gets checked before it goes to the client?", "direction": "Read once, verbatim.", "capture": [{"set": "C4", "state": "update"}, {"set": "C4b", "state": "update"}, {"set": "C5", "state": "update"}, {"set": "C5b", "state": "update"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so I have it right — as of Monday morning, which sections are complete and which are not?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "Understood. Thank you.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3", "state": "final"}, {"set": "C4", "state": "final"}, {"set": "C5", "state": "final"}, {"set": "C7", "state": "final"}, {"set": "C9", "state": "final"}]}], "question_applicability": [{"question": "Q-D3-01", "state": "DIRECT", "basis": "Three change groups and a read-through; B3 asks the order"}, {"question": "Q-D3-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-02", "state": "DIRECT", "basis": "B4 asks what goes Monday"}, {"question": "Q-D3-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-03", "state": "DIRECT", "basis": "Three stated requirements, two of which pull against the third"}, {"question": "Q-D3-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-04", "state": "DIRECT", "basis": "B5 asks what is checked"}, {"question": "Q-D3-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-05", "state": "DIRECT", "basis": "Three means"}, {"question": "Q-D3-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-06a", "state": "NOT SERVED", "basis": "blocking_dependency is an explicit none. THE READ-BACK IS A CHECK, NOT A DEPENDENCY"}, {"question": "Q-D3-06b", "state": "NOT SERVED", "basis": "blocking_dependency is an explicit none. THE READ-BACK IS A CHECK, NOT A DEPENDENCY"}, {"question": "Q-D3-07", "state": "DIRECT", "basis": "B4 and B6 create the opportunity"}, {"question": "Q-D3-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-08", "state": "NOT SERVED", "basis": "The situation presents no change to the requirement"}, {"question": "Q-D3-09", "state": "DIRECT", "basis": "delivery_test_point at B6"}], "material_map": [{"Item": "WI1", "Item text": "the pricing changes", "Where the participant meets it": "The pre-brief", "Quoted text": "changes to the terms section, affecting pricing"}, {"Item": "WI2", "Item text": "the liability cap changes", "Where the participant meets it": "The pre-brief", "Quoted text": "changes to the terms section, affecting pricing, liability caps"}, {"Item": "WI3", "Item text": "the service level changes", "Where the participant meets it": "The pre-brief", "Quoted text": "changes to the terms section, affecting pricing, liability caps and service levels"}, {"Item": "WI4", "Item text": "the full read-through of the terms section", "Where the participant meets it": "The pre-brief", "Quoted text": "terms section, affecting pricing"}, {"Item": "SR1", "Item text": "no terms change goes to a client without a legal read-back", "Where the participant meets it": "The pre-brief", "Quoted text": "terms change goes to a client without a legal"}, {"Item": "SR2", "Item text": "the proposal is delivered complete rather than in parts", "Where the participant meets it": "The pre-brief", "Quoted text": "no terms change goes to a client without a legal read-back, and that the proposal is delivered complete rather than in parts"}, {"Item": "SR3", "Item text": "the proposal reaches the client Monday at 9:00 AM", "Where the participant meets it": "The pre-brief", "Quoted text": "proposal for the client organization is due Monday"}], "source_sheet": {"d3_situation_class": "SC-D3-1", "workplace_demand": "Fifteen judgment-bearing changes against a fixed client deadline.", "relevant_conduct": "The order stated across the three change groups; what was reduced or deferred; what was stated as held; which checks were named; which means were used; what was stated about any section not complete; the answer at B6.", "irrelevant_conduct": "Whether the request was reasonable; the participant''s weekend; the legal content.", "stated_standard": "\"no terms change goes to a client without a legal read-back\" and \"the proposal is delivered complete rather than in parts.\" Exact pre-brief text.", "stated_standard_source_quote_or_location": "\"no terms change goes to a client without a legal read-back\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations recorded.", "unsupported_inferences": "That accepting was required; that working the weekend is a virtue; anything about commitment or discipline.", "compatibility_class": "S2-SEVEN-BEAT", "work_items": [{"id": "WI1", "text": "the pricing changes"}, {"id": "WI2", "text": "the liability cap changes"}, {"id": "WI3", "text": "the service level changes"}, {"id": "WI4", "text": "the full read-through of the terms section"}], "deliverable_components": [{"id": "DC1", "text": "the pricing terms"}, {"id": "DC2", "text": "the liability terms"}, {"id": "DC3", "text": "the service level terms"}, {"id": "DC4", "text": "the assembled proposal"}], "stated_requirements": [{"id": "SR1", "text": "no terms change goes to a client without a legal read-back"}, {"id": "SR2", "text": "the proposal is delivered complete rather than in parts"}, {"id": "SR3", "text": "the proposal reaches the client Monday at 9:00 AM"}], "available_checks": [{"id": "CK1", "text": "cross-reference each incorporated change against the legal markup"}, {"id": "CK2", "text": "a full read-through of the terms section after all changes land"}], "available_means": [{"id": "MN1", "text": "group the fifteen by type and work each group through"}, {"id": "MN2", "text": "send the incorporated changes to legal for read-back before Monday"}, {"id": "MN3", "text": "ask the supervisor which of the three groups must land if not all do"}], "time_available": "About two hours Friday before the system closes at 6:00 PM, and one hour Monday from 8:00 AM. Exact pre-brief text.", "work_required": "\"three to four hours of focused work.\" Exact pre-brief text.", "blocking_dependency": null, "dependency_holder_role": null, "moved_standard_point": null, "handover_point": "Monday at 9:00 AM, stated at B4.", "delivery_state_record": "At B6: fifteen changes returned by legal; none incorporated; a read-back not yet run.", "delivery_test_point": "B6", "list_note": null, "source_note": "blocking_dependency: LEGAL HAS ALREADY DELIVERED THE MARKUP; the read-back is a check, not a dependency the work waits on. A build that treats the read-back as a blocking dependency has misread the field.", "situation_class_label": "More work than the available time allows, with the gap stated in the situation", "observation_mode_label": "structured_live_session", "min_seconds": 480, "max_seconds": 900}, "source_identifier": "SRC-D3-S2-010", "stage_code": "S2", "source_version_hash": "4b7bc35217ef882c8d4c0bb529ba016424d4518ae3bf5933bc2e498135cfe30e", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D3-S2-010' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D3-S3-001', 'source'::public.t3a_content_family, 'MONDAY MORNING, THREE CLAIMS', 'D3', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.0', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 3, "title": "MONDAY MORNING, THREE CLAIMS", "source_digest": "af42e36d3ba43465a802872f7090a1b2963df9419d99cdf0a30839f9d9e0f91a", "brief_summary": "The participant reads the brief in the pack and submits the work the submission instructions name.", "participant_pack": [{"document": "D1", "title": "The brief", "text": "You manage a property portfolio. At 8:00 AM Monday three matters arrive at once. The heating system on floors three to five of the flagship property failed overnight, and two anchor tenants have complained; one has an investor presentation at 2:00 PM today. The finance team needs your sign-off on a quarterly maintenance reconciliation due to the chief financial officer by noon Tuesday; you have not reviewed it, it covers eight months, and two line items are flagged. A tenant at a secondary property has submitted a written complaint about repeated lighting failures against a commitment made before you arrived; the work order opened six weeks ago has no update logged. Your director is traveling and expects a written update before 5:00 PM. One junior coordinator can take one task with clear instructions."}], "submission_instructions": "Produce a triage plan stating what you address first, second and third and what you delegate; a written update to your director; and a register of what you assumed, what you do not know and what you would verify. The work is submitted within 3 days.", "question_applicability": [{"question": "Q-D3-01", "state": "DIRECT", "basis": "The brief asks for first, second and third"}, {"question": "Q-D3-01b", "state": "CONDITIONAL", "basis": "ORDER PERSISTED AS A SEQUENCE"}, {"question": "Q-D3-02", "state": "DIRECT", "basis": "Three matters, one day"}, {"question": "Q-D3-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-03", "state": "DIRECT", "basis": "Two stated requirements on different horizons"}, {"question": "Q-D3-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-04", "state": "DIRECT", "basis": "The assumption register is the verification surface"}, {"question": "Q-D3-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-05", "state": "DIRECT", "basis": "Three means evidenced in the submission"}, {"question": "Q-D3-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-06a", "state": "NOT SERVED", "basis": "blocking_dependency is an explicit none"}, {"question": "Q-D3-06b", "state": "NOT SERVED", "basis": "blocking_dependency is an explicit none"}, {"question": "Q-D3-07", "state": "DIRECT", "basis": "The update identifies what is incomplete"}, {"question": "Q-D3-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-08", "state": "NOT SERVED", "basis": "Stage 3 launch design"}, {"question": "Q-D3-09", "state": "NOT SERVED", "basis": "Stage 3 launch design"}], "material_map": [{"Item": "WI1", "Item text": "the heating failure and the 2:00 PM tenant presentation", "Where the participant meets it": "Pack document D1", "Quoted text": "heating system on floors three to five of the flagship property failed overnight, and two anchor tenants have complained; one has an"}, {"Item": "WI2", "Item text": "the maintenance reconciliation due noon Tuesday", "Where the participant meets it": "Pack document D1", "Quoted text": "maintenance reconciliation due to the chief financial officer by noon Tuesday"}, {"Item": "WI3", "Item text": "the lighting complaint and its stale work order", "Where the participant meets it": "Pack document D1", "Quoted text": "complaint about repeated lighting failures against a commitment made before you arrived; the work order"}, {"Item": "SR1", "Item text": "a written update reaches the director before 5:00 PM", "Where the participant meets it": "Submission instructions", "Quoted text": "written update to your director"}, {"Item": "SR2", "Item text": "the reconciliation reaches the chief financial officer by noon Tuesday", "Where the participant meets it": "Pack document D1", "Quoted text": "reconciliation due to the chief financial officer by noon Tuesday"}], "source_sheet": {"d3_situation_class": "SC-D3-1", "workplace_demand": "Holding more work than can be carried and stating which parts will not be.", "relevant_conduct": "The order stated; what was reduced, deferred or dropped; what was stated as held; which verifications were named and against what; which means were used; what the update identified as incomplete.", "irrelevant_conduct": "Whether the triage order is correct; who holds the lighting commitment, WHICH IS A D2 MATTER; the heating fault.", "stated_standard": "\"a written update before 5:00 PM\"; \"due to the chief financial officer by noon Tuesday.\" Exact brief text.", "stated_standard_source_quote_or_location": "\"a written update before 5:00 PM\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Extended time and assistive software permitted and recorded.", "unsupported_inferences": "That any ordering is correct; that delegating indicates anything; anything about the predecessor.", "compatibility_class": "S3-ASYNC-SUBMISSION", "work_items": [{"id": "WI1", "text": "the heating failure and the 2:00 PM tenant presentation"}, {"id": "WI2", "text": "the maintenance reconciliation due noon Tuesday"}, {"id": "WI3", "text": "the lighting complaint and its stale work order"}], "deliverable_components": [{"id": "DC1", "text": "the triage plan"}, {"id": "DC2", "text": "the director update"}, {"id": "DC3", "text": "the assumption register"}], "stated_requirements": [{"id": "SR1", "text": "a written update reaches the director before 5:00 PM"}, {"id": "SR2", "text": "the reconciliation reaches the chief financial officer by noon Tuesday"}], "available_checks": [{"id": "CK1", "text": "reconcile the two flagged line items against the underlying records"}, {"id": "CK2", "text": "confirm the work order status against the maintenance system rather than the complaint"}], "available_means": [{"id": "MN1", "text": "assign one task to the junior coordinator with stated instructions"}, {"id": "MN2", "text": "ask the finance team for a one-day extension on the reconciliation"}, {"id": "MN3", "text": "state the assumptions in the register rather than resolving them"}], "time_available": "To 5:00 PM today for the update and noon Tuesday for the reconciliation.", "work_required": "Three matters against one coordinator and one working day.", "blocking_dependency": null, "dependency_holder_role": null, "handover_point": "The 5:00 PM update.", "list_note": null, "source_note": "blocking_dependency: THE DIRECTOR''S TRAVEL IS AN ABSENCE, NOT A DEPENDENCY THE WORK WAITS ON. Shared with SRC-D2-S3-002. One submission may carry both records.", "situation_class_label": "More work than the available time allows, with the gap stated in the situation", "observation_mode_label": "work_sample", "ai_use": "AI_USE_DECLARATION_REQUIRED", "submission_window_days": 3}, "source_identifier": "SRC-D3-S3-001", "stage_code": "S3", "source_version_hash": "af42e36d3ba43465a802872f7090a1b2963df9419d99cdf0a30839f9d9e0f91a", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D3-S3-001' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D3-S3-002', 'source'::public.t3a_content_family, 'THE HANDOFF THAT KEEPS FAILING', 'D3', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.0', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 3, "title": "THE HANDOFF THAT KEEPS FAILING", "source_digest": "8f576c0d7ff34bc1c46a529d937a0cdac52e899d4b966bf1047a3df31daff5a1", "brief_summary": "The participant reads the brief in the pack and submits the work the submission instructions name.", "participant_pack": [{"document": "D1", "title": "The brief", "text": "You are a process improvement analyst at a manufacturing firm. The handoff between the production and packaging shifts is failing: over the past quarter, eleven batches have moved to packaging without their completed quality records, and each time packaging has had to hold the batch and chase the record. The current handoff is verbal, at shift change, with no written record. You have been asked to redesign it. You have: the eleven incident logs; the current shift-change procedure, which is one paragraph; a four-week window before the next audit; and no authority to change staffing or shift times. The plant standard states that every batch reaching packaging carries a completed quality record, and that any procedure change is trialled on one line before it is adopted across the plant."}], "submission_instructions": "Produce a redesigned handoff procedure; a trial plan for one line stating what you would verify and how; and a statement of what the redesign does not solve and why. The work is submitted within 3 days.", "question_applicability": [{"question": "Q-D3-01", "state": "DIRECT", "basis": "Four work items in four weeks"}, {"question": "Q-D3-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-02", "state": "DIRECT", "basis": "Trial before adoption means not everything lands before the audit"}, {"question": "Q-D3-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-03", "state": "DIRECT", "basis": "Three stated requirements that pull against each other"}, {"question": "Q-D3-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-04", "state": "DIRECT", "basis": "The trial plan is the verification surface and the brief asks for it"}, {"question": "Q-D3-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-05", "state": "DIRECT", "basis": "Three means"}, {"question": "Q-D3-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-06a", "state": "DIRECT", "basis": "The authority limit is the constraint the participant cannot move"}, {"question": "Q-D3-06b", "state": "DIRECT", "basis": "The authority limit is the constraint the participant cannot move"}, {"question": "Q-D3-07", "state": "DIRECT", "basis": "THE BRIEF ASKS DIRECTLY what the redesign does not solve"}, {"question": "Q-D3-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-08", "state": "NOT SERVED", "basis": "Stage 3 launch design"}, {"question": "Q-D3-09", "state": "NOT SERVED", "basis": "Stage 3 launch design"}], "material_map": [{"Item": "WI1", "Item text": "analyze the eleven incident logs", "Where the participant meets it": "Pack document D1", "Quoted text": "eleven incident logs; the"}, {"Item": "WI2", "Item text": "redesign the handoff procedure", "Where the participant meets it": "Submission instructions", "Quoted text": "redesigned handoff procedure; a trial plan for one line stating what you would verify and how; and a statement of what the"}, {"Item": "WI3", "Item text": "build the one-line trial plan", "Where the participant meets it": "Submission instructions", "Quoted text": "trial plan for one line"}, {"Item": "WI4", "Item text": "state what remains unsolved", "Where the participant meets it": "Submission instructions", "Quoted text": "a statement of what the redesign does not solve"}, {"Item": "SR1", "Item text": "every batch reaching packaging carries a completed quality record", "Where the participant meets it": "Pack document D1", "Quoted text": "every batch reaching packaging carries a completed quality record"}, {"Item": "SR2", "Item text": "any change is trialled on one line before plant-wide adoption", "Where the participant meets it": "Pack document D1", "Quoted text": "carries a completed quality record, and that any procedure change is trialled on one line before it is adopted across the plant"}, {"Item": "SR3", "Item text": "the redesign is in place before the audit in four weeks", "Where the participant meets it": "Pack document D1", "Quoted text": "asked to redesign it"}], "source_sheet": {"d3_situation_class": "SC-D3-7", "workplace_demand": "Redesigning the point at which work passes between two parties incomplete.", "relevant_conduct": "The order stated for the four weeks; what was reduced or deferred from the redesign; what was stated as held; which verifications were named; which means were used; what was done about the staffing constraint; what the submission identified as unsolved.", "irrelevant_conduct": "Whether the redesign would work; the shift workers'' conduct; who was responsible for the eleven batches, WHICH IS A D2 MATTER.", "stated_standard": "\"every batch reaching packaging carries a completed quality record\" and \"any procedure change is trialled on one line before it is adopted.\" Exact brief text.", "stated_standard_source_quote_or_location": "\"every batch reaching packaging carries a completed quality record\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Extended time and assistive software permitted and recorded.", "unsupported_inferences": "That the verbal handoff was the cause; that a written record will fix it; anything about process thinking as a trait.", "compatibility_class": "S3-ASYNC-SUBMISSION", "work_items": [{"id": "WI1", "text": "analyze the eleven incident logs"}, {"id": "WI2", "text": "redesign the handoff procedure"}, {"id": "WI3", "text": "build the one-line trial plan"}, {"id": "WI4", "text": "state what remains unsolved"}], "deliverable_components": [{"id": "DC1", "text": "the redesigned procedure"}, {"id": "DC2", "text": "the trial plan"}, {"id": "DC3", "text": "the unsolved statement"}], "stated_requirements": [{"id": "SR1", "text": "every batch reaching packaging carries a completed quality record"}, {"id": "SR2", "text": "any change is trialled on one line before plant-wide adoption"}, {"id": "SR3", "text": "the redesign is in place before the audit in four weeks"}], "available_checks": [{"id": "CK1", "text": "verify the redesigned procedure against all eleven incident logs"}, {"id": "CK2", "text": "define what the one-line trial measures and against what threshold"}], "available_means": [{"id": "MN1", "text": "introduce a written handoff record without changing staffing or shift times"}, {"id": "MN2", "text": "move the quality record check earlier in production rather than at handoff"}, {"id": "MN3", "text": "stage the rollout so the trial completes before the audit"}], "time_available": "Four weeks to the audit.", "work_required": "An analysis, a redesign, a trial plan and a gap statement.", "blocking_dependency": "No authority to change staffing or shift times.", "dependency_holder_role": null, "handover_point": "Adoption after the trial.", "list_note": null, "source_note": "dependency_holder_role: The constraint is an authority limit, not a person the work waits on.", "situation_class_label": "Work received from, or passed to, another party in an incomplete state", "observation_mode_label": "work_sample", "ai_use": "AI_USE_DECLARATION_REQUIRED", "submission_window_days": 3}, "source_identifier": "SRC-D3-S3-002", "stage_code": "S3", "source_version_hash": "8f576c0d7ff34bc1c46a529d937a0cdac52e899d4b966bf1047a3df31daff5a1", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D3-S3-002' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D3-S3-003', 'source'::public.t3a_content_family, 'FIVE DAYS TO GO-LIVE, SEVENTY PER CENT TESTED', 'D3', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.0', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 3, "title": "FIVE DAYS TO GO-LIVE, SEVENTY PER CENT TESTED", "source_digest": "b74e5e7fab197b9301074e0ac4e410598a89e85f2aae514390ded9dd9817e7ae", "brief_summary": "The participant reads the brief in the pack and submits the work the submission instructions name.", "participant_pack": [{"document": "D1", "title": "The brief", "text": "You are an implementation lead at an information technology services firm. Your firm is migrating a regional healthcare network''s patient scheduling system to your cloud platform. The implementation was planned for six weeks; a regulatory deadline on the client''s side pulled the go-live forward by two weeks, and you are five days out. The engineering lead reports that data migration testing is seventy per cent complete, and the remaining thirty per cent is the most complex module — historical records with nested referral chains. She estimates three further days of testing, which would push one day past go-live. The account manager reports that the client expects a full cutover with no phased fallback. The engagement terms state that no module goes live without completed migration testing, and that the go-live date is fixed by the client''s regulatory deadline."}], "submission_instructions": "Produce a go-live plan stating what goes live and what does not; a verification schedule for the five days; and a statement of what will be completed by go-live, what will remain incomplete, and the verification points before each release. The work is submitted within 3 days.", "question_applicability": [{"question": "Q-D3-01", "state": "DIRECT", "basis": "Four work items in five days"}, {"question": "Q-D3-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-02", "state": "DIRECT", "basis": "The brief asks what goes live and what does not"}, {"question": "Q-D3-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-03", "state": "DIRECT", "basis": "THREE stated requirements, two of which are in direct conflict"}, {"question": "Q-D3-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-04", "state": "DIRECT", "basis": "The brief asks for a verification schedule"}, {"question": "Q-D3-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-05", "state": "DIRECT", "basis": "Three means"}, {"question": "Q-D3-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-06a", "state": "DIRECT", "basis": "The three-day testing requirement is the binding constraint"}, {"question": "Q-D3-06b", "state": "DIRECT", "basis": "The three-day testing requirement is the binding constraint"}, {"question": "Q-D3-07", "state": "DIRECT", "basis": "The brief asks what is going live untested"}, {"question": "Q-D3-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-08", "state": "NOT SERVED", "basis": "Stage 3 launch design. A MOVED DATE IN THE BACKSTORY IS NOT A MOVED STANDARD WITHIN THE OBSERVATION"}, {"question": "Q-D3-09", "state": "NOT SERVED", "basis": "Stage 3 launch design"}], "material_map": [{"Item": "WI1", "Item text": "complete testing on the seventy per cent already covered", "Where the participant meets it": "Pack document D1", "Quoted text": "testing is seventy per cent complete, and the remaining thirty per cent"}, {"Item": "WI2", "Item text": "test the historical records module", "Where the participant meets it": "Pack document D1", "Quoted text": "testing is seventy per cent complete, and the remaining thirty per cent is the most complex module — historical records"}, {"Item": "WI3", "Item text": "prepare the cutover", "Where the participant meets it": "Pack document D1", "Quoted text": "cutover with no phased"}, {"Item": "WI4", "Item text": "prepare the fallback position", "Where the participant meets it": "Pack document D1", "Quoted text": "with no phased fallback"}, {"Item": "SR1", "Item text": "no module goes live without completed migration testing", "Where the participant meets it": "Pack document D1", "Quoted text": "module goes live without completed migration testing"}, {"Item": "SR2", "Item text": "go-live happens on the fixed regulatory date", "Where the participant meets it": "Pack document D1", "Quoted text": "live without completed migration testing, and that the go-live date is fixed by the client''s regulatory"}, {"Item": "SR3", "Item text": "the client expects a full cutover with no phased fallback", "Where the participant meets it": "Pack document D1", "Quoted text": "client expects a full cutover with no phased fallback"}], "source_sheet": {"d3_situation_class": "SC-D3-4", "workplace_demand": "A cutover that can be completed only in part against a date that cannot move.", "relevant_conduct": "The order stated across the five days; which modules were deferred or dropped from the cutover; what was stated as held; which verifications were named; which means were used; what was done about the three-day testing gap; what the plan identified as going live untested.", "irrelevant_conduct": "Whether the plan is achievable; the regulatory deadline; the engineering estimate''s accuracy.", "stated_standard": "\"no module goes live without completed migration testing\" and \"the go-live date is fixed by the client''s regulatory deadline.\" Exact brief text. THESE TWO CANNOT BOTH HOLD and that is the situation.", "stated_standard_source_quote_or_location": "\"no module goes live without completed migration testing\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Extended time and assistive software permitted and recorded.", "unsupported_inferences": "That a phased cutover is better; that the testing should be compressed; anything about risk appetite.", "compatibility_class": "S3-ASYNC-SUBMISSION", "work_items": [{"id": "WI1", "text": "complete testing on the seventy per cent already covered"}, {"id": "WI2", "text": "test the historical records module"}, {"id": "WI3", "text": "prepare the cutover"}, {"id": "WI4", "text": "prepare the fallback position"}], "deliverable_components": [{"id": "DC1", "text": "the current-records modules"}, {"id": "DC2", "text": "the historical records module"}, {"id": "DC3", "text": "the referral chain data"}], "stated_requirements": [{"id": "SR1", "text": "no module goes live without completed migration testing"}, {"id": "SR2", "text": "go-live happens on the fixed regulatory date"}, {"id": "SR3", "text": "the client expects a full cutover with no phased fallback"}], "available_checks": [{"id": "CK1", "text": "completed migration testing per module"}, {"id": "CK2", "text": "a referral-chain integrity check on a sample before cutover"}], "available_means": [{"id": "MN1", "text": "go live with the tested modules and hold the historical records module"}, {"id": "MN2", "text": "run testing in parallel with cutover preparation"}, {"id": "MN3", "text": "propose a phased cutover to the client against their stated expectation"}], "time_available": "Five days.", "work_required": "Three days of remaining testing plus cutover preparation.", "blocking_dependency": "The historical records module cannot be tested in less than three days.", "dependency_holder_role": "The engineering lead. RETAINED AND NEVER RENDERED.", "handover_point": "Go-live.", "list_note": null, "source_note": null, "situation_class_label": "A deliverable that can be completed only in part by the time it is due", "observation_mode_label": "work_sample", "ai_use": "AI_USE_DECLARATION_REQUIRED", "submission_window_days": 3}, "source_identifier": "SRC-D3-S3-003", "stage_code": "S3", "source_version_hash": "b74e5e7fab197b9301074e0ac4e410598a89e85f2aae514390ded9dd9817e7ae", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D3-S3-003' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D3-S3-004', 'source'::public.t3a_content_family, 'THREE HUNDRED AND FORTY FILES OVERNIGHT', 'D3', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.0', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 3, "title": "THREE HUNDRED AND FORTY FILES OVERNIGHT", "source_digest": "b8ce525e5fccac1ba776f39388d16e666f0d2863ab514764d9ea20ec395bac87", "brief_summary": "The participant reads the brief in the pack and submits the work the submission instructions name.", "participant_pack": [{"document": "D1", "title": "The brief", "text": "You are an operations manager at an asset management firm. At 6:45 AM Tuesday the security team reports that a service account with elevated privileges accessed three hundred and forty client agreement files between 1:15 AM and 3:40 AM, matching no scheduled process. The account is disabled and logs are under review. The document system is the firm''s only store for client agreements, compliance filings and audit reports, and it is now read-only pending the review, so no filings can be made. Two regulatory filings are due Thursday. The firm''s incident procedure states that a suspected unauthorised access is assessed and reported to the chief operating officer within four hours, and that no filing is made from an unverified record."}], "submission_instructions": "Produce a four-hour assessment for the chief operating officer stating what is known and not known; a plan for the two Thursday filings; and a verification list stating what must be confirmed before any record is used. The work is submitted within 3 days.", "question_applicability": [{"question": "Q-D3-01", "state": "DIRECT", "basis": "Three work items against two deadlines"}, {"question": "Q-D3-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-02", "state": "DIRECT", "basis": "The filings may not all be verifiable"}, {"question": "Q-D3-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-03", "state": "DIRECT", "basis": "Three stated requirements, two in tension"}, {"question": "Q-D3-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-04", "state": "DIRECT", "basis": "THE BRIEF ASKS FOR THE VERIFICATION LIST DIRECTLY — the strongest CE-D3-04 source in this bank"}, {"question": "Q-D3-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-05", "state": "DIRECT", "basis": "Three means"}, {"question": "Q-D3-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-06a", "state": "DIRECT", "basis": "The read-only system is the blocking dependency"}, {"question": "Q-D3-06b", "state": "DIRECT", "basis": "The read-only system is the blocking dependency"}, {"question": "Q-D3-07", "state": "DIRECT", "basis": "The assessment states what is not known"}, {"question": "Q-D3-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-08", "state": "NOT SERVED", "basis": "Stage 3 launch design"}, {"question": "Q-D3-09", "state": "NOT SERVED", "basis": "Stage 3 launch design"}], "material_map": [{"Item": "WI1", "Item text": "the four-hour assessment", "Where the participant meets it": "Pack document D1", "Quoted text": "four hours, and that"}, {"Item": "WI2", "Item text": "the two Thursday filings", "Where the participant meets it": "Pack document D1", "Quoted text": "filings are due Thursday"}, {"Item": "WI3", "Item text": "the record verification list", "Where the participant meets it": "Submission instructions", "Quoted text": "verification list stating what must be confirmed before any record"}, {"Item": "SR1", "Item text": "the assessment reaches the chief operating officer within four hours", "Where the participant meets it": "Pack document D1", "Quoted text": "chief operating officer within four hours"}, {"Item": "SR2", "Item text": "no filing is made from an unverified record", "Where the participant meets it": "Pack document D1", "Quoted text": "filing is made from an unverified record"}, {"Item": "SR3", "Item text": "both regulatory filings are made by Thursday", "Where the participant meets it": "Pack document D1", "Quoted text": "regulatory filings are due Thursday"}], "source_sheet": {"d3_situation_class": "SC-D3-2", "workplace_demand": "Meeting fixed filing dates while the system holding the records is unavailable.", "relevant_conduct": "The order stated; what was deferred from the Thursday filings; what was stated as held; which verifications were named; which means were used; what was done about the read-only system; what the assessment identified as not known.", "irrelevant_conduct": "The cause of the access; who is responsible, WHICH IS A D2 MATTER; the security team''s handling.", "stated_standard": "\"assessed and reported to the chief operating officer within four hours\" and \"no filing is made from an unverified record.\" Exact brief text.", "stated_standard_source_quote_or_location": "\"assessed and reported to the chief operating officer within four hours\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Extended time and assistive software permitted and recorded.", "unsupported_inferences": "That the access was malicious; that the filings should be delayed; anything about composure or security instinct.", "compatibility_class": "S3-ASYNC-SUBMISSION", "work_items": [{"id": "WI1", "text": "the four-hour assessment"}, {"id": "WI2", "text": "the two Thursday filings"}, {"id": "WI3", "text": "the record verification list"}], "deliverable_components": [{"id": "DC1", "text": "the assessment"}, {"id": "DC2", "text": "the first Thursday filing"}, {"id": "DC3", "text": "the second Thursday filing"}, {"id": "DC4", "text": "the verification list"}], "stated_requirements": [{"id": "SR1", "text": "the assessment reaches the chief operating officer within four hours"}, {"id": "SR2", "text": "no filing is made from an unverified record"}, {"id": "SR3", "text": "both regulatory filings are made by Thursday"}], "available_checks": [{"id": "CK1", "text": "confirm which of the three hundred and forty files the Thursday filings depend on"}, {"id": "CK2", "text": "verify a filing record against a source outside the document system"}], "available_means": [{"id": "MN1", "text": "prepare the filings from verified copies held outside the system"}, {"id": "MN2", "text": "request a filing extension from the regulator"}, {"id": "MN3", "text": "file what can be verified and identify what cannot"}], "time_available": "Four hours to the assessment, two days to the filings.", "work_required": "An assessment, two filings and a verification list, with the record store read-only.", "blocking_dependency": "The document system is read-only pending the security review.", "dependency_holder_role": "The security team. RETAINED AND NEVER RENDERED.", "handover_point": "The assessment at four hours and the filings on Thursday.", "list_note": null, "source_note": null, "situation_class_label": "A tool or resource the work depends on is unavailable, with no restoration time given", "observation_mode_label": "work_sample", "ai_use": "AI_USE_DECLARATION_REQUIRED", "submission_window_days": 3}, "source_identifier": "SRC-D3-S3-004", "stage_code": "S3", "source_version_hash": "b8ce525e5fccac1ba776f39388d16e666f0d2863ab514764d9ea20ec395bac87", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D3-S3-004' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D3-S3-005', 'source'::public.t3a_content_family, 'THE BRIEF WITH NO DETAIL', 'D3', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.0', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 3, "title": "THE BRIEF WITH NO DETAIL", "source_digest": "1c9ed36bea9dc3e431afe070b77b3d632b339f5f066c1dd4c3fc823a14384129", "brief_summary": "The participant reads the brief in the pack and submits the work the submission instructions name.", "participant_pack": [{"document": "D1", "title": "The brief", "text": "You are a business analyst asked to lead the initial findings presentation for the client organization. The instruction arrived at 4:30 PM Friday: take the lead on pulling together the initial findings deck, use the discovery data, the client meeting is Thursday at 10:00 AM, make it sharp, review Wednesday afternoon. No further detail was given. The discovery package holds six months of complaint volume data, three interview transcripts, a process flow diagram and an unfinished benchmarking comparison whose author is on leave until Wednesday. Three past initial findings presentations sit on the shared drive, each with a different structure and depth. There is no template. The client sponsor has previously asked for concrete numbers rather than generalities, and the known bottleneck was identified in the interviews but never quantified."}], "submission_instructions": "Produce a note stating how you interpreted the brief, the structure you will use and the data you will prioritize; an outline of the presentation with the key findings and how you will handle the incomplete benchmarking; and a register of your assumptions and what you would verify with more time. The work is submitted within 3 days.", "question_applicability": [{"question": "Q-D3-01", "state": "DIRECT", "basis": "Four work items; the brief asks for prioritisation"}, {"question": "Q-D3-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-02", "state": "DIRECT", "basis": "The brief asks what is left out"}, {"question": "Q-D3-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-03", "state": "DIRECT", "basis": "Two stated requirements only, both about timing"}, {"question": "Q-D3-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-04", "state": "DIRECT", "basis": "The register is the verification surface"}, {"question": "Q-D3-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-05", "state": "DIRECT", "basis": "Three means"}, {"question": "Q-D3-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-06a", "state": "DIRECT", "basis": "The unreachable analyst is the blocking dependency"}, {"question": "Q-D3-06b", "state": "DIRECT", "basis": "The unreachable analyst is the blocking dependency"}, {"question": "Q-D3-07", "state": "DIRECT", "basis": "The brief asks how the incomplete benchmarking is handled"}, {"question": "Q-D3-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-08", "state": "NOT SERVED", "basis": "Stage 3 launch design"}, {"question": "Q-D3-09", "state": "NOT SERVED", "basis": "Stage 3 launch design"}], "material_map": [{"Item": "WI1", "Item text": "interpret the brief", "Where the participant meets it": "Submission instructions", "Quoted text": "interpreted the brief, the"}, {"Item": "WI2", "Item text": "select and prioritize the discovery data", "Where the participant meets it": "Pack document D1", "Quoted text": "discovery data, the client"}, {"Item": "WI3", "Item text": "handle the unfinished benchmarking", "Where the participant meets it": "Pack document D1", "Quoted text": "unfinished benchmarking comparison whose"}, {"Item": "WI4", "Item text": "build the outline", "Where the participant meets it": "Submission instructions", "Quoted text": "outline of the presentation"}, {"Item": "SR1", "Item text": "the deck is ready for Thursday at 10:00 AM", "Where the participant meets it": "Pack document D1", "Quoted text": "deck, use the discovery data, the client meeting is Thursday"}, {"Item": "SR2", "Item text": "the deck is reviewed Wednesday afternoon", "Where the participant meets it": "Pack document D1", "Quoted text": "deck, use the discovery data, the client meeting is Thursday at 10:00 AM, make it sharp, review Wednesday afternoon"}], "source_sheet": {"d3_situation_class": "SC-D3-6", "workplace_demand": "Delivering to a specification that does not exist.", "relevant_conduct": "The order stated; what was built and what was left out; what was stated as held; which verifications were named and against what; which means were used; what was done about the unreachable analyst; what the outline identified as incomplete.", "irrelevant_conduct": "Whether the interpretation is right; who should have briefed better, WHICH IS A D2 MATTER; the analytical findings.", "stated_standard": "\"the client meeting is Thursday at 10:00 AM\" and \"review Wednesday afternoon.\" Exact brief text. NOTHING ELSE ESTABLISHES A REQUIREMENT AND THE ABSENCE IS THE SITUATION.", "stated_standard_source_quote_or_location": "\"the client meeting is Thursday at 10:00 AM\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Extended time and assistive software permitted and recorded.", "unsupported_inferences": "That clarification was required; that building on an assumption was wrong; anything about initiative.", "compatibility_class": "S3-ASYNC-SUBMISSION", "work_items": [{"id": "WI1", "text": "interpret the brief"}, {"id": "WI2", "text": "select and prioritize the discovery data"}, {"id": "WI3", "text": "handle the unfinished benchmarking"}, {"id": "WI4", "text": "build the outline"}], "deliverable_components": [{"id": "DC1", "text": "the interpretation note"}, {"id": "DC2", "text": "the presentation outline"}, {"id": "DC3", "text": "the benchmarking section"}, {"id": "DC4", "text": "the assumption register"}], "stated_requirements": [{"id": "SR1", "text": "the deck is ready for Thursday at 10:00 AM"}, {"id": "SR2", "text": "the deck is reviewed Wednesday afternoon"}], "available_checks": [{"id": "CK1", "text": "quantify the bottleneck against the complaint volume data before presenting it"}, {"id": "CK2", "text": "compare the proposed structure against the three past presentations"}], "available_means": [{"id": "MN1", "text": "state the interpretation for confirmation at the Wednesday review"}, {"id": "MN2", "text": "present the benchmarking as a partial with its gaps marked"}, {"id": "MN3", "text": "build the structure and leave the benchmarking section for Wednesday"}], "time_available": "From Friday evening to Thursday morning, with one checkpoint.", "work_required": "An interpretation, a structure, a prioritisation and an outline.", "blocking_dependency": "The benchmarking author is on leave until Wednesday and unreachable.", "dependency_holder_role": "A junior analyst. RETAINED AND NEVER RENDERED.", "handover_point": "The Wednesday review and the Thursday meeting.", "list_note": null, "source_note": "Shared with SRC-D2-S3-006. One submission may carry both records.", "situation_class_label": "Work that arrives without a specification sufficient to complete it", "observation_mode_label": "work_sample", "ai_use": "AI_USE_DECLARATION_REQUIRED", "submission_window_days": 3}, "source_identifier": "SRC-D3-S3-005", "stage_code": "S3", "source_version_hash": "1c9ed36bea9dc3e431afe070b77b3d632b339f5f066c1dd4c3fc823a14384129", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D3-S3-005' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D3-S3-006', 'source'::public.t3a_content_family, 'SIX PROPERTIES, THREE NIGHTS, ONE PATCH', 'D3', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.0', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 3, "title": "SIX PROPERTIES, THREE NIGHTS, ONE PATCH", "source_digest": "08c3409c9123a8529d98ada59c137ed602897fc549055ddd8229e613b59f1cd4", "brief_summary": "The participant reads the brief in the pack and submits the work the submission instructions name.", "participant_pack": [{"document": "D1", "title": "The brief", "text": "You are running a system rollout across a property group. On Monday the vendor states that a security patch must be applied to all six live properties before any new go-live proceeds. Each patch needs four hours of downtime and the vendor supports only two at a time. On Tuesday your director states that the chief executive has committed the Friday go-live date to the ownership group and it is not moving. The general manager of the highest-revenue property in Friday''s wave states that occupancy is ninety-four per cent this weekend and any front-desk disruption during check-in will be held against you. Patching can run overnight but needs on-site support; your three-person team can cover two properties a night, so six properties take three nights and leave Thursday for testing. The vendor offers remote support at twenty-five hundred dollars per property, compressing it to two nights. The patch affects only a secondary encryption module, not booking. Your team lead says it can be done with zero buffer."}], "submission_instructions": "Produce a delivery plan stating the sequence, the resource route selected, what will be completed by Friday and what will not, and the checks required before each property proceeds; and a day-by-day timeline with single points of failure flagged. The work is submitted within 3 days.", "question_applicability": [{"question": "Q-D3-01", "state": "DIRECT", "basis": "Four work items in a fixed week"}, {"question": "Q-D3-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-02", "state": "DIRECT", "basis": "The zero-buffer position means something gives"}, {"question": "Q-D3-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-03", "state": "DIRECT", "basis": "Three stated requirements"}, {"question": "Q-D3-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-04", "state": "DIRECT", "basis": "The brief asks for the timeline with failure points flagged"}, {"question": "Q-D3-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-05", "state": "DIRECT", "basis": "Three means, one of which carries a stated cost"}, {"question": "Q-D3-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-06a", "state": "DIRECT", "basis": "The vendor''s two-at-a-time limit is the binding constraint"}, {"question": "Q-D3-06b", "state": "DIRECT", "basis": "The vendor''s two-at-a-time limit is the binding constraint"}, {"question": "Q-D3-07", "state": "DIRECT", "basis": "The brief asks what will not be completed by Friday"}, {"question": "Q-D3-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-08", "state": "NOT SERVED", "basis": "Stage 3 launch design"}, {"question": "Q-D3-09", "state": "NOT SERVED", "basis": "Stage 3 launch design"}], "material_map": [{"Item": "WI1", "Item text": "patch the first pair of properties", "Where the participant meets it": "Pack document D1", "Quoted text": "patch must be applied to all six live properties"}, {"Item": "WI2", "Item text": "patch the second pair", "Where the participant meets it": "Pack document D1", "Quoted text": "patch must be applied"}, {"Item": "WI3", "Item text": "patch the third pair", "Where the participant meets it": "Pack document D1", "Quoted text": "patch must be applied"}, {"Item": "WI4", "Item text": "test before Friday", "Where the participant meets it": "Pack document D1", "Quoted text": "Friday go-live date to"}, {"Item": "SR1", "Item text": "all six properties are patched before any new go-live", "Where the participant meets it": "Pack document D1", "Quoted text": "patch must be applied to all six live properties before any new"}, {"Item": "SR2", "Item text": "go-live happens Friday", "Where the participant meets it": "Pack document D1", "Quoted text": "live properties before any"}, {"Item": "SR3", "Item text": "no front-desk disruption during check-in at the high-occupancy property", "Where the participant meets it": "Pack document D1", "Quoted text": "property in Friday''s wave states that occupancy is ninety-four per cent this weekend and any front-desk disruption during"}], "source_sheet": {"d3_situation_class": "SC-D3-1", "workplace_demand": "A fixed date whose delivery depends on capacity the participant does not have.", "relevant_conduct": "The order across the nights; what was deferred or dropped; what was stated as held; which verifications were named; which means were used and at what cost; what was done about the vendor constraint; what the plan identified as not completed by Friday.", "irrelevant_conduct": "Whether the recommendation is right; whether the date should have been committed; the general manager''s warning.", "stated_standard": "\"must be applied to all six live properties before any new go-live proceeds\"; \"the Friday date is not moving.\" Exact brief text.", "stated_standard_source_quote_or_location": "\"must be applied to all six live properties before any new go-live proceeds\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Extended time and assistive software permitted and recorded.", "unsupported_inferences": "That paying for vendor support is right or wrong; that the date should be challenged; anything about risk appetite.", "compatibility_class": "S3-ASYNC-SUBMISSION", "work_items": [{"id": "WI1", "text": "patch the first pair of properties"}, {"id": "WI2", "text": "patch the second pair"}, {"id": "WI3", "text": "patch the third pair"}, {"id": "WI4", "text": "test before Friday"}], "deliverable_components": [{"id": "DC1", "text": "the six patched properties"}, {"id": "DC2", "text": "the Thursday testing window"}, {"id": "DC3", "text": "the Friday go-live"}], "stated_requirements": [{"id": "SR1", "text": "all six properties are patched before any new go-live"}, {"id": "SR2", "text": "go-live happens Friday"}, {"id": "SR3", "text": "no front-desk disruption during check-in at the high-occupancy property"}], "available_checks": [{"id": "CK1", "text": "confirm each patched property before moving to the next pair"}, {"id": "CK2", "text": "confirm the patch does not touch booking before the high-occupancy night"}], "available_means": [{"id": "MN1", "text": "buy vendor remote support to compress three nights to two"}, {"id": "MN2", "text": "sequence the high-occupancy property away from the check-in window"}, {"id": "MN3", "text": "state the zero-buffer position as an accepted risk"}], "time_available": "Monday to Friday.", "work_required": "Six patches at two a night, plus testing.", "blocking_dependency": "The vendor supports only two properties at a time.", "dependency_holder_role": "The vendor. RETAINED AND NEVER RENDERED.", "handover_point": "Friday go-live.", "list_note": null, "source_note": "Shared with SRC-D2-S3-007. One submission may carry both records.", "situation_class_label": "More work than the available time allows, with the gap stated in the situation", "observation_mode_label": "work_sample", "ai_use": "AI_USE_DECLARATION_REQUIRED", "submission_window_days": 3}, "source_identifier": "SRC-D3-S3-006", "stage_code": "S3", "source_version_hash": "08c3409c9123a8529d98ada59c137ed602897fc549055ddd8229e613b59f1cd4", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D3-S3-006' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D3-S3-007', 'source'::public.t3a_content_family, 'FORTY PER CENT LESS, SAME TWO PROGRAMS', 'D3', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.0', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 3, "title": "FORTY PER CENT LESS, SAME TWO PROGRAMS", "source_digest": "1325275c895a784f2057ecae6c87c00918d6071ad1c23e947e15c1e3a6f159c8", "brief_summary": "The participant reads the brief in the pack and submits the work the submission instructions name.", "participant_pack": [{"document": "D1", "title": "The brief", "text": "You hold program responsibility at a community organization. A provincial grant funding thirty per cent of the employment pathways program and fifteen per cent of the youth integration program has been cut by forty per cent from next quarter. The reduction is confirmed and cannot be reversed. The employment pathways manager must either cancel the spring workshop series serving sixty clients or reduce staff from four to two and a half full-time equivalents, and needs a decision by Friday. The youth integration coordinator reports that the afterschool mentoring program serving thirty-five young people loses its paid supervisor, and without a supervisor the volunteer facilitators cannot operate. The reserve fund holds about forty thousand dollars, board-earmarked for emergencies and requiring written justification. The workshop series has a seventy-eight per cent completion rate and is a reporting metric under the municipal funding agreement. An employer partner has informally offered to co-fund a placement stream if you can match staff time, but nothing is formalized."}], "submission_instructions": "Produce an allocation plan stating what you would cut, preserve and restructure; a justification memo with the trade-offs; and a delivery-state table showing which program components continue, which are reduced or deferred, the resource assigned to each, and the verification required before the next funding period begins. The work is submitted within 3 days.", "question_applicability": [{"question": "Q-D3-01", "state": "DIRECT", "basis": "Four work items against one Friday decision"}, {"question": "Q-D3-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-02", "state": "DIRECT", "basis": "The brief asks what is cut"}, {"question": "Q-D3-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-03", "state": "DIRECT", "basis": "The brief asks what is preserved; three stated requirements"}, {"question": "Q-D3-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-04", "state": "DIRECT", "basis": "Two checks, one of which guards against relying on an informal offer"}, {"question": "Q-D3-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-05", "state": "DIRECT", "basis": "Three means"}, {"question": "Q-D3-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-06a", "state": "DIRECT", "basis": "The informal employer offer is the thing outside the participant''s control"}, {"question": "Q-D3-06b", "state": "DIRECT", "basis": "The informal employer offer is the thing outside the participant''s control"}, {"question": "Q-D3-07", "state": "DIRECT", "basis": "The delivery-state table states which components are reduced or deferred"}, {"question": "Q-D3-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-08", "state": "NOT SERVED", "basis": "Stage 3 launch design"}, {"question": "Q-D3-09", "state": "NOT SERVED", "basis": "Stage 3 launch design"}], "material_map": [{"Item": "WI1", "Item text": "the employment pathways decision due Friday", "Where the participant meets it": "Pack document D1", "Quoted text": "employment pathways manager must either cancel the spring workshop series serving sixty clients or reduce staff from four to two and a"}, {"Item": "WI2", "Item text": "the youth integration supervisor position", "Where the participant meets it": "Pack document D1", "Quoted text": "youth integration coordinator reports that the afterschool mentoring program serving thirty-five young people loses its paid supervisor, and without a supervisor"}, {"Item": "WI3", "Item text": "the reserve fund justification", "Where the participant meets it": "Pack document D1", "Quoted text": "reserve fund holds about forty thousand dollars, board-earmarked for emergencies and requiring written justification"}, {"Item": "WI4", "Item text": "the delivery-state table", "Where the participant meets it": "Submission instructions", "Quoted text": "table showing which program"}, {"Item": "SR1", "Item text": "a decision reaches the employment pathways manager by Friday", "Where the participant meets it": "Pack document D1", "Quoted text": "employment pathways manager must either cancel the spring workshop series serving sixty clients or reduce staff from four to two and a"}, {"Item": "SR2", "Item text": "the workshop series completion rate is reported under the municipal agreement", "Where the participant meets it": "Pack document D1", "Quoted text": "workshop series has a seventy-eight per cent completion rate and is a reporting metric under the municipal funding agreement"}, {"Item": "SR3", "Item text": "any reserve draw carries written justification and board approval", "Where the participant meets it": "Pack document D1", "Quoted text": "reserve fund holds about forty thousand dollars, board-earmarked for emergencies and requiring written justification"}], "source_sheet": {"d3_situation_class": "SC-D3-3", "workplace_demand": "Allocating a reduced resource across commitments that were sized for the original one.", "relevant_conduct": "The order stated; what was cut, preserved or restructured; what was stated as held; which verifications were named; which means were used; what was done about the unconfirmed employer offer; what the delivery-state table identified as reduced or deferred.", "irrelevant_conduct": "Whether the allocation is right; the funder''s decision; the merits of either program.", "stated_standard": "\"a decision by Friday\"; the workshop series \"is a reporting metric under the municipal funding agreement\"; the reserve \"requires board approval with written justification.\" Exact brief text.", "stated_standard_source_quote_or_location": "\"a decision by Friday\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Extended time and assistive software permitted and recorded.", "unsupported_inferences": "That any allocation is correct; that preserving one program indicates values; anything about compassion.", "compatibility_class": "S3-ASYNC-SUBMISSION", "work_items": [{"id": "WI1", "text": "the employment pathways decision due Friday"}, {"id": "WI2", "text": "the youth integration supervisor position"}, {"id": "WI3", "text": "the reserve fund justification"}, {"id": "WI4", "text": "the delivery-state table"}], "deliverable_components": [{"id": "DC1", "text": "the spring workshop series"}, {"id": "DC2", "text": "the employment pathways staffing"}, {"id": "DC3", "text": "the afterschool mentoring supervisor"}, {"id": "DC4", "text": "the employer-partner placement stream"}], "stated_requirements": [{"id": "SR1", "text": "a decision reaches the employment pathways manager by Friday"}, {"id": "SR2", "text": "the workshop series completion rate is reported under the municipal agreement"}, {"id": "SR3", "text": "any reserve draw carries written justification and board approval"}], "available_checks": [{"id": "CK1", "text": "confirm the municipal reporting obligation before cutting the workshop series"}, {"id": "CK2", "text": "confirm the employer offer is not relied upon in the plan while it is informal"}], "available_means": [{"id": "MN1", "text": "draw on the reserve with a written justification"}, {"id": "MN2", "text": "restructure staffing rather than cancelling a program"}, {"id": "MN3", "text": "phase the reduction across two quarters"}], "time_available": "To Friday for the decision, to next quarter for the reduction.", "work_required": "A reduced budget across two programs with a fixed reporting obligation.", "blocking_dependency": "The employer-partner offer is informal and cannot be built on.", "dependency_holder_role": "An employer partner. RETAINED AND NEVER RENDERED.", "handover_point": "The Friday decision and the quarter start.", "list_note": null, "source_note": "Shared with SRC-D2-S3-008. One submission may carry both records.", "situation_class_label": "The deadline or scope moves after work has begun", "observation_mode_label": "work_sample", "ai_use": "AI_USE_DECLARATION_REQUIRED", "submission_window_days": 3}, "source_identifier": "SRC-D3-S3-007", "stage_code": "S3", "source_version_hash": "1325275c895a784f2057ecae6c87c00918d6071ad1c23e947e15c1e3a6f159c8", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D3-S3-007' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D3-S3-009', 'source'::public.t3a_content_family, 'SOMETHING VISUAL BY TUESDAY', 'D3', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.0', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 3, "title": "SOMETHING VISUAL BY TUESDAY", "source_digest": "b447eb48716ffb1e8c0d10dc73e5867cfc94ab1d4dacfb12c6d410a3066fbafa", "brief_summary": "The participant reads the brief in the pack and submits the work the submission instructions name.", "participant_pack": [{"document": "D1", "title": "The brief", "text": "You are a client services coordinator supporting a workplace transformation practice, eight months into the role. Your firm is midway through an engagement with a municipal housing authority redesigning their tenant complaint resolution process; the project is in Phase 2, design and pilot. At 4:45 PM Friday the client sponsor emails: a deputy minister is visiting their office next Wednesday, they need something from your firm showing what has been worked on, can you have it ready by Tuesday, something visual and clear. No further specification. Your practice lead replies that she is in a workshop all day Monday, to use your judgment, and not to over-promise. The engagement terms state that no client-facing material leaves the firm without practice lead review, and that Phase 2 pilot findings are not represented as conclusions."}], "submission_instructions": "Produce a note stating how you interpreted the request and what you will produce; the outline of the material with what it will and will not show; and a register of what you assumed and what you would confirm. The work is submitted within 3 days.", "question_applicability": [{"question": "Q-D3-01", "state": "DIRECT", "basis": "Four work items across a weekend"}, {"question": "Q-D3-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-02", "state": "DIRECT", "basis": "The brief asks what the material will not show"}, {"question": "Q-D3-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-03", "state": "DIRECT", "basis": "Three stated requirements, one of which the schedule threatens"}, {"question": "Q-D3-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-04", "state": "DIRECT", "basis": "Two checks, one of them the not-as-conclusions read"}, {"question": "Q-D3-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-05", "state": "DIRECT", "basis": "Three means"}, {"question": "Q-D3-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-06a", "state": "DIRECT", "basis": "The mandatory review with an unavailable reviewer is the blocking dependency"}, {"question": "Q-D3-06b", "state": "DIRECT", "basis": "The mandatory review with an unavailable reviewer is the blocking dependency"}, {"question": "Q-D3-07", "state": "DIRECT", "basis": "The outline states what the material will and will not show"}, {"question": "Q-D3-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-08", "state": "NOT SERVED", "basis": "Stage 3 launch design"}, {"question": "Q-D3-09", "state": "NOT SERVED", "basis": "Stage 3 launch design"}], "material_map": [{"Item": "WI1", "Item text": "interpret the request", "Where the participant meets it": "Submission instructions", "Quoted text": "interpreted the request and"}, {"Item": "WI2", "Item text": "select what Phase 2 material can be shown", "Where the participant meets it": "Pack document D1", "Quoted text": "material leaves the firm without practice lead review, and that Phase"}, {"Item": "WI3", "Item text": "build the visual material", "Where the participant meets it": "Pack document D1", "Quoted text": "something visual and clear"}, {"Item": "WI4", "Item text": "secure the practice lead review", "Where the participant meets it": "Pack document D1", "Quoted text": "practice lead review, and"}, {"Item": "SR1", "Item text": "no client-facing material leaves without practice lead review", "Where the participant meets it": "Pack document D1", "Quoted text": "material leaves the firm without practice lead review"}, {"Item": "SR2", "Item text": "pilot findings are not represented as conclusions", "Where the participant meets it": "Pack document D1", "Quoted text": "pilot findings are not represented as conclusions"}, {"Item": "SR3", "Item text": "the material is ready by Tuesday", "Where the participant meets it": "Pack document D1", "Quoted text": "ready by Tuesday, something"}], "source_sheet": {"d3_situation_class": "SC-D3-6", "workplace_demand": "Producing a client-facing artifact from a request that specifies only a date and a feeling.", "relevant_conduct": "The order stated; what was included and what left out; what was stated as held; which verifications were named; which means were used; what was done about the unavailable review; what the material identified as not yet concluded.", "irrelevant_conduct": "Whether the interpretation is right; the sponsor''s vagueness; the practice lead''s availability.", "stated_standard": "\"no client-facing material leaves the firm without practice lead review\" and \"Phase 2 pilot findings are not represented as conclusions.\" Exact brief text.", "stated_standard_source_quote_or_location": "\"no client-facing material leaves the firm without practice lead review\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Extended time and assistive software permitted and recorded.", "unsupported_inferences": "That asking for specification was required; that producing something was over-promising; anything about judgment as a trait.", "compatibility_class": "S3-ASYNC-SUBMISSION", "work_items": [{"id": "WI1", "text": "interpret the request"}, {"id": "WI2", "text": "select what Phase 2 material can be shown"}, {"id": "WI3", "text": "build the visual material"}, {"id": "WI4", "text": "secure the practice lead review"}], "deliverable_components": [{"id": "DC1", "text": "the interpretation note"}, {"id": "DC2", "text": "the visual material"}, {"id": "DC3", "text": "the assumption register"}], "stated_requirements": [{"id": "SR1", "text": "no client-facing material leaves without practice lead review"}, {"id": "SR2", "text": "pilot findings are not represented as conclusions"}, {"id": "SR3", "text": "the material is ready by Tuesday"}], "available_checks": [{"id": "CK1", "text": "read the material against the not-as-conclusions rule before it leaves"}, {"id": "CK2", "text": "confirm the practice lead review can happen before Tuesday"}], "available_means": [{"id": "MN1", "text": "produce material that shows process rather than findings"}, {"id": "MN2", "text": "ask the sponsor what the deputy minister needs to see"}, {"id": "MN3", "text": "book the practice lead review for Monday evening or Tuesday morning"}], "time_available": "Friday evening to Tuesday, with Monday review unavailable.", "work_required": "An unspecified client-facing artifact plus a mandatory review.", "blocking_dependency": "The practice lead is unavailable all Monday and review is mandatory.", "dependency_holder_role": "The practice lead. RETAINED AND NEVER RENDERED.", "handover_point": "Tuesday, when the material goes to the sponsor.", "list_note": null, "source_note": null, "situation_class_label": "Work that arrives without a specification sufficient to complete it", "observation_mode_label": "work_sample", "ai_use": "AI_USE_DECLARATION_REQUIRED", "submission_window_days": 3}, "source_identifier": "SRC-D3-S3-009", "stage_code": "S3", "source_version_hash": "b447eb48716ffb1e8c0d10dc73e5867cfc94ab1d4dacfb12c6d410a3066fbafa", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D3-S3-009' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D3-S3-010', 'source'::public.t3a_content_family, 'THE VENUE CLOSED FOR FOUR WEEKS', 'D3', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.0', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 3, "title": "THE VENUE CLOSED FOR FOUR WEEKS", "source_digest": "53ac84e631ca83a62c7267c3dd352cdaac614862c1e4bd521ab9e848da8aa730", "brief_summary": "The participant reads the brief in the pack and submits the work the submission instructions name.", "participant_pack": [{"document": "D1", "title": "The brief", "text": "You are an event coordinator at a boutique events firm. Your firm is running a half-day leadership summit for eighty senior executives of a financial services client, three weeks from today. The summit has keynote speakers, two breakout sessions, a networking lunch and a closing panel. Planning has run five weeks and is on track. On Monday morning the venue reports that a water main break has damaged the main conference hall and the venue will be closed for at least four weeks. They waive the cancellation fee and offer help finding an alternative, but have no comparable space. Your contract with the client states that the date is fixed because it is tied to the client''s board calendar, and that the format — four elements, eighty attendees — is what was sold."}], "submission_instructions": "Produce a recovery plan stating what happens to each of the four elements; a venue and logistics schedule for the three weeks with decision points; and a statement of what the summit will look like if no comparable venue is found. The work is submitted within 3 days.", "question_applicability": [{"question": "Q-D3-01", "state": "DIRECT", "basis": "Four work items in three weeks"}, {"question": "Q-D3-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-02", "state": "DIRECT", "basis": "The brief asks what happens to each element"}, {"question": "Q-D3-02b", "state": "CONDITIONAL", "basis": "FOUR components, all named"}, {"question": "Q-D3-03", "state": "DIRECT", "basis": "Three stated requirements that may not all hold"}, {"question": "Q-D3-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-04", "state": "DIRECT", "basis": "The brief asks for decision points"}, {"question": "Q-D3-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-05", "state": "DIRECT", "basis": "Three means"}, {"question": "Q-D3-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-06a", "state": "DIRECT", "basis": "The venue closure is the blocking dependency"}, {"question": "Q-D3-06b", "state": "DIRECT", "basis": "The venue closure is the blocking dependency"}, {"question": "Q-D3-07", "state": "DIRECT", "basis": "The brief asks what the summit looks like if no venue is found"}, {"question": "Q-D3-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-08", "state": "NOT SERVED", "basis": "Stage 3 launch design"}, {"question": "Q-D3-09", "state": "NOT SERVED", "basis": "Stage 3 launch design"}], "material_map": [{"Item": "WI1", "Item text": "find an alternative venue", "Where the participant meets it": "Pack document D1", "Quoted text": "finding an alternative, but"}, {"Item": "WI2", "Item text": "re-confirm the speakers and panel", "Where the participant meets it": "Pack document D1", "Quoted text": "speakers, two breakout sessions, a networking lunch and a closing panel"}, {"Item": "WI3", "Item text": "re-arrange catering and logistics", "Where the participant meets it": "Submission instructions", "Quoted text": "logistics schedule for the"}, {"Item": "WI4", "Item text": "re-issue attendee information", "Where the participant meets it": "Pack document D1", "Quoted text": "four elements, eighty attendees"}, {"Item": "SR1", "Item text": "the date does not move", "Where the participant meets it": "Pack document D1", "Quoted text": "date is fixed because"}, {"Item": "SR2", "Item text": "the four-element format is delivered", "Where the participant meets it": "Pack document D1", "Quoted text": "format — four elements"}, {"Item": "SR3", "Item text": "eighty attendees are accommodated", "Where the participant meets it": "Pack document D1", "Quoted text": "eighty attendees — is"}], "source_sheet": {"d3_situation_class": "SC-D3-1", "workplace_demand": "Holding a fixed date and format when the place it depends on has gone.", "relevant_conduct": "The order across the three weeks; which of the four elements were reduced, deferred or dropped; what was stated as held; which verifications were named; which means were used; what was done about the venue; what the plan stated the summit would be without a comparable venue.", "irrelevant_conduct": "Whether the recovery is achievable; the venue''s failure; the client''s board calendar.", "stated_standard": "\"the date is fixed because it is tied to the client''s board calendar\" and \"the format — four elements, eighty attendees — is what was sold.\" Exact brief text.", "stated_standard_source_quote_or_location": "\"the date is fixed because it is tied to the client''s board calendar\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Extended time and assistive software permitted and recorded.", "unsupported_inferences": "That the summit should be postponed; that any element should be cut first; anything about resourcefulness.", "compatibility_class": "S3-ASYNC-SUBMISSION", "work_items": [{"id": "WI1", "text": "find an alternative venue"}, {"id": "WI2", "text": "re-confirm the speakers and panel"}, {"id": "WI3", "text": "re-arrange catering and logistics"}, {"id": "WI4", "text": "re-issue attendee information"}], "deliverable_components": [{"id": "DC1", "text": "the keynote sessions"}, {"id": "DC2", "text": "the two breakout sessions"}, {"id": "DC3", "text": "the networking lunch"}, {"id": "DC4", "text": "the closing panel"}], "stated_requirements": [{"id": "SR1", "text": "the date does not move"}, {"id": "SR2", "text": "the four-element format is delivered"}, {"id": "SR3", "text": "eighty attendees are accommodated"}], "available_checks": [{"id": "CK1", "text": "confirm an alternative venue holds eighty and supports breakouts before committing"}, {"id": "CK2", "text": "re-confirm every speaker against the new venue and timings"}], "available_means": [{"id": "MN1", "text": "split the summit across two smaller spaces"}, {"id": "MN2", "text": "reduce the format to three elements and state which is dropped"}, {"id": "MN3", "text": "use the venue''s assistance to reach spaces not publicly available"}], "time_available": "Three weeks.", "work_required": "A full relocation of a five-week plan.", "blocking_dependency": "No comparable space is available and the venue is closed for at least four weeks.", "dependency_holder_role": "The venue. RETAINED AND NEVER RENDERED.", "handover_point": "The summit date.", "list_note": null, "source_note": null, "situation_class_label": "More work than the available time allows, with the gap stated in the situation", "observation_mode_label": "work_sample", "ai_use": "AI_USE_DECLARATION_REQUIRED", "submission_window_days": 3}, "source_identifier": "SRC-D3-S3-010", "stage_code": "S3", "source_version_hash": "53ac84e631ca83a62c7267c3dd352cdaac614862c1e4bd521ab9e848da8aa730", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D3-S3-010' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D3-S4-001', 'source'::public.t3a_content_family, 'THREE ANALYSTS, THREE PROJECTS', 'D3', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.0', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 4, "title": "THREE ANALYSTS, THREE PROJECTS", "source_digest": "278eb79400220d23c8fd65c8400d0bd4f351180a540ac2e9ce70d6fb51929633", "mentor_brief": "The facilitator facilitates the session and observes the observed participant only. At B1 the facilitator states the speaking order aloud: the three co-participants, then the observed participant. During the B2 round the facilitator does not look at, gesture towards or address the observed participant. The facilitator reads the scripted text verbatim, reacts to nothing, and does not press, repeat or escalate, whatever the observed participant says or does not say. The co-participants are role players; nothing they say is recorded.", "participant_pre_brief": "You lead a client engagement. Three senior analysts support all the firm''s engagements. This week your engagement and two others have all hit critical phases. Each needs two analysts full time for two weeks and there are three analysts. Your engagement has four remaining pieces — the data build, the model, the client review pack and the handover — of about a week each, and two weeks left. The engagement terms state that the client review happens on the agreed date and that no deliverable goes to the client without a second-analyst check.", "script": [{"beat": "B1", "type": "SAY", "spoken": "Thank you all. I will hear each of you in turn, in the order on your cards, and then I will turn to the last of you. Two minutes each.", "direction": null, "capture": []}, {"beat": "B2", "type": "ROUND", "spoken": "Over to you, in the order I gave.", "direction": "Invite the three co-participants in the stated order. Do not address the observed participant.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, {"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C3", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4", "state": "open"}, {"set": "C4b", "state": "open"}, {"set": "C5", "state": "open"}, {"set": "C5b", "state": "open"}, {"set": "C6a", "state": "open"}, {"set": "C6b", "state": "open"}, {"set": "C7", "state": "open"}, {"set": "C7b", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "Where does your engagement stand on two analysts or fewer?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C1b", "state": "update"}, {"set": "C6a", "state": "update"}, {"set": "C6b", "state": "update"}]}, {"beat": "B4", "type": "ASK", "spoken": "If you get one analyst, what still gets delivered and what does not?", "direction": "Read once, verbatim.", "capture": [{"set": "C2", "state": "update"}, {"set": "C2b", "state": "update"}, {"set": "C3", "state": "update"}, {"set": "C3b", "state": "update"}, {"set": "C7", "state": "update"}, {"set": "C7b", "state": "update"}]}, {"beat": "B5", "type": "ASK", "spoken": "What gets checked before anything goes to your client, and how?", "direction": "Read once, verbatim.", "capture": [{"set": "C4", "state": "update"}, {"set": "C4b", "state": "update"}, {"set": "C5", "state": "update"}, {"set": "C5b", "state": "update"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so the position is right — which of your four pieces is complete and which is not?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "That is the session. Thank you all.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3", "state": "final"}, {"set": "C4", "state": "final"}, {"set": "C5", "state": "final"}, {"set": "C6a", "state": "final"}, {"set": "C6b", "state": "final"}, {"set": "C7", "state": "final"}, {"set": "C9", "state": "final"}]}], "co_participant_positions": [{"Co-participant": "CP-1", "Position stated at the round": "Your engagement has a regulatory deadline; state it and do not depart from it."}, {"Co-participant": "CP-2", "Position stated at the round": "Your engagement is for the firm''s largest client; state it."}, {"Co-participant": "CP-3", "Position stated at the round": "You are the operations director; state that if no allocation is agreed in this meeting you will impose one."}], "impact_assessment": [{"Part": "1. Shared material", "Finding": "Only the scripted situation is placed before the group, and it names no real organization", "Controls": "IA-01 shown in one shared window holding only the shared material"}, {"Part": "2. Identity", "Finding": "The observed participant is the authenticated participant; the three co-participants are role players", "Controls": "IA-02 platform account authentication; role players are never observed"}, {"Part": "3. Recording", "Finding": "Nothing is recorded", "Controls": "IA-03 no media persists"}, {"Part": "4. Correction", "Finding": "A correction reaches only the observed participant''s record", "Controls": "IA-04 a correction reaches only the observed participant''s record"}, {"Part": "5. Withdrawal", "Finding": "Withdrawal removes the participant''s determinations from composition only", "Controls": "IA-05 withdrawal excludes from composition; history retained"}, {"Part": "6. Group composition", "Finding": "One observed participant, three role players and one facilitator", "Controls": "IA-06 composition record and confidentiality undertaking from each role player"}, {"Part": "7. Accommodation", "Finding": "An accommodation is settled before composition and never changes the observation during the session", "Controls": "IA-07 settled before composition"}], "impact_result": "Completed", "question_applicability": [{"question": "Q-D3-01", "state": "DIRECT", "basis": "Four pieces, reduced capacity"}, {"question": "Q-D3-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-02", "state": "DIRECT", "basis": "B4 asks what still gets delivered"}, {"question": "Q-D3-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-03", "state": "DIRECT", "basis": "Two stated requirements"}, {"question": "Q-D3-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-04", "state": "DIRECT", "basis": "B5 asks what is checked and how"}, {"question": "Q-D3-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-05", "state": "DIRECT", "basis": "Three means, all performable in the round"}, {"question": "Q-D3-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-06a", "state": "DIRECT", "basis": "The fixed shared pool is the binding constraint"}, {"question": "Q-D3-06b", "state": "DIRECT", "basis": "The fixed shared pool is the binding constraint"}, {"question": "Q-D3-07", "state": "DIRECT", "basis": "B4 creates the opportunity"}, {"question": "Q-D3-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-08", "state": "NOT SERVED", "basis": "The situation presents no change to the requirement"}, {"question": "Q-D3-09", "state": "DIRECT", "basis": "Test point at B6"}], "material_map": [{"Item": "WI1", "Item text": "data build", "Where the participant meets it": "The pre-brief", "Quoted text": "data build, the model"}, {"Item": "WI2", "Item text": "model", "Where the participant meets it": "The pre-brief", "Quoted text": "model, the client review"}, {"Item": "WI3", "Item text": "client review pack", "Where the participant meets it": "The pre-brief", "Quoted text": "client review pack and"}, {"Item": "WI4", "Item text": "handover", "Where the participant meets it": "The pre-brief", "Quoted text": "handover — of about"}, {"Item": "SR1", "Item text": "the client review happens on the agreed date", "Where the participant meets it": "The pre-brief", "Quoted text": "client review happens on the agreed date and that no deliverable goes to the client"}, {"Item": "SR2", "Item text": "no deliverable goes to the client without a second-analyst check", "Where the participant meets it": "The pre-brief", "Quoted text": "client review happens on the agreed date and that no deliverable goes to the client without a second-analyst check"}], "source_sheet": {"d3_situation_class": "SC-D3-1", "workplace_demand": "Ordering four pieces of work against a shared analyst pool that cannot cover every engagement.", "relevant_conduct": "The order stated; what was reduced, deferred or dropped; what was stated as held; which checks were named or performed; which means were named or used; what was done about the item outside the participant''s control; what happened to the work while it remained; what was identified as incomplete at handover; the answer when the delivery state was put to the participant.", "irrelevant_conduct": "The co-participants'' claims, which are scripted and never recorded; whether the allocation is fair.", "stated_standard": "The client review happens on the agreed date; no deliverable goes to the client without a second-analyst check.", "stated_standard_source_quote_or_location": "\"client review happens on the agreed date and that no deliverable goes to the client\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "That competing for analysts is self-interest; that conceding is maturity; ANY COMPARISON OF WHAT P-OBS SAID EARLY WITH WHAT THEY DID LATER TO INFER SINCERITY.", "compatibility_class": "S4-GROUP-ROUND", "work_items": [{"id": "WI1", "text": "data build"}, {"id": "WI2", "text": "model"}, {"id": "WI3", "text": "client review pack"}, {"id": "WI4", "text": "handover"}], "deliverable_components": [{"id": "DC1", "text": "data build"}, {"id": "DC2", "text": "model"}, {"id": "DC3", "text": "client review pack"}, {"id": "DC4", "text": "handover"}], "stated_requirements": [{"id": "SR1", "text": "the client review happens on the agreed date"}, {"id": "SR2", "text": "no deliverable goes to the client without a second-analyst check"}], "available_checks": [{"id": "CK1", "text": "the second-analyst check"}, {"id": "CK2", "text": "a data reconciliation before the model runs"}], "available_means": [{"id": "MN1", "text": "propose objective allocation criteria in the round"}, {"id": "MN2", "text": "offer to take one analyst and extend a piece"}, {"id": "MN3", "text": "ask the operations director to impose the allocation"}], "time_available": "Two weeks.", "work_required": "Four pieces of about a week each.", "blocking_dependency": "The analyst pool is fixed at three and shared.", "dependency_holder_role": "The operations director.", "moved_standard_point": null, "handover_point": "The client review date, stated at B4.", "delivery_state_record": "At B6: four pieces, two weeks, allocation unresolved at the start of the session.", "delivery_test_point": "B6", "list_note": null, "source_note": null, "situation_class_label": "More work than the available time allows, with the gap stated in the situation", "observation_mode_label": "group_session", "min_seconds": 900, "max_seconds": 1500}, "source_identifier": "SRC-D3-S4-001", "stage_code": "S4", "source_version_hash": "278eb79400220d23c8fd65c8400d0bd4f351180a540ac2e9ce70d6fb51929633", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D3-S4-001' and family = 'source'::public.t