  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D3-S4-002', 'source'::public.t3a_content_family, 'THREE DISRUPTIONS BEFORE HALF PAST NINE', 'D3', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.0', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 4, "title": "THREE DISRUPTIONS BEFORE HALF PAST NINE", "source_digest": "1a7cd30d3c03e81abc05f96ae21b4f1cedb4984776835260f66fb446a0b48d05", "mentor_brief": "The facilitator facilitates the session and observes the observed participant only. At B1 the facilitator states the speaking order aloud: the three co-participants, then the observed participant. During the B2 round the facilitator does not look at, gesture towards or address the observed participant. The facilitator reads the scripted text verbatim, reacts to nothing, and does not press, repeat or escalate, whatever the observed participant says or does not say. The co-participants are role players; nothing they say is recorded.", "participant_pre_brief": "You are on the operations team of a logistics company. It is 9:15 AM. A refrigeration failure at the primary warehouse puts temperature-sensitive stock at risk unless cooling is restored within four hours. A shipment for the largest client is held at a port on a documentation error and their line stops if it does not arrive Thursday. The fleet management system is offline, so dispatchers cannot see truck locations or schedules; manual workarounds exist but are slow. The operations director is on a flight for three hours. The operating standard states that a temperature excursion is logged and escalated within one hour of detection, and that no dispatch is made without a confirmed route record.", "script": [{"beat": "B1", "type": "SAY", "spoken": "Thank you all. I will hear each of you in turn, in the order on your cards, and then I will turn to the last of you. Two minutes each.", "direction": null, "capture": []}, {"beat": "B2", "type": "ROUND", "spoken": "Over to you, in the order I gave.", "direction": "Invite the three co-participants in the stated order. Do not address the observed participant.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, {"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C3", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4", "state": "open"}, {"set": "C4b", "state": "open"}, {"set": "C5", "state": "open"}, {"set": "C5b", "state": "open"}, {"set": "C6a", "state": "open"}, {"set": "C6b", "state": "open"}, {"set": "C7", "state": "open"}, {"set": "C7b", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "What order are we taking these in?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C1b", "state": "update"}, {"set": "C6a", "state": "update"}, {"set": "C6b", "state": "update"}]}, {"beat": "B4", "type": "ASK", "spoken": "Three things and one team. What gets handled today and what does not?", "direction": "Read once, verbatim.", "capture": [{"set": "C2", "state": "update"}, {"set": "C2b", "state": "update"}, {"set": "C3", "state": "update"}, {"set": "C3b", "state": "update"}, {"set": "C7", "state": "update"}, {"set": "C7b", "state": "update"}]}, {"beat": "B5", "type": "ASK", "spoken": "What gets confirmed before anything dispatches?", "direction": "Read once, verbatim.", "capture": [{"set": "C4", "state": "update"}, {"set": "C4b", "state": "update"}, {"set": "C5", "state": "update"}, {"set": "C5b", "state": "update"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so the position is right — as of now, which of the three is contained and which is not?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "That is the session. Thank you all.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3", "state": "final"}, {"set": "C4", "state": "final"}, {"set": "C5", "state": "final"}, {"set": "C6a", "state": "final"}, {"set": "C6b", "state": "final"}, {"set": "C7", "state": "final"}, {"set": "C9", "state": "final"}]}], "co_participant_positions": [{"Co-participant": "CP-1", "Position stated at the round": "You hold the warehouse; state the four-hour window and nothing more."}, {"Co-participant": "CP-2", "Position stated at the round": "You hold client relations; state that the client''s vice-president has called directly."}, {"Co-participant": "CP-3", "Position stated at the round": "You hold dispatch; state that manual working halves throughput."}], "impact_assessment": [{"Part": "1. Shared material", "Finding": "Only the scripted situation is placed before the group, and it names no real organization", "Controls": "IA-01 shown in one shared window holding only the shared material"}, {"Part": "2. Identity", "Finding": "The observed participant is the authenticated participant; the three co-participants are role players", "Controls": "IA-02 platform account authentication; role players are never observed"}, {"Part": "3. Recording", "Finding": "Nothing is recorded", "Controls": "IA-03 no media persists"}, {"Part": "4. Correction", "Finding": "A correction reaches only the observed participant''s record", "Controls": "IA-04 a correction reaches only the observed participant''s record"}, {"Part": "5. Withdrawal", "Finding": "Withdrawal removes the participant''s determinations from composition only", "Controls": "IA-05 withdrawal excludes from composition; history retained"}, {"Part": "6. Group composition", "Finding": "One observed participant, three role players and one facilitator", "Controls": "IA-06 composition record and confidentiality undertaking from each role player"}, {"Part": "7. Accommodation", "Finding": "An accommodation is settled before composition and never changes the observation during the session", "Controls": "IA-07 settled before composition"}], "impact_result": "Completed", "question_applicability": [{"question": "Q-D3-01", "state": "DIRECT", "basis": "Three disruptions; B3 asks the order"}, {"question": "Q-D3-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-02", "state": "DIRECT", "basis": "B4 asks what gets handled"}, {"question": "Q-D3-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-03", "state": "DIRECT", "basis": "Two stated requirements under a fixed clock"}, {"question": "Q-D3-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-04", "state": "DIRECT", "basis": "B5 asks what is confirmed before dispatch"}, {"question": "Q-D3-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-05", "state": "DIRECT", "basis": "Three means"}, {"question": "Q-D3-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-06a", "state": "DIRECT", "basis": "The offline system is the blocking dependency"}, {"question": "Q-D3-06b", "state": "DIRECT", "basis": "The offline system is the blocking dependency"}, {"question": "Q-D3-07", "state": "DIRECT", "basis": "B4 and B6 create the opportunity"}, {"question": "Q-D3-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-08", "state": "NOT SERVED", "basis": "The situation presents no change to the requirement"}, {"question": "Q-D3-09", "state": "DIRECT", "basis": "Test point at B6"}], "material_map": [{"Item": "WI1", "Item text": "refrigeration", "Where the participant meets it": "The pre-brief", "Quoted text": "refrigeration failure at the"}, {"Item": "WI2", "Item text": "the held shipment", "Where the participant meets it": "The pre-brief", "Quoted text": "shipment for the largest client is held"}, {"Item": "WI3", "Item text": "the fleet system workaround", "Where the participant meets it": "The pre-brief", "Quoted text": "fleet management system is offline, so dispatchers cannot see truck locations or schedules; manual workarounds"}, {"Item": "SR1", "Item text": "a temperature excursion is logged and escalated within one hour", "Where the participant meets it": "The pre-brief", "Quoted text": "temperature excursion is logged and escalated within one hour"}, {"Item": "SR2", "Item text": "no dispatch without a confirmed route record", "Where the participant meets it": "The pre-brief", "Quoted text": "dispatch is made without a confirmed route record"}], "source_sheet": {"d3_situation_class": "SC-D3-2", "workplace_demand": "Ordering three operational disruptions while the system the work depends on is offline.", "relevant_conduct": "The order stated; what was reduced, deferred or dropped; what was stated as held; which checks were named or performed; which means were named or used; what was done about the item outside the participant''s control; what happened to the work while it remained; what was identified as incomplete at handover; the answer when the delivery state was put to the participant.", "irrelevant_conduct": "The co-participants'' statements; the cause of any failure.", "stated_standard": "SR-01 and SR-02, exact pre-brief text.", "stated_standard_source_quote_or_location": "\"temperature excursion is logged and escalated within one hour\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "That the angry client should or should not outrank the stock; that emotional urgency displaced analysis; anything about composure.", "compatibility_class": "S4-GROUP-ROUND", "work_items": [{"id": "WI1", "text": "refrigeration"}, {"id": "WI2", "text": "the held shipment"}, {"id": "WI3", "text": "the fleet system workaround"}], "deliverable_components": [{"id": "DC1", "text": "the stock at risk"}, {"id": "DC2", "text": "the Thursday delivery"}, {"id": "DC3", "text": "the day''s dispatch schedule"}], "stated_requirements": [{"id": "SR1", "text": "a temperature excursion is logged and escalated within one hour"}, {"id": "SR2", "text": "no dispatch without a confirmed route record"}], "available_checks": [{"id": "CK1", "text": "confirm the temperature log before escalation"}, {"id": "CK2", "text": "confirm a route record manually before dispatch"}], "available_means": [{"id": "MN1", "text": "move stock to a second cold store"}, {"id": "MN2", "text": "correct the port documentation"}, {"id": "MN3", "text": "run dispatch from the manual record at reduced throughput"}], "time_available": "Four hours on refrigeration, two days on the shipment.", "work_required": "Three simultaneous disruptions with one team.", "blocking_dependency": "The fleet management system is offline.", "dependency_holder_role": null, "moved_standard_point": null, "handover_point": "Each dispatch, inside the observation.", "delivery_state_record": "At B6: refrigeration unrestored, shipment held, fleet system offline.", "delivery_test_point": "B6", "list_note": null, "source_note": "dependency_holder_role: The system is the firm''s own.", "situation_class_label": "A tool or resource the work depends on is unavailable, with no restoration time given", "observation_mode_label": "group_session", "min_seconds": 900, "max_seconds": 1500}, "source_identifier": "SRC-D3-S4-002", "stage_code": "S4", "source_version_hash": "1a7cd30d3c03e81abc05f96ae21b4f1cedb4984776835260f66fb446a0b48d05", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D3-S4-002' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D3-S4-003', 'source'::public.t3a_content_family, 'SIXTEEN WEEKS INTO EIGHT', 'D3', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.0', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 4, "title": "SIXTEEN WEEKS INTO EIGHT", "source_digest": "adba296ae7db1aaea85be1f705d28cb98d1c1d82b24a55f3379eb16b9d2102ed", "mentor_brief": "The facilitator facilitates the session and observes the observed participant only. At B1 the facilitator states the speaking order aloud: the three co-participants, then the observed participant. During the B2 round the facilitator does not look at, gesture towards or address the observed participant. The facilitator reads the scripted text verbatim, reacts to nothing, and does not press, repeat or escalate, whatever the observed participant says or does not say. The co-participants are role players; nothing they say is recorded.", "participant_pre_brief": "You are on an implementation team migrating twelve years of records from a legacy system to a new platform. The plan was sixteen weeks. The current vendor terminates support in eight weeks, and your vice-president has already committed to the client that it will be done. The plan has four stages — extraction, transformation, validation and cutover — of about four weeks each. The engagement terms state that no record set is cut over without completed validation, and that the migration completes before support terminates.", "script": [{"beat": "B1", "type": "SAY", "spoken": "Thank you all. I will hear each of you in turn, in the order on your cards, and then I will turn to the last of you. Two minutes each.", "direction": null, "capture": []}, {"beat": "B2", "type": "ROUND", "spoken": "Over to you, in the order I gave.", "direction": "Invite the three co-participants in the stated order. Do not address the observed participant.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, {"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C3", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4", "state": "open"}, {"set": "C4b", "state": "open"}, {"set": "C5", "state": "open"}, {"set": "C5b", "state": "open"}, {"set": "C6a", "state": "open"}, {"set": "C6b", "state": "open"}, {"set": "C7", "state": "open"}, {"set": "C7b", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "Where does the plan stand at eight weeks?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C1b", "state": "update"}, {"set": "C6a", "state": "update"}, {"set": "C6b", "state": "update"}]}, {"beat": "B4", "type": "ASK", "spoken": "Sixteen into eight. What is compressed and what is not?", "direction": "Read once, verbatim.", "capture": [{"set": "C2", "state": "update"}, {"set": "C2b", "state": "update"}, {"set": "C3", "state": "update"}, {"set": "C3b", "state": "update"}, {"set": "C7", "state": "update"}, {"set": "C7b", "state": "update"}]}, {"beat": "B5", "type": "ASK", "spoken": "What is validated before cutover, and how?", "direction": "Read once, verbatim.", "capture": [{"set": "C4", "state": "update"}, {"set": "C4b", "state": "update"}, {"set": "C5", "state": "update"}, {"set": "C5b", "state": "update"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so the position is right — as of now, which stages are complete and which are not?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "That is the session. Thank you all.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3", "state": "final"}, {"set": "C4", "state": "final"}, {"set": "C5", "state": "final"}, {"set": "C6a", "state": "final"}, {"set": "C6b", "state": "final"}, {"set": "C7", "state": "final"}, {"set": "C9", "state": "final"}]}], "co_participant_positions": [{"Co-participant": "CP-1", "Position stated at the round": "You hold extraction; state that extraction cannot be compressed below three weeks."}, {"Co-participant": "CP-2", "Position stated at the round": "You hold validation; state that validation is the only stage that catches record loss."}, {"Co-participant": "CP-3", "Position stated at the round": "You hold the client relationship; state that the vice-president has already committed the date."}], "impact_assessment": [{"Part": "1. Shared material", "Finding": "Only the scripted situation is placed before the group, and it names no real organization", "Controls": "IA-01 shown in one shared window holding only the shared material"}, {"Part": "2. Identity", "Finding": "The observed participant is the authenticated participant; the three co-participants are role players", "Controls": "IA-02 platform account authentication; role players are never observed"}, {"Part": "3. Recording", "Finding": "Nothing is recorded", "Controls": "IA-03 no media persists"}, {"Part": "4. Correction", "Finding": "A correction reaches only the observed participant''s record", "Controls": "IA-04 a correction reaches only the observed participant''s record"}, {"Part": "5. Withdrawal", "Finding": "Withdrawal removes the participant''s determinations from composition only", "Controls": "IA-05 withdrawal excludes from composition; history retained"}, {"Part": "6. Group composition", "Finding": "One observed participant, three role players and one facilitator", "Controls": "IA-06 composition record and confidentiality undertaking from each role player"}, {"Part": "7. Accommodation", "Finding": "An accommodation is settled before composition and never changes the observation during the session", "Controls": "IA-07 settled before composition"}], "impact_result": "Completed", "question_applicability": [{"question": "Q-D3-01", "state": "DIRECT", "basis": "Four stages, half the time"}, {"question": "Q-D3-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-02", "state": "DIRECT", "basis": "B4 asks what is compressed"}, {"question": "Q-D3-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-03", "state": "DIRECT", "basis": "Two stated requirements in direct conflict"}, {"question": "Q-D3-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-04", "state": "DIRECT", "basis": "B5 asks what is validated"}, {"question": "Q-D3-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-05", "state": "DIRECT", "basis": "Three means"}, {"question": "Q-D3-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-06a", "state": "DIRECT", "basis": "The support termination date is outside the firm''s control"}, {"question": "Q-D3-06b", "state": "DIRECT", "basis": "The support termination date is outside the firm''s control"}, {"question": "Q-D3-07", "state": "DIRECT", "basis": "B4 and B6 create the opportunity"}, {"question": "Q-D3-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D3-08", "state": "NOT SERVED", "basis": "The situation presents no change to the requirement"}, {"question": "Q-D3-09", "state": "DIRECT", "basis": "Test point at B6"}], "material_map": [{"Item": "WI1", "Item text": "extraction", "Where the participant meets it": "The pre-brief", "Quoted text": "extraction, transformation, validation and"}, {"Item": "WI2", "Item text": "transformation", "Where the participant meets it": "The pre-brief", "Quoted text": "transformation, validation and cutover"}, {"Item": "WI3", "Item text": "validation", "Where the participant meets it": "The pre-brief", "Quoted text": "validation and cutover —"}, {"Item": "WI4", "Item text": "cutover", "Where the participant meets it": "The pre-brief", "Quoted text": "cutover — of about"}, {"Item": "SR1", "Item text": "no record set is cut over without completed validation", "Where the participant meets it": "The pre-brief", "Quoted text": "record set is cut over without completed validation, and that the migration completes"}, {"Item": "SR2", "Item text": "the migration completes before support terminates", "Where the participant meets it": "The pre-brief", "Quoted text": "completed validation, and that the migration completes before support terminates"}], "source_sheet": {"d3_situation_class": "SC-D3-4", "workplace_demand": "Replanning a sixteen week migration to fit an eight week window the firm does not control.", "relevant_conduct": "The order stated; what was reduced, deferred or dropped; what was stated as held; which checks were named or performed; which means were named or used; what was done about the item outside the participant''s control; what happened to the work while it remained; what was identified as incomplete at handover; the answer when the delivery state was put to the participant.", "irrelevant_conduct": "The vice-president''s commitment; the co-participants'' positions.", "stated_standard": "SR-01 and SR-02.", "stated_standard_source_quote_or_location": "\"record set is cut over without completed validation, and that the migration completes\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "That agreeing to the timeline is reckless; that pushing back is courage; ANY INFERENCE FROM WHETHER P-OBS''S POSITION CHANGED DURING THE SESSION.", "compatibility_class": "S4-GROUP-ROUND", "work_items": [{"id": "WI1", "text": "extraction"}, {"id": "WI2", "text": "transformation"}, {"id": "WI3", "text": "validation"}, {"id": "WI4", "text": "cutover"}], "deliverable_components": [{"id": "DC1", "text": "extraction"}, {"id": "DC2", "text": "transformation"}, {"id": "DC3", "text": "validation"}, {"id": "DC4", "text": "cutover"}], "stated_requirements": [{"id": "SR1", "text": "no record set is cut over without completed validation"}, {"id": "SR2", "text": "the migration completes before support terminates"}], "available_checks": [{"id": "CK1", "text": "per-record-set validation"}, {"id": "CK2", "text": "a sample integrity check before full cutover"}], "available_means": [{"id": "MN1", "text": "run extraction and transformation in parallel"}, {"id": "MN2", "text": "cut over in waves rather than at once"}, {"id": "MN3", "text": "ask the vice-president for a support extension"}], "time_available": "Eight weeks.", "work_required": "Four stages of about four weeks each.", "blocking_dependency": "Vendor support terminates on a date the firm does not control.", "dependency_holder_role": "The legacy vendor.", "moved_standard_point": null, "handover_point": "Cutover.", "delivery_state_record": "At B6: a sixteen-week plan, eight weeks available, no stage complete.", "delivery_test_point": "B6", "list_note": null, "source_note": "moved_standard_point: Within the observation.", "situation_class_label": "A deliverable that can be completed only in part by the time it is due", "observation_mode_label": "group_session", "min_seconds": 900, "max_seconds": 1500}, "source_identifier": "SRC-D3-S4-003", "stage_code": "S4", "source_version_hash": "adba296ae7db1aaea85be1f705d28cb98d1c1d82b24a55f3379eb16b9d2102ed", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D3-S4-003' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D3-S4-004', 'source'::public.t3a_content_family, 'FIVE FUNCTIONAL FAULTS BEFORE MONDAY', 'D3', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.0', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 4, "title": "FIVE FUNCTIONAL FAULTS BEFORE MONDAY", "source_digest": "50294e46ef187b92bef05d24ab55f2ead7f3e25f693ae0e65247b0ea758da70a", "mentor_brief": "The facilitator facilitates the session and observes the observed participant only. At B1 the facilitator states the speaking order aloud: the three co-participants, then the observed participant. During the B2 round the facilitator does not look at, gesture towards or address the observed participant. The facilitator reads the scripted text verbatim, reacts to nothing, and does not press, repeat or escalate, whatever the observed participant says or does not say. The co-participants are role players; nothing they say is recorded.", "participant_pre_brief": "You are on a product team. Version 3.0 launches Monday. Testing finished yesterday and found fourteen faults: nine cosmetic, five functional. The five affect inventory count accuracy under high concurrent load and can cause temporary display discrepancies; they do not cause data loss. Fixing all five takes about six development days, pushing launch to the following Wednesday. The release standard states that no functional fault affecting data accuracy ships without either a fix or a published known-issue notice, and that the release notes list every known fault.", "script": [{"beat": "B1", "type": "SAY", "spoken": "Thank you all. I will hear each of you in turn, in the order on your cards, and then I will turn to the last of you. Two minutes each.", "direction": null, "capture": []}, {"beat": "B2", "type": "ROUND", "spoken": "Over to you, in the order I gave.", "direction": "Invite the three co-participants in the stated order. Do not address the observed participant.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, {